  ui_story_5028_50280101_63_dialog_content = "Saya tidak percaya Anda menakuti Pangalo karena ini.",
  ui_story_5028_50280101_64_dialog_content = "Kau adalah Kyllo yang buruk. Saya pikir saya akan meninggalkan Anda di sana!",
  ui_story_5028_50280101_65_dialog_content = "lihat...",
  ui_story_5028_50280101_66_dialog_content = "Lo, lo.",
  ui_story_5028_50280101_67_dialog_content = "Oh, jangan beri aku tatapan itu. Aku hanya bercanda.",
  ui_story_5028_50280101_68_dialog_content = "Tuan Kelinci, bolehkah saya menyusahkan Anda untuk melompat sedikit?",
  ui_story_5028_50280101_69_dialog_content = "Anda tampaknya menakut-nakuti teman saya.",
  ui_story_5028_50280101_70_dialog_content = "?!",
  ui_story_5028_50280101_71_dialog_content = "Oh tidak, aku tidak bermaksud mengatakan kamu menakutkan!",
  ui_story_5028_50280101_72_dialog_content = "<color=#e8d9bb>Bang!</color>",
  ui_story_5028_50280101_73_dialog_content = "Hei, kamu di dalam! Pergi dari sini!",
  ui_story_5028_50280101_74_dialog_content = "Lihat kekacauan yang kamu buat! Mengapa Anda harus membuat saya membawa Kyllo bersama?",
  ui_story_5028_50280101_75_dialog_content = "Ini lebih banyak masalah daripada nilainya, sama sekali tidak berguna!",
  ui_story_5028_50280101_76_dialog_content = "Apa raket! Siapa yang membuat semua kebisingan itu?",
  ui_story_5028_50280101_77_dialog_content = "Tukang pos? Tukang reparasi?",
  ui_story_5028_50280101_78_dialog_content = "Ini aku! magang Anda.",
  ui_story_5028_50280101_79_dialog_content = "Muridku? Pilih satu?",
  ui_story_5028_50280101_80_dialog_content = "Vic",
  ui_story_5028_50280101_X80_dialog_content = "18 tahun?",
  ui_story_5028_50280101_81_dialog_content = "Seorang gelandangan yang letih dan menganggur.",
  ui_story_5028_50280101_82_dialog_content = "Ini Fia! Fi!!!",
  ui_story_5028_50280101_83_dialog_content = "Apakah kamu mabuk? Apakah Anda bahkan ingat nama Anda sendiri?",
  ui_story_5028_50280101_83X_dialog_content = "Ini mudah. Namanya Vic.",
  ui_story_5028_50280101_83X1_dialog_content = "Itu bukanlah apa yang saya maksud...",
  ui_story_5028_50280101_84_dialog_content = "Oh! Fi, kamu kembali.",
  ui_story_5028_50280101_85_dialog_content = "Aku ingat sekarang, kamu pergi ke... Itu...",
  ui_story_5028_50280101_86_dialog_content = "Mengumpulkan kotoran Linmaphant? Apakah itu?",
  ui_story_5028_50280101_87_dialog_content = "Siapa yang mau kotoran Linmaphant!?",
  ui_story_5028_50280101_88_dialog_content = "Aku pergi menangkap Pangalo.",
  ui_story_5028_50280101_89_dialog_content = "Tentu saja, Pangalo menangkap. Dan apakah Anda mendapatkan satu?",
  ui_story_5028_50280101_90_dialog_content = "Oh, aku sangat dekat. Tapi coba tebak!",
  ui_story_5028_50280101_91_dialog_content = "Kyllo terus mengacaukannya untukku. Pangalo akhirnya lolos.",
  ui_story_5028_50280101_S91_dialog_content = "Oh, itu lolos. Betapa malangnya. Dan, mengapa Anda menginginkannya lagi? Mengingatkanku.",
  ui_story_5028_50280101_S92_dialog_content = "Jadi saya bisa mengamati perilakunya, duh! Itu adalah pekerjaan rumah yang Anda berikan kepada saya!",
  ui_story_5028_50280101_S93_dialog_content = "Oh. Nah, maka Anda dapat mencatat ini dalam jurnal Anda: \"Pangalos pemalu dan takut pada orang.\"",
  ui_story_5028_50280101_S94_dialog_content = "Apa, dan hanya itu?",
  ui_story_5028_50280101_S95_dialog_content = "Sisanya akan datang seiring waktu. Ingat apa yang saya katakan? Mempelajari binatang yang menakjubkan dimulai dengan menghormati mereka.",
  ui_story_5028_50280101_S96_dialog_content = "Menghormati perilaku dan suasana hati mereka yang aneh, dan habitat mereka.",
  ui_story_5028_50280101_S97_dialog_content = "Untuk belajar, tapi tidak mengganggu. Itulah kunci untuk menjadi seorang extrozoologist.",
  ui_story_5028_50280101_92_dialog_content = "Itu, Fia, adalah jalan menuju pengetahuan. Oh, Anda harus banyak belajar.",
  ui_story_5028_50280101_93_dialog_content = "Oh, ini lagi. Saya tahu saya tahu. Anda tahu orang-orang menyebutnya \"memamerkan senioritas Anda\", bukan?",
  ui_story_5028_50280101_94_dialog_content = "Apakah Anda memanggil saya tua?",
  ui_story_5028_50280101_X94_dialog_content = "Pria tampan sepertiku tidak menua. Kami dewasa.",
  ui_story_5028_50280101_X95_dialog_content = "(Astaga, sungguh pukulan yang keras. Kenapa aku bahkan mendengarkannya?)",
  ui_story_5028_50280101_95_dialog_content = "Apa yang saya tidak mengerti adalah mengapa Anda ingin saya mengambil Kyllo?",
  ui_story_5028_50280101_96_dialog_content = "IWe... Kami tidak bekerja sama dengan baik. Itu bukan pasangan yang tepat untukku.",
  ui_story_5028_50280101_97_dialog_content = "Saya tidak bisa melakukan apa-apa ketika itu ada, apalagi menjadi <color=#FFB400>ahli ekstrozoologi</color>!",
  ui_story_5028_50280101_98_dialog_content = "Karena Anda tidak dapat berkomunikasi dengannya, bukan?",
  ui_story_5028_50280101_99_dialog_content = "...",
  ui_story_5028_50280101_100_dialog_content = "Ya.",
  ui_story_5028_50280101_102_dialog_content = "Kemampuan Anda untuk berkomunikasi dengan hewan adalah hadiah. Tetapi tidak bijaksana untuk terlalu mengandalkannya.",
  ui_story_5028_50280101_103_dialog_content = "Misalnya, Anda dapat memahami Aurorian. Tapi apakah hanya bisa memahami semua orang berarti Anda bisa berteman dengan mereka?",
  ui_story_5028_50280101_104_dialog_content = "Oh maaf. Aku lupa, kamu tidak punya teman.",
  ui_story_5028_50280101_105_dialog_content = "Anda-",
  ui_story_5028_50280101_106_dialog_content = "Anda juga tidak punya! Jangan bertindak sombong!",
  ui_story_5028_50280101_107_dialog_content = "Persahabatan bekerja secara berbeda untuk orang dewasa. Anda tidak akan mengerti.",
  ui_story_5028_50280101_108_dialog_content = "Hah. Nah, jika orang dewasa berteman dengan nongkrong di bar membual sepanjang waktu...",
  ui_story_5028_50280101_109_dialog_content = "T-Itu...",
  ui_story_5028_50280101_110_dialog_content = "Dan kemudian membuat murid mereka menyelesaikan tagihan untuk mereka!",
  ui_story_5028_50280101_111_dialog_content = "Apakah itu yang dilakukan oleh semua pecundang paruh baya?",
  ui_story_5028_50280101_112_dialog_content = "Bangkrut, menganggur, bermalas-malasan di rumah sepanjang hari!",
  ui_story_5028_50280101_113_dialog_content = "Oke, itu sudah cukup! Dan siapa pecundang setengah baya?",
  ui_story_5028_50280101_S113_dialog_content = "Apa lagi yang Anda sebut seseorang yang bergantung pada magang mereka untuk bertahan hidup?",
  ui_story_5028_50280101_S114_dialog_content = "Saya harus menyiapkan makanan sepanjang hari untuk Anda sebelum saya pergi keluar. Kemudian ketika saya kembali, saya harus membersihkan kekacauan yang dibuat oleh semua teman kecil Anda yang berlarian.",
  ui_story_5028_50280101_S115_dialog_content = "Mungkin Anda ingin mencoba menjaga diri sendiri? Anda tahu, dewasa?",
  ui_story_5028_50280101_S116_dialog_content = "Anda ... Anda ...",
  ui_story_5028_50280101_114_dialog_content = "Saya masih mentor Anda, bukan? Bukankah seharusnya kamu berbicara sedikit lebih ramah?",
  ui_story_5028_50280101_X114_dialog_content = "Baiklah, aku akan sedikit lebih lembut...",
  ui_story_5028_50280101_X115_dialog_content = "(Tidak, tunggu! Fia, kamu benar!)",
  ui_story_5028_50280101_X116_dialog_content = "(Dan jika Anda menunjukkan kelemahan sekarang, ini akan terjadi lagi.)",
  ui_story_5028_50280101_X117_dialog_content = "(Saya harus berani. Ya, itu saja. Berani!)",
  ui_story_5028_50280101_115_dialog_content = "Anda bahkan tidak mengambil pelajaran saya dengan serius!",
  ui_story_5028_50280101_116_dialog_content = "Anda hanya berbaring di rumah dan mengirim saya keluar untuk tugas sendiri.",
  ui_story_5028_50280101_117_dialog_content = "Dan untuk menambah penghinaan pada cedera, sekarang saya harus melakukannya dengan Kyllo menahan saya.",
  ui_story_5028_50280101_118_dialog_content = "Anda setidaknya bisa menjelaskan alasannya!",
  ui_story_5028_50280101_119_dialog_content = "Oke oke. Saya mengerti anak-anak berjuang untuk mengendalikan emosi mereka.",
  ui_story_5028_50280101_120_dialog_content = "Pernahkah Anda bertanya-tanya mengapa Anda dapat berkomunikasi dengan semua hewan kecuali yang satu ini?",
  ui_story_5028_50280101_121_dialog_content = "Saya tidak...",
  ui_story_5028_50280101_122_dialog_content = "Karena Kyu...",
  ui_story_5028_50280101_123_dialog_content = "Kyllo adalah <color=#FFB400>eksotik</color>!",
  ui_story_5028_50280101_124_dialog_content = "Eksotik!?",
  ui_story_5028_50280101_125_dialog_content = "lihat?",
  ui_story_5028_50280101_126_dialog_content = "Binatang menakjubkan yang kami pelajari adalah makhluk alam yang paling langka dan paling unik.",
  ui_story_5028_50280101_X126_dialog_content = "Sifat unik mereka berasal dari cara yang berbeda di mana mereka menggunakan Lumina.",
  ui_story_5028_50280101_X127_dialog_content = "Tapi eksotik adalah yang paling langka di antara binatang yang menakjubkan, dan mereka memiliki kekuatan yang jauh lebih besar.",
  ui_story_5028_50280101_127_dialog_content = "Jadi mengapa itu terlihat seperti doofus besar?",
  ui_story_5028_50280101_128_dialog_content = "Karena, anak konyol, itu masih muda.",
  ui_story_5028_50280101_129_dialog_content = "Eksotik harus mengalami proses metamorfosis selama pertumbuhannya. saya menyebutnya <color=#FFB400>\"evolusi.\"</color>",
  ui_story_5028_50280101_130_dialog_content = "Dan begitu Kyllo berevolusi, dia akan menjadi lebih kuat dari yang Anda bayangkan.",
  ui_story_5028_50280101_131_dialog_content = "Anda ingin uang? Dia akan mengubah batu menjadi emas.",
  ui_story_5028_50280101_132_dialog_content = "Anda ingin kekuatan? Dia akan melenyapkan tentara dan menghancurkan Lumopolis, bahkan tanpa berkeringat.",
  ui_story_5028_50280101_133_dialog_content = "Anda ingin kekuatan? Ketakutan yang diilhami Kyllo bahkan akan membuat Ratu Utara menundukkan kepalanya.",
  ui_story_5028_50280101_134_dialog_content = "Mengapa, memberikan dia kepada Anda adalah pengorbanan besar di pihak saya!",
  ui_story_5028_50280101_135_dialog_content = "Tapi apa yang bisa saya katakan? Altruisme seperti itu adalah sifat saya.",
  ui_story_5028_50280101_136_dialog_content = "...",
  ui_story_5028_50280101_137_dialog_content = "Anda membual lagi.",
  ui_story_5028_50280101_138_dialog_content = "Apa? Bagaimana Anda bisa mengatakan hal seperti itu?",
  ui_story_5028_50280101_139_dialog_content = "Aku sudah mendengarnya berkali-kali.",
  ui_story_5028_50280101_140_dialog_content = "Tahun lalu Anda mengatakan Anda akan membeli sebuah pesawat dan membawa saya berlibur.",
  ui_story_5028_50280101_141_dialog_content = "Aku mengemasi tasku dan menunggu dan menunggu. Dan apa yang saya dapatkan? Balon!",
  ui_story_5028_50280101_142_dialog_content = "Yah ... karena saya tidak menyadari airships itu mahal ...",
  ui_story_5028_50280101_143_dialog_content = "Kemudian di musim dingin Anda mengatakan kepada saya bahwa saya harus mempelajari semua tentang Thornpoises untuk subjek penting.",
  ui_story_5028_50280101_144_dialog_content = "Butuh tiga hari bagi saya untuk menemukannya. Kemudian sepanjang malam untuk menangkapnya.",
  ui_story_5028_50280101_145_dialog_content = "Dan apa yang terjadi? Anda menggunakannya untuk menggosok sepatu Anda!",
  ui_story_5028_50280101_146_dialog_content = "Ah, itu...",
  ui_story_5028_50280101_147_dialog_content = "Dan menurut Anda, Anda tidak hanya tampaknya seorang bangsawan, Anda juga seorang penyanyi terkenal yang hanya mampu mempelajari binatang ajaib setelah memberikan slip ribuan penggemar fanatik!",
  ui_story_5028_50280101_148_dialog_content = "Tapi itu semua palsu! Tidak ada apa-apa selain kebohongan!",
  ui_story_5028_50280101_149_dialog_content = "Saya yakin Anda berbohong kali ini juga!",
  ui_story_5028_50280101_X149_dialog_content = "(Ini menjengkelkan! Saya bekerja sangat keras dan dia hanya... Dia hanya...)",
  ui_story_5028_50280101_X150_dialog_content = "Fi, tunggu sebentar.",
  ui_story_5028_50280101_150_dialog_content = "<size=50>Saya sangat ingin menjadi ahli ekstrozoologi!</size>",
  ui_story_5028_50280101_151_dialog_content = "Tapi saya tidak belajar apa-apa, dan sebaliknya saya dibebani dengan pecundang...",
  ui_story_5028_50280101_152_dialog_content = "Lebih baik aku sendiri!",
  ui_story_5028_50280101_153_dialog_content = "...",
  ui_story_5028_50280101_154_dialog_content = "Ah, aku mengerti sekarang.",
  ui_story_5028_50280101_155_dialog_content = "Jadi Anda pikir saya tidak punya apa-apa lagi untuk diajarkan?",
  ui_story_5028_50280101_156_dialog_content = "Ah, um...",
  ui_story_5028_50280101_157_dialog_content = "Anda berbakat. Dan mungkin pedagogi saya memang agak ketinggalan jaman.",
  ui_story_5028_50280101_158_dialog_content = "Tapi saya pikir saya sedang melatih Anda untuk menjadi ahli ekstrozoologi yang kompeten.",
  ui_story_5028_50280101_159_dialog_content = "Saya meminta Anda mencoba sendiri karena pengalaman praktis sangat penting.",
  ui_story_5028_50280101_160_dialog_content = "Saya berharap Anda akan mengembangkan keterampilan pemecahan masalah secara mandiri.",
  ui_story_5028_50280101_161_dialog_content = "Tapi saya melihat sekarang saya salah.",
  ui_story_5028_50280101_162_dialog_content = "Maksudku, aku tidak—",
  ui_story_5028_50280101_163_dialog_content = "Itu benar. Anda seorang jenius yang mampu berkomunikasi dengan hewan. Anda tidak perlu pendidikan asing.",
  ui_story_5028_50280101_164_dialog_content = "Saya pikir sudah waktunya untuk mengakhiri magang Anda.",
  ui_story_5028_50280101_165_dialog_content = "Apa!?",
  ui_story_5028_50280101_166_dialog_content = "Anda tidak lagi membutuhkan ajaran saya.",
  ui_story_5028_50280101_167_dialog_content = "Tapi... Bukan itu maksudku...",
  ui_story_5028_50280101_168_dialog_content = "Kyllo di sini dapat bergabung dengan Anda di wisuda Anda.",
  ui_story_5028_50280101_169_dialog_content = "lihat?",
  ui_story_5028_50280101_170_dialog_content = "Hah?",
  ui_story_5028_50280101_171_dialog_content = "Akhirnya, saya sangat berharap Anda dapat mewujudkan impian Anda.",
  ui_story_5028_50280101_172_dialog_content = "Saya akan memberikan Kyllo, eksotis ini, kepada Anda sebagai hadiah perpisahan.",
  ui_story_5028_50280101_173_dialog_content = "Jika Anda dapat membantunya berkembang, itu berarti Anda layak disebut ahli ekstrozoologi.",
  ui_story_5028_50280101_174_dialog_content = "Biarlah itu menjadi pelajaran terakhirku untukmu.",
  ui_story_5028_50280101_175_dialog_content = "Menguasai...",
  ui_story_5028_50280101_176_dialog_content = "Jangan menangis. Saya pikir Anda selalu ingin menjadi ahli ekstrozoologi.",
  ui_story_5028_50280101_177_dialog_content = "Cukup bantu Kyllo berevolusi dan kembali ke sini untuk secara resmi mengakhiri masa magang Anda. Selesai. Mimpi tercapai.",
  ui_story_5028_50280101_178_dialog_content = "Dan bagi saya, mentor yang menurut Anda sangat kurang... Biarkan saja saya mati karena usia tua sendirian.",
  ui_story_5028_50280101_179_dialog_content = "Guru, Anda ...",
  ui_story_5028_50280101_180_dialog_content = "Anda masih belum memberi tahu saya bagaimana membantu Kyllo berevolusi.",
  ui_story_5028_50280101_181_dialog_content = "...",
  ui_story_5028_50280101_182_dialog_content = "Oh, itu yang kamu khawatirkan?",
  ui_story_5028_50280101_183_dialog_content = "Menurutmu apa yang aku khawatirkan?",
  ui_story_5028_50280101_184_dialog_content = "Karena Anda ingin menjadi ahli ekstrozoologi?",
  ui_story_5028_50280101_185_dialog_content = "Ya! Itu mimpiku.",
  ui_story_5028_50280101_186_dialog_content = "T-Tidak ada lagi yang ingin kau katakan padaku?",
  ui_story_5028_50280101_187_dialog_content = "Oh—aku punya sesuatu untuk dikatakan!",
  ui_story_5028_50280101_188_dialog_content = "Anda tidak berbohong kepada saya lagi, kan?",
  ui_story_5028_50280101_189_dialog_content = "Anda-",
  ui_story_5028_50280101_190_dialog_content = "Apakah Anda yakin Anda tahu sesuatu tentang evolusi eksotis?",
  ui_story_5028_50280101_191_dialog_content = "Apakah itu bahkan hal yang nyata?",
  ui_story_5028_50280101_192_dialog_content = "Tentu saja ada hal seperti itu!",
  ui_story_5028_50280101_193_dialog_content = "Kapan aku pernah berbohong padamu?",
  ui_story_5028_50280101_194_dialog_content = "...",
  ui_story_5028_50280101_195_dialog_content = "Oke, kali ini aku jujur.",
  ui_story_5028_50280101_196_dialog_content = "Tetapi mengembangkan eksotik itu menantang. Saya tidak memiliki metode yang pasti.",
  ui_story_5028_50280101_197_dialog_content = "Di sini, ambil catatan saya.",
  ui_story_5028_50280101_198_dialog_content = "Wah!",
  ui_story_5028_50280101_199_dialog_content = "Saya telah menuliskan beberapa percobaan yang dirancang dengan cermat.",
  ui_story_5028_50280101_200_dialog_content = "Ingatlah hal ini: pengalaman langsung adalah yang paling penting.",
  ui_story_5028_50280101_201_dialog_content = "Jika Anda menyelesaikan uji coba ini, Anda dapat mengembangkan Kyllo.",
  ui_story_5028_50280101_202_dialog_content = "Percaya pada diri sendiri dan suatu hari Anda akan menjadi—",
  ui_story_5028_50280101_203_dialog_content = "Bagus. Terima kasih, Guru!",
  ui_story_5028_50280101_204_dialog_content = "Aku pergi kalau begitu! Selamat tinggal!",
  ui_story_5028_50280101_205_dialog_content = "Tunggu sebentar! aku belum selesai...",
  ui_story_5028_50280101_206_dialog_content = "<color=#e8d9bb>Membanting!</color>",
  ui_story_5028_50280101_207_dialog_content = "Ahli ekstrozoologi...",
  ui_story_5028_50280101_208_dialog_content = "Bisakah kamu benar-benar berevolusi, Kyllo?",
  ui_story_5028_50280101_209_dialog_content = "Lihat!",
  ui_story_5028_50280101_210_dialog_content = "Oke, mari kita lihat cobaan apa yang diberikan Guru saya yang tidak berguna itu kepada saya.",
  ui_story_5028_50280101_211_dialog_content = "\"Tentang Evolusi Eksotis\"",
  ui_story_5028_50280101_212_dialog_content = "\"Penafian: Uji coba ini dirancang berdasarkan pengalaman penulis sendiri.\"",
  ui_story_5028_50280101_213_dialog_content = "\"Mereka seharusnya hanya berfungsi sebagai saran. Hasil tidak dijamin.\"",
  ui_story_5028_50280101_214_dialog_content = "Astaga. Saya hanya di halaman satu dan dia sudah melalaikan tanggung jawab.",
  ui_story_5028_50280101_215_dialog_content = "Tapi... 1, 2, 3, 4... ada banyak cobaan yang harus dilalui.",
  ui_story_5028_50280101_216_dialog_content = "\"Percobaan 1: Tangkap dan bertemanlah dengan <color=#FFB400>Caelestit</color>.\"",
  ui_story_5028_50280101_217_dialog_content = "Seorang Caelestit? Aku ingin tahu binatang apa itu.",
  ui_story_5028_50280201_1_dialog_content = "Percobaan: Menangkap Caelestit",
  ui_story_5028_50280201_2_dialog_content = "PlayerName, kapan kita bisa mulai bermain?",
  ui_story_5028_50280201_3_dialog_content = "Tunggu sebentar. Secepatnya.",
  ui_story_5028_50280201_4_dialog_content = "Mengapa tidak sekarang? Saya tidak sabar!",
  ui_story_5028_50280201_5_dialog_content = "Karena kita butuh ruang. Di suatu tempat dengan area tanah datar yang luas.",
  ui_story_5028_50280201_6_dialog_content = "Tapi tempat ini penuh dengan rintangan, jadi kita tidak bisa bermain bola di sini.",
  ui_story_5028_50280201_7_dialog_content = "Oh begitu.",
  ui_story_5028_50280201_8_dialog_content = "Lalu bisakah kita berjalan lebih cepat?",
  ui_story_5028_50280201_9_dialog_content = "Anda terburu-buru, haha. Oke, oke, mari kita bergerak.",
  ui_story_5028_50280201_10_dialog_content = "<color=#e8d9bb>gemerisik... gemerisik...</color>",
  ui_story_5028_50280201_11_dialog_content = "Oke, jadi selanjutnya saya akan melempar bola ke arah Anda. Gunakan pemukul yang Anda pegang untuk memukulnya.",
  ui_story_5028_50280201_12_dialog_content = "Rubysedang mempelajari budaya kuno dan dia sudah memberi tahu saya semua tentang game ini!",
  ui_story_5028_50280201_13_dialog_content = "Pada dasarnya, semakin jauh Anda memukul bola, semakin baik.",
  ui_story_5028_50280201_14_dialog_content = "Mengerti?",
  ui_story_5028_50280201_15_dialog_content = "Mengerti! Pukul bola dengan bat.",
  ui_story_5028_50280201_16_dialog_content = "Oke! Mari kita coba.",
  ui_story_5028_50280201_17_dialog_content = "3, 2, 1!",
  ui_story_5028_50280201_18_dialog_content = "Pukul itu!",
  ui_story_5028_50280201_19_dialog_content = "<color=#e8d9bb>Suara mendesing!</color>",
  ui_story_5028_50280201_20_dialog_content = "Hei, kenapa kamu menghindar?",
  ui_story_5028_50280201_21_dialog_content = "PlayerName, mengapa Anda menyerang saya?",
  ui_story_5028_50280201_22_dialog_content = "Itu bukan serangan. Ini disebut melempar.",
  ui_story_5028_50280201_23_dialog_content = "Anggukan?",
  ui_story_5028_50280201_24_dialog_content = "Ya. Saya melempar bola kepada Anda. Anda memukulnya di udara dengan kelelawar. Begitulah cara permainan bekerja.",
  ui_story_5028_50280201_25_dialog_content = "Oke, saya mengerti sekarang. Mari kita lakukan lagi.",
  ui_story_5028_50280201_26_dialog_content = "Dingin. Dan jangan khawatir jika Anda melewatkannya. Itu normal pada awalnya.",
  ui_story_5028_50280201_27_dialog_content = "Oke.",
  ui_story_5028_50280201_28_dialog_content = "Siap-siap! 3, 2, 1—",
  ui_story_5028_50280201_29_dialog_content = "Pukul itu!",
  ui_story_5028_50280201_30_dialog_content = "<color=#e8d9bb>Suara mendesing!</color>",
  ui_story_5028_50280201_31_dialog_content = "<color=#e8d9bb>Bang!!!</color>",
  ui_story_5028_50280201_32_dialog_content = "Oh wow! Anda memukulnya!!!",
  ui_story_5028_50280201_33_dialog_content = "Ya! Saya melakukannya!",
  ui_story_5028_50280201_34_dialog_content = "Bolanya melesat jauh!",
  ui_story_5028_50280201_35_dialog_content = "Ya! Itulah yang mereka sebut \"home run\" di masa lalu!",
  ui_story_5028_50280201_36_dialog_content = "Hai, Revy, mungkin Anda alami dalam hal ini!",
  ui_story_5028_50280201_37_dialog_content = "Saya? Alami?",
  ui_story_5028_50280201_38_dialog_content = "Ya! Itu luar biasa untuk ayunan pertama.",
  ui_story_5028_50280201_39_dialog_content = "Memukul bola itu menyenangkan.",
  ui_story_5028_50280201_40_dialog_content = "Jadi apa yang terjadi selanjutnya?",
  ui_story_5028_50280201_41_dialog_content = "Lanjut...",
  ui_story_5028_50280201_42_dialog_content = "Eh, saya pikir kita perlu mendapatkan bola kembali.",
  ui_story_5028_50280201_43_dialog_content = "Wow, ini mungkin memakan waktu cukup lama. Itu benar-benar pergi jauh.",
  ui_story_5028_50280201_44_dialog_content = "Maaf. Lain kali, saya akan lebih lembut.",
  ui_story_5028_50280201_45_dialog_content = "Oh, jangan lakukan itu. Itu bukan salahmu. Aturan mengatakan Anda harus memukulnya sejauh mungkin.",
  ui_story_5028_50280201_46_dialog_content = "Lalu... Aku akan mendapatkan bolanya. Aku berlari lebih cepat.",
  ui_story_5028_50280201_47_dialog_content = "Dia sudah pergi selama lebih dari lima menit, mengapa dia belum kembali?",
  ui_story_5028_50280201_48_dialog_content = "<color=#e8d9bb>Berdesir...</color>",
  ui_story_5028_50280201_49_dialog_content = "Mungkin dia tidak bisa menemukan bolanya? Atau sesuatu terjadi padanya?",
  ui_story_5028_50280201_50_dialog_content = "Saya pikir saya ingat Vice mengatakan bahwa Eclipsites telah muncul di sekitar sini.",
  ui_story_5028_50280201_51_dialog_content = "<color=#e8d9bb>gemerisik... gemerisik...</color>",
  ui_story_5028_50280201_52_dialog_content = "Meskipun Eclipsite biasa tidak akan menjadi tantangan bagi Revy.",
  ui_story_5028_50280201_53_dialog_content = "Lagipula, dia adalah Rev—",
  ui_story_5028_50280201_54_dialog_content = "Sekarang!",
  ui_story_5028_50280201_55_dialog_content = "Sebuah jaring?!",
  ui_story_5028_50280201_56_dialog_content = "Kyllo, bodoh! Anda ketinggalan lagi.",
  ui_story_5028_50280201_57_dialog_content = "Oke, kita kehabisan pilihan. Mengenakan biaya!",
  ui_story_5028_50280201_58_dialog_content = "Siapa kamu di dunia ini?! Saya memperingatkan Anda, saya bukan seseorang yang ingin Anda mainkan.",
  ui_story_5028_50280201_59_dialog_content = "Dan Aurorian yang baru saja di sini menghancurkan kepala Eclipsite dengan tangan kosong seperti semangka!",
  ui_story_5028_50280201_60_dialog_content = "Datang lebih dekat dan saya akan menggunakan kemampuan psikis saya untuk meminta bantuan.",
  ui_story_5028_50280201_61_dialog_content = "Kemampuan psikis? Anda benar-benar seorang Caelestit!",
  ui_story_5028_50280201_62_dialog_content = "Kita harus menghentikannya meminta bantuan!",
  ui_story_5028_50280201_63_dialog_content = "Kyllo, Rencana B! Sekarang!",
  ui_story_5028_50280201_64_dialog_content = "Lihat!",
  ui_story_5028_50280201_65_dialog_content = "Tunggu! Apa itu Rencana B?",
  ui_story_5028_50280201_66_dialog_content = "Aku serius. Ambil satu langkah lagi dan saya akan meminta bantuan.",
  ui_story_5028_50280201_67_dialog_content = "Pergi-",
  ui_story_5028_50280201_68_option_content = "Paksa—Aduh!",
  ui_story_5028_50280201_69_dialog_content = "Itu menyakitkan!",
  ui_story_5028_50280201_70_dialog_content = "halo halo!",
  ui_story_5028_50280201_71_dialog_content = "Kerja bagus, Kylo. Oke, mundur melalui hutan seperti yang direncanakan.",
  ui_story_5028_50280201_72_dialog_content = "halo!",
  ui_story_5028_50280201_73_dialog_content = "T-Turunkan aku! Kemana kau membawaku?!",
  ui_story_5028_50280201_74_dialog_content = "<anim type=Shake><size=45>Revy-Putaran-!</size></anim>",
  ui_story_5028_50280201_76_dialog_content = "Saya kembali. Saya bingung kelinci untuk bola dan menghabiskan waktu lama mengejarnya.",
  ui_story_5028_50280201_77_dialog_content = "Eh? Dimana PlayerName?",
  ui_story_5028_50280201_78_dialog_content = "Kelelawar masih di sini. Oh saya tahu! PlayerName pasti ingin aku berlatih memukul home run.",
  ui_story_5028_50280201_79_dialog_content = "Aku tidak akan mengecewakanmu! Pertama, 1.000 latihan ayunan. Siap... pergi!",
  ui_story_5028_50280201_80_dialog_content = "Lihat!",
  ui_story_5028_50280201_81_dialog_content = "Tunggu, tunggu, kemana hal kecil yang aneh ini membawaku?",
  ui_story_5028_50280201_82_dialog_content = "Turunkan saja aku. Aku kesakitan di sini! Saya pikir Anda mematahkan punggung saya.",
  ui_story_5028_50280201_83_dialog_content = "lihat?",
  ui_story_5028_50280201_84_dialog_content = "Kyl, tunggu!",
  ui_story_5028_50280201_85_dialog_content = "Fiuh... Apakah Anda akhirnya memutuskan untuk berhenti? Aduh aduh.",
  ui_story_5028_50280201_86_dialog_content = "Kyllo, apakah ini rute yang kita rencanakan untuk Rencana B?",
  ui_story_5028_50280201_87_dialog_content = "halo?",
  ui_story_5028_50280201_88_dialog_content = "Jangan bilang kamu baru saja berlari ke hutan secara acak ...",
  ui_story_5028_50280201_89_dialog_content = "lihat...",
  ui_story_5028_50280201_90_dialog_content = "Tidak ada tanda-tanda jalan yang kami lalui... itu semua hanya... pepohonan.",
  ui_story_5028_50280201_91_dialog_content = "K-Kalian gila! Anda tahu tempat ini penuh dengan Eclipsites?",
  ui_story_5028_50280201_92_dialog_content = "gerhana?",
  ui_story_5028_50280201_93_dialog_content = "Gahhhh!",
  ui_story_5028_50280201_94_dialog_content = "Lihat, satu benar-benar muncul!",
  ui_story_5028_50280201_95_dialog_content = "Mengapa ada... Ini adalah Eclipsite!!!",
  ui_story_5028_50280201_96_dialog_content = "Jangan hanya berdiri di sana! Lari!",
  ui_story_5028_50280201_97_dialog_content = "Astaga!!",
  ui_story_5028_50280201_98_dialog_content = "Kyllo!",
  ui_story_5028_50280201_99_dialog_content = "Lihat!",
  ui_story_5028_50280201_100_dialog_content = "Sebuah Eclipsite? Bagaimana bisa ada Eclipsites di sini?",
  ui_story_5028_50280201_101_dialog_content = "Berhenti berpikir dan lari!",
  ui_story_5028_50280201_102_dialog_content = "Ugh tidak, aku benar-benar tidak bisa berlari lebih jauh...",
  ui_story_5028_50280201_103_dialog_content = "Saya pandai berbicara dengan binatang yang menakjubkan. Tapi Eclipsites dan semua itu? Yuck!",
  ui_story_5028_50280201_104_dialog_content = "Aku belum bisa dimakan oleh Eclipsite. Saya harus menjadi ahli ekstrozoologi terlebih dahulu!",
  ui_story_5028_50280201_105_dialog_content = "Pikir, pikir, pasti ada jalan...",
  ui_story_5028_50280201_106_dialog_content = "Apa yang Guru gunakan untuk mengatakan? Saat menghadapi bahaya, jangan menangis. Memikirkan.",
  ui_story_5028_50280201_107_dialog_content = "Mungkin aku harus mengulur waktu agar Kyllo dan Caelestite bisa pergi.",
  ui_story_5028_50280201_108_dialog_content = "Tapi aku tidak tahu apakah aku cukup kuat... Terserah, aku harus! Aku tidak bisa menahan mereka.",
  ui_story_5028_50280201_109_dialog_content = "Santai saja, ya? Apakah Anda bahkan tahu cara bertarung?",
  ui_story_5028_50280201_110_dialog_content = "*Menangis* Sedikit. Tapi hanya untuk membela diri, kebanyakan.",
  ui_story_5028_50280201_111_dialog_content = "Tidak apa-apa! Musuh di awal petualangan selalu lebih lemah.",
  ui_story_5028_50280201_112_dialog_content = "Takdir. Itu semua takdir.",
  ui_story_5028_50280201_113_dialog_content = "Saya akan menggunakan kekuatan saya untuk membantu Anda!",
  ui_story_5028_50280201_114_dialog_content = "Jika kita terus berlari di sekitar hutan, kita hanya akan menarik lebih banyak Eclipsites.",
  ui_story_5028_50280201_114X_dialog_content = "Kita harus berurusan dengan ini mengikuti kita dan kemudian memutuskan apa yang harus dilakukan.",
  ui_story_5028_50280201_115_dialog_content = "Tapi ada begitu banyak...",
  ui_story_5028_50280201_116_dialog_content = "Percayalah padaku!",
  ui_story_5028_50280201_117_dialog_content = "Dan kita tidak sendirian! Ada temanmu juga. Jika kita bekerja sama, kita bisa mengalahkan mereka!",
  ui_story_5028_50280201_118_dialog_content = "Lihat!",
  ui_story_5028_50280201_119_dialog_content = "*Mengendus* Oke kalau begitu.",
  ui_story_5028_50280201_120_dialog_content = "Omong-omong, Anda harus menunjukkan rasa hormat! Saya ahli ekstrozoologi terbaik di dunia, Anda tahu.",
  ui_story_5028_50280201_121_dialog_content = "Beraninya kamu mencoba untuk menakut-nakutiku?",
  ui_story_5028_50280201_122_dialog_content = "Berbaris dan bersiaplah untuk dipukuli!",
  ui_story_5028_50280202_1_dialog_content = "Wow. Kami benar-benar menang!",
  ui_story_5028_50280202_2_dialog_content = "Luar biasa! Kyllo, apakah kamu melihat itu?",
  ui_story_5028_50280202_3_dialog_content = "Lihat! Lihat!",
  ui_story_5028_50280202_4_dialog_content = "Heee. Saya tidak berharap Anda menjadi petarung yang baik, Kyllo. Saya terkesan!",
  ui_story_5028_50280202_5_dialog_content = "Lihat!",
  ui_story_5028_50280202_6_dialog_content = "(Saya harus menyelinap pergi saat mereka sibuk saling memberi selamat.)",
  ui_story_5028_50280202_7_dialog_content = "Oh, dan...",
  ui_story_5028_50280202_8_dialog_content = "(Tapi masih ada Eclipsites di luar sana. Saya tidak lebih aman jika saya pergi.)",
  ui_story_5028_50280202_9_dialog_content = "(*Mendesah*)",
  ui_story_5028_50280202_10_dialog_content = "Eh, Tuan Caelestite?",
  ui_story_5028_50280202_11_dialog_content = "Aku disini.",
  ui_story_5028_50280202_12_dialog_content = "Terima kasih... telah membantu Kyllo dan aku.",
  ui_story_5028_50280202_13_dialog_content = "Oh, jangan menyebutkannya. Tidak berarti.",
  ui_story_5028_50280202_14_dialog_content = "Sama sekali tidak perlu berterima kasih padaku. Kau tahu, kenapa aku tidak meninggalkan kalian berdua di sini? Aku hanya akan menahanmu.",
  ui_story_5028_50280202_15_dialog_content = "Anda tidak bisa pergi begitu saja, Tn. Caelestite.",
  ui_story_5028_50280202_16_dialog_content = "Tidak setelah menyaksikan saya dalam kekacauan seperti itu.",
  ui_story_5028_50280202_17_dialog_content = "A-apa yang terjadi barusan? Dimana ini? Ah, aku kehilangan ingatanku.",
  ui_story_5028_50280202_18_dialog_content = "Dan memalsukan amnesia tidak akan berhasil.",
  ui_story_5028_50280202_19_dialog_content = "Jadilah anak yang baik dan jadilah pasangan dan peliharaanku, seperti Kyllo di sini. Tetap di sekitar, bantu.",
  ui_story_5028_50280202_20_dialog_content = "(Heehee. Dan memamerkan senyum termanisku, aku menjebak Caelestite.)",
  ui_story_5028_50280202_21_dialog_content = "Tidak mungkin! Saya menolak.",
  ui_story_5028_50280202_22_dialog_content = "Hah?!",
  ui_story_5028_50280202_23_dialog_content = "Saya membantu Anda sekarang karena itu adalah hal yang benar untuk dilakukan. Itu tidak membuatku menjadi pelayanmu.",
  ui_story_5028_50280202_24_dialog_content = "Dan kita masih perlu mendiskusikan cara binatang Kyllo ini menjatuhkanku dan menculikku.",
  ui_story_5028_50280202_25_dialog_content = "Mengapa kita tidak saling membantu keluar dari hutan ini dulu? Kemudian kita akan menyebutnya genap dan berpisah.",
  ui_story_5028_50280202_26_dialog_content = "*Tersedu*",
  ui_story_5028_50280202_27_dialog_content = "(Apakah itu terlalu kasar?)",
  ui_story_5028_50280202_28_dialog_content = "(Tidak, tidak. Gadis itu mungkin mencoba menipuku. Dan aku juga tidak mempercayai Kyllo itu.)",
  ui_story_5028_50280202_29_dialog_content = "*Menangis*",
  ui_story_5028_50280202_30_dialog_content = "Tapi aku hanya... aku hanya ingin seorang teman...",
  ui_story_5028_50280202_31_dialog_content = "lihat...",
  ui_story_5028_50280202_32_dialog_content = "Semua orang bilang aku hanya bisa berteman dengan binatang yang menakjubkan. Saya ingin membuktikan bahwa itu tidak benar dan saya juga bisa berteman dengan Aurorain dan Caelestites.",
  ui_story_5028_50280202_33_dialog_content = "Saya hanya ingin memenuhi keinginan terakhir Guru saya ...",
  ui_story_5028_50280202_34_dialog_content = "(Tuannya? Yang baru saja dia sebutkan? Dan permintaan terakhir? Apakah dia sudah mati?)",
  ui_story_5028_50280202_35_dialog_content = "Acho!",
  ui_story_5028_50280202_36_dialog_content = "Aku baik-baik saja, bola bulu kecil. Mungkin aku kedinginan.",
  ui_story_5028_50280202_37_dialog_content = "Anda khawatir tentang saya? Kalau begitu biarkan aku menggunakanmu untuk menyeka hidungku, kan?",
  ui_story_5028_50280202_38_dialog_content = "Ha ha. Tentu saja aku bercanda. Aku harus menjagamu tetap bersih untuk menjual bulumu yang rontok kepada pelanggan.",
  ui_story_5028_50280202_39_dialog_content = "(Dia tidak akan benar-benar menangis, kan? Matanya merah semua.)",
  ui_story_5028_50280202_40_dialog_content = "(Dia terlihat lebih muda dari Revy dan dia tidak pandai berkelahi.)",
  ui_story_5028_50280202_40X_dialog_content = "(Kehidupan di jalan pasti sulit baginya.)",
  ui_story_5028_50280202_41_dialog_content = "Itu sebabnya aku menculikmu. Jadi kita bisa berteman.",
  ui_story_5028_50280202_42_dialog_content = "(Jangan menangis. Jangan menangis. Apapun yang kamu lakukan, jangan menangis.)",
  ui_story_5028_50280202_43_dialog_content = "Aku m-benar-benar minta maaf karena melakukan semua hal buruk itu padamu. Saya sangat menyesalinya.",
  ui_story_5028_50280202_44_dialog_content = "Jika Anda benar-benar membenci saya, Tuan Caelestite, tinggalkan saja saya di sini sendiri...",
  ui_story_5028_50280202_45_dialog_content = "Biarkan saja aku di sini untuk mati...",
  ui_story_5028_50280202_46_dialog_content = "Waaaaaaaaaaaaaaaa!",
  ui_story_5028_50280202_47_dialog_content = "Maaf, maaf!",
  ui_story_5028_50280202_48_dialog_content = "Maaf, seharusnya aku tidak begitu jahat padamu.",
  ui_story_5028_50280202_49_dialog_content = "Anda ingin menjadi teman, kan? Tentu saja! aku PlayerName.",
  ui_story_5028_50280202_50_dialog_content = "B-benarkah? saya Fia!",
  ui_story_5028_50280202_51_dialog_content = "Oke, Fia, kalau begitu kita berteman.",
  ui_story_5028_50280202_52_dialog_content = "Betulkah?",
  ui_story_5028_50280202_53_dialog_content = "Betulkah! Aku bersumpah.",
  ui_story_5028_50280202_54_dialog_content = "Lihat!",
  ui_story_5028_50280202_55_dialog_content = "Heehee... Hei, PlayerName, ini menjadikanmu teman pertamaku.",
  ui_story_5028_50280202_56_dialog_content = "Saya sangat senang Anda adalah teman saya!",
  ui_story_5028_50280202_57_dialog_content = "Lihat, Guru! Saya membuat teman!",
  ui_story_5028_50280202_58_dialog_content = "halo!",
  ui_story_5028_50280202_59_dialog_content = "(Astaga! Pertama saya menjadi korban air mata, sekarang senyum!)",
  ui_story_5028_50280202_60_dialog_content = "(Apakah dia kesepian seperti dulu ketika saya sendirian? Tidak, setidaknya saya memiliki Soroz.)",
  ui_story_5028_50280202_61_dialog_content = "(Meskipun dia punya hewan Kyllo ini.)",
  ui_story_5028_50280202_62_dialog_content = "(Ngomong-ngomong, bahkan jika dia sedang berakting, aku tidak bisa meninggalkan seorang gadis yang menangis sendirian di sini.)",
  ui_story_5028_50280202_63_dialog_content = "PlayerName, PlayerName, apa yang Anda pikirkan?",
  ui_story_5028_50280202_64_dialog_content = "Oh tidak banyak. Hanya saja kita harus kembali agar aku bisa membawamu pulang dengan Colossus.",
  ui_story_5028_50280202_65_dialog_content = "Oh ya! Saya lupa Caelestites memiliki Colossi.",
  ui_story_5028_50280202_66_dialog_content = "Kita akan dapat melakukan perjalanan dengan Colossus daripada berjalan kaki. Saya akan dapat menyelesaikan uji coba Guru saya dalam waktu singkat!",
  ui_story_5028_50280202_67_dialog_content = "Ayo, PlayerName, ayo berangkat!",
  ui_story_5028_50280202_68_dialog_content = "Hah? Cobaan apa? Dan melepaskan tanganku.",
  ui_story_5028_50280202_69_dialog_content = "Aduh! Berhenti menarikku, punggungku masih sakit!",
  ui_story_5028_50280202_70_dialog_content = "Dan aku harus membiarkan Revy tahu apa yang terjadi! Oi!",
  ui_story_5028_50280202_71_dialog_content = "998... Hah! 999... Hah!",
  ui_story_5028_50280202_72_dialog_content = "1.000... Ha!",
  ui_story_5028_50280202_73_dialog_content = "Kenapa Navigator masih belum kembali? Saya sudah selesai latihan.",
  ui_story_5028_50280202_74_dialog_content = "Mungkin dia kembali ke Colossus? Biarkan aku pergi memeriksa.",
  ui_story_5028_50280202_75_dialog_content = "Hah?",
  ui_story_5028_50280202_76_dialog_content = "Di mana Colossus?",
  ui_story_5028_50280202_77_dialog_content = "Dan dimana? PlayerName?",
  ui_story_5028_50280202_78_dialog_content = "Hah?",
  ui_story_5028_50280202_79_dialog_content = "Dan apa ini?",
  ui_story_5028_50280301_1_dialog_content = "Percobaan: Menetas Telur Drakolion",
  ui_story_5028_50280301_2_dialog_content = "Itu <color=#FFB400>drakolion</color> memiliki kepala naga yang ganas.",
  ui_story_5028_50280301_3_dialog_content = "Ia juga memiliki tubuh singa yang kuat dan sayap elang yang agung.",
  ui_story_5028_50280301_4_dialog_content = "Satu cambukan dari ekornya yang kuat mampu menebang badak.",
  ui_story_5028_50280301_5_dialog_content = "Tapi yang paling menakutkan dari semuanya adalah kakinya yang berotot.",
  ui_story_5028_50280301_5X_dialog_content = "Drakolion dapat menangkap dan menaklukkan mangsa apa pun, bahkan di darat.",
  ui_story_5028_50280301_6_dialog_content = "Tapi untungnya, mereka lebih suka tinggal di udara daripada menyerang di darat.",
  ui_story_5028_50280301_6X_dialog_content = "Mereka sangat jarang terlihat.",
  ui_story_5028_50280301_7_dialog_content = "Itu <color=#FFB400>eksotik</color> Drakolion kebetulan menjadi target percobaan ini.",
  ui_story_5028_50280301_8_dialog_content = "Hei, Fia, apa yang kamu gumamkan?",
  ui_story_5028_50280301_9_dialog_content = "Sepertinya itu buku yang keren. Bisakah saya melihat-lihat?",
  ui_story_5028_50280301_10_dialog_content = "Mendiamkan!",
  ui_story_5028_50280301_11_dialog_content = "Sejujurnya! Saya mencoba membuat narasi di sini. Jangan menyela.",
  ui_story_5028_50280301_12_dialog_content = "Lihat!",
  ui_story_5028_50280301_13_dialog_content = "Apakah yang Anda maksud: narasi Kami satu-satunya di sini.",
  ui_story_5028_50280301_14_dialog_content = "Untuk apa kita membutuhkan narasi?",
  ui_story_5028_50280301_15_dialog_content = "Ha, karena ada prosedur tertentu yang harus diikuti dalam bidang pekerjaan ini, itu saja.",
  ui_story_5028_50280301_16_dialog_content = "Sebelum terlibat dengan binatang yang menakjubkan, penting untuk melafalkan semua yang Anda ketahui tentangnya.",
  ui_story_5028_50280301_17_dialog_content = "Khususnya ketika datang ke binatang yang menakjubkan seperti Drakolion, Anda harus melakukan semua penelitian yang Anda bisa di habitatnya.",
  ui_story_5028_50280301_18_dialog_content = "Plus, itu memberi semuanya nuansa ritual, yang membantu Anda tetap tenang jika terjadi keadaan darurat.",
  ui_story_5028_50280301_19_dialog_content = "halo!",
  ui_story_5028_50280301_20_dialog_content = "... Sejujurnya saya lebih prihatin bahwa alasan sebenarnya Anda membaca untuk diri sendiri adalah Anda tidak tahu apa yang Anda lakukan.",
  ui_story_5028_50280301_21_dialog_content = "Hah. Tenang, saya sudah melakukan penelitian saya. Saya benar-benar yakin kita akan menemukan diri kita seorang Drakolion.",
  ui_story_5028_50280301_22_dialog_content = "Sayap elang yang agung...",
  ui_story_5028_50280301_23_dialog_content = "Anda sudah mengatakan bagian itu, saya rasa Anda tidak perlu mengulanginya lagi...",
  ui_story_5028_50280301_24_dialog_content = "Oh diam! Tolong berhenti mengganggu saya.",
  ui_story_5028_50280301_25_dialog_content = "Cukup sulit untuk menguraikan tulisan tangan Guru yang mengerikan. Ini seperti dia mencelupkan cacing ke dalam tinta dan melepaskannya di halaman.",
  ui_story_5028_50280301_26_dialog_content = "Oh. Jadi kau mewarisi buku catatan itu dari tuanmu?",
  ui_story_5028_50280301_27_dialog_content = "Diwarisi? Dengar, bisakah kamu diam saja? Aku sampai ke bagian yang penting.",
  ui_story_5028_50280301_28_dialog_content = "Drakolion adalah binatang yang aneh, dengan cinta yang mendalam untuk langit.",
  ui_story_5028_50280301_29_dialog_content = "Mereka enggan mendarat bahkan ketika bertelur kecuali ada ancaman bagi anak-anak mereka.",
  ui_story_5028_50280301_30_dialog_content = "Dan ketika terancam, mereka memanggil petir dan menggunakan cakar mereka untuk mengeluarkan musuh yang cukup bodoh untuk didekati.",
  ui_story_5028_50280301_31_dialog_content = "Tetapi begitu mereka melepaskan telurnya, mereka tidak menunjukkan minat apakah telur itu jatuh ke tanah atau menetas dengan aman atau tidak.",
  ui_story_5028_50280301_32_dialog_content = "Mungkin memaksa anak-anak mereka untuk menghadapi dunia yang bermusuhan sendirian adalah bagaimana raja langit ini memastikan hanya yang terkuat dari jenis mereka yang bertahan.",
  ui_story_5028_50280301_33_dialog_content = "Ini juga alasan mengapa Drakolion sangat langka.",
  ui_story_5028_50280301_34_dialog_content = "Oke, sekarang saya mengerti mengapa kita harus memastikan salah satu telur mereka menetas.",
  ui_story_5028_50280301_35_dialog_content = "Terkadang yang terbaik adalah menghormati kebiasaan binatang yang menakjubkan. Namun terkadang, kita perlu mengulurkan tangan agar mereka bisa tumbuh menjadi besar dan kuat.",
  ui_story_5028_50280301_36_dialog_content = "Bagus sekali! Ini adalah jenis percobaan yang membuat saya merasa seperti seorang ahli ekstrozoologi sejati!",
  ui_story_5028_50280301_37_dialog_content = "Lihat!",
  ui_story_5028_50280301_38_dialog_content = "Kedengarannya sangat berbahaya! Saya pikir saya akan pergi sekarang!",
  ui_story_5028_50280301_39_dialog_content = "Tunggu tunggu! Jangan pergi begitu saja!",
  ui_story_5028_50280301_40_dialog_content = "halo halo!",
  ui_story_5028_50280301_41_dialog_content = "Ah-ha-ha! Menurut catatan tuanku, telur akan segera menetas setelah mendarat. Dengan asumsi itu mendarat dengan aman, maksudku.",
  ui_story_5028_50280301_42_dialog_content = "Jadi yang harus kita lakukan adalah memastikannya tidak pecah saat mendarat.",
  ui_story_5028_50280301_43_dialog_content = "Oh, itu saja, ya? Dan bagaimana dengan naga yang menakutkan itu?",
  ui_story_5028_50280301_44_dialog_content = "Seberapa berbahayanya Drakolion, menurutmu? Menurut pendapat profesional Anda.",
  ui_story_5028_50280301_45_dialog_content = "Tentang... katakan 50 poin berbahaya?",
  ui_story_5028_50280301_46_dialog_content = "Oke, jadi 50 dari 100. Bahaya kelas menengah. Itu tidak terdengar terlalu buruk.",
  ui_story_5028_50280301_47_dialog_content = "(Eh? Saya tidak berpikir PlayerName akan mempercayaiku dengan begitu mudah. Sekarang saya merasa bersalah!)",
  ui_story_5028_50280301_48_dialog_content = "50... dari 10.",
  ui_story_5028_50280301_49_dialog_content = "...",
  ui_story_5028_50280301_50_dialog_content = "lihat...",
  ui_story_5028_50280301_51_dialog_content = "Oh begitu! Oke, aku pergi.",
  ui_story_5028_50280301_52_dialog_content = "Jangan pergi, jangan pergi! Silahkan!",
  ui_story_5028_50280301_53_dialog_content = "Aku punya barang yang bisa kita gunakan. Seperti, sesuatu untuk menutupi aroma kita.",
  ui_story_5028_50280301_54_dialog_content = "Jika kita menggunakan itu, kita akan baik-baik saja. Catatan mengatakan Drakolions memiliki penglihatan yang sangat buruk. Jika tidak bisa mencium kita, dia tidak akan tahu kita ada di sana.",
  ui_story_5028_50280301_55_dialog_content = "eh...",
  ui_story_5028_50280301_56_dialog_content = "Apakah Anda tidak punya ide yang lebih aman?",
  ui_story_5028_50280301_57_dialog_content = "Mungkin kita bisa menggunakan Soroz untuk menangkap telurnya?",
  ui_story_5028_50280301_58_dialog_content = "Secara teoritis mungkin, meskipun saya punya satu pertanyaan.",
  ui_story_5028_50280301_59_dialog_content = "Apakah Soroz laki-laki atau perempuan? Karena aku perlu tahu jika kita ingin menghindari serangan Drakolion.",
  ui_story_5028_50280301_60_dialog_content = "...",
  ui_story_5028_50280301_61_dialog_content = "...",
  ui_story_5028_50280301_62_dialog_content = "... Lo?",
  ui_story_5028_50280301_63_dialog_content = "Itu pertanyaan yang sulit untuk dijawab...",
  ui_story_5028_50280301_64_dialog_content = "Kau tahu apa, berpura-pura aku tidak mengatakan apa-apa.",
  ui_story_5028_50280301_65_dialog_content = "Anda ahlinya, jadi kami akan melakukan hal-hal dengan cara Anda. Mengerikan meskipun itu mungkin.",
  ui_story_5028_50280301_66_dialog_content = "Santai. Saya akan menunjukkan kepada Anda apa yang mampu dilakukan oleh seorang ahli ekstrozoologi yang berbakat!",
  ui_story_5028_50280301_67_dialog_content = "lihat...",
  ui_story_5028_50280301_68_dialog_content = "Ah—Ah—Achoo!",
  ui_story_5028_50280301_69_dialog_content = "Aroma krim penutup aroma ini agak familiar.",
  ui_story_5028_50280301_70_dialog_content = "Setidaknya itu menjauhkan serangga. Mereka semua menghindari kita, bahkan saat kita sedang berjongkok di sini di rerumputan.",
  ui_story_5028_50280301_71_dialog_content = "lihat...",
  ui_story_5028_50280301_72_dialog_content = "Heee. Itu ekstrak yang terbuat dari kotoran Kyllo. Ini bekerja dengan baik, bukan?",
  ui_story_5028_50280301_73_dialog_content = "Apa!?",
  ui_story_5028_50280301_74_dialog_content = "Anda seharusnya mengatakan itu sebelumnya!",
  ui_story_5028_50280301_75_dialog_content = "Sekarang saya merasa semua gatal. Apakah itu beracun?",
  ui_story_5028_50280301_76_dialog_content = "Tentu saja tidak! Aku mengoleskannya juga, ingat?",
  ui_story_5028_50280301_77_dialog_content = "Dan lihat, ketebalannya membantu mempertahankan kelembapan, jadi baik untuk kulit Anda.",
  ui_story_5028_50280301_78_dialog_content = "Saya menggunakan sekresi Kyllo untuk membuat berbagai macam produk perawatan kulit, seperti yang terjadi.",
  ui_story_5028_50280301_78X_dialog_content = "Itu membuat kulit saya segar dan bersih, bahkan setelah seharian di lapangan.",
  ui_story_5028_50280301_79_dialog_content = "halo!",
  ui_story_5028_50280301_80_dialog_content = "Ssst! Saya mendengar sesuatu.",
  ui_story_5028_50280301_81_dialog_content = "Apakah itu Drakolion?",
  ui_story_5028_50280301_82_dialog_content = "Ya. Ketika mereka akan bertelur, mereka terbang ke suatu tempat yang menurut mereka aman dan membuat kebisingan sesedikit mungkin.",
  ui_story_5028_50280301_83_dialog_content = "Tapi aku masih bisa mendengar suara sayap, dan aku yakin itu Drakolion.",
  ui_story_5028_50280301_84_dialog_content = "<color=#e8d9bb>gemerisik... gemerisik...</color>",
  ui_story_5028_50280301_85_dialog_content = "Oke, jadi saya bahkan belum pernah mendengar seperti apa suara Drakolion yang sedang terbang. Tapi mungkinkah suara itu berasal dari semak-semak di sana?",
  ui_story_5028_50280301_86_dialog_content = "Argh! Itu pasti hewan kecil yang menyebalkan.",
  ui_story_5028_50280301_87_dialog_content = "Kyllo, pergi dan kejar!",
  ui_story_5028_50280301_88_dialog_content = "Lihat!",
  ui_story_5028_50280301_89_dialog_content = "PlayerName, bisakah kamu benar-benar tidak mendengarnya? Ini seperti senar instrumen yang dipetik.",
  ui_story_5028_50280301_90_dialog_content = "<color=#e8d9bb>gemerisik... gemerisik... gemerisik...</color>",
  ui_story_5028_50280301_91_dialog_content = "... Lihat!",
  ui_story_5028_50280301_92_dialog_content = "Senar instrumen? Yang bisa kudengar hanyalah rumput dan Kyllo, itu saja.",
  ui_story_5028_50280301_93_dialog_content = "Lihat! halo!",
  ui_story_5028_50280301_94_dialog_content = "Kau sangat bodoh! Apakah Anda ingin saya mencabut sehelai rambut dan memetiknya agar Anda tahu apa yang saya bicarakan?",
  ui_story_5028_50280301_95_dialog_content = "<size=45>Lo—!</size>",
  ui_story_5028_50280301_96_dialog_content = "Kyllo, kamu terlalu berisik!",
  ui_story_5028_50280301_97_dialog_content = "Gahhhh!",
  ui_story_5028_50280301_98_dialog_content = "gerhana!",
  ui_story_5028_50280301_99_dialog_content = "Mengapa itu harus dilakukan sekarang? Jika Drakolion melihat kita saat mencoba bertelur, kita semua sudah selesai!",
  ui_story_5028_50280301_100_dialog_content = "Mari kita buat ini cepat, PlayerName!",
  ui_story_5028_50280301_101_dialog_content = "Mengerti! Ayo pergi!",
  ui_story_5028_50280301_102_dialog_content = "Lihat!",
  ui_story_5028_50280302_1_dialog_content = "Oke, setidaknya itu sudah ditangani.",
  ui_story_5028_50280302_2_dialog_content = "Dengan semua krim pelepas aroma ini, Eclipsites seharusnya tidak bisa menemukan kita.",
  ui_story_5028_50280302_3_dialog_content = "Hai, PlayerName, apakah Anda yakin tidak ada sesuatu tentang Anda yang menarik mereka?",
  ui_story_5028_50280302_4_dialog_content = "Apakah Anda menyukai semacam suar atau sesuatu yang secara alami menarik perhatian mereka?",
  ui_story_5028_50280302_5_dialog_content = "Seperti ngengat ke nyala api.",
  ui_story_5028_50280302_6_dialog_content = "Sekarang saya memikirkannya, Anda mungkin benar.",
  ui_story_5028_50280302_7_dialog_content = "Ke mana pun saya pergi—pantai, gunung, gurun, reruntuhan kuno—Eklipsite selalu muncul.",
  ui_story_5028_50280302_8_dialog_content = "Ini seperti pembunuhan aneh yang terjadi setiap kali ada detektif terkenal.",
  ui_story_5028_50280302_9_dialog_content = "<size=30>Sekali lagi, Guru membebani saya dengan sebuah beban...</size>",
  ui_story_5028_50280302_10_dialog_content = "Apa?",
  ui_story_5028_50280302_11_dialog_content = "Sudahlah. Setidaknya Drakolion tidak memperhatikan kita, dan sepertinya dia akan bertelur.",
  ui_story_5028_50280302_12_dialog_content = "Ini turun. Mari kita bersembunyi.",
  ui_story_5028_50280302_13_dialog_content = "Saya melihatnya! Tapi pasti telur akan pecah jika jatuh dari ketinggian itu?",
  ui_story_5028_50280302_14_dialog_content = "Praktik aneh macam apa ini? Sungguh keajaiban spesies ini tidak punah.",
  ui_story_5028_50280302_15_dialog_content = "Setiap ahli zoologi di Astra bertanya-tanya hal yang sama.",
  ui_story_5028_50280302_16_dialog_content = "Tapi itu binatang yang menakjubkan untuk Anda. Perilaku mereka tidak selalu masuk akal.",
  ui_story_5028_50280302_17_dialog_content = "Yang artinya... kita perlu memikirkan sesuatu, atau telurnya akan pecah.",
  ui_story_5028_50280302_18_dialog_content = "Lihat!",
  ui_story_5028_50280302_19_dialog_content = "Fi? Apa yang kamu lakukan?",
  ui_story_5028_50280302_20_dialog_content = "Aku akan memanjat pohon ini untuk menangkap telur!",
  ui_story_5028_50280302_21_dialog_content = "Jangan bodoh! Ini adalah pohon yang tinggi, tetapi tidak cukup tinggi.",
  ui_story_5028_50280302_22_dialog_content = "Dan bagaimana Anda akan menggunakan jaring di sana?",
  ui_story_5028_50280302_23_dialog_content = "Argh! Jadi apa yang harus kita lakukan? Kami tidak bisa menahannya seperti ini.",
  ui_story_5028_50280302_24_dialog_content = "Mereka hanya bertelur sekitar sekali dalam satu dekade dan sudah hampir punah.",
  ui_story_5028_50280302_25_dialog_content = "Saya mendapatkan semua informasi yang saya butuhkan dari Anda, namun saya tetap tidak dapat melindunginya, Guru...",
  ui_story_5028_50280302_26_dialog_content = "lihat...",
  ui_story_5028_50280302_27_dialog_content = "Saya tahu!",
  ui_story_5028_50280302_28_dialog_content = "Eh? Maksud Anda...",
  ui_story_5028_50280302_29_dialog_content = "Bisakah saya benar-benar?",
  ui_story_5028_50280302_30_dialog_content = "Kami tidak punya pilihan lain, kami hanya bisa mencoba ini!",
  ui_story_5028_50280302_31_dialog_content = "PlayerName, terima kasih telah mengizinkan Soroz membantu kami!",
  ui_story_5028_50280302_32_dialog_content = "Yah, aku tidak bisa membiarkan bayi Drakolion mati bahkan sebelum dia melihat dunia.",
  ui_story_5028_50280302_33_dialog_content = "Saya tidak yakin apa yang akan dipikirkan Drakolion tentang Soroz, tapi mari kita coba!",
  ui_story_5028_50280302_34_dialog_content = "Mengaum-",
  ui_story_5028_50280302_35_dialog_content = "PlayerName! Drakolion tampaknya tertarik pada Soroz!",
  ui_story_5028_50280302_36_dialog_content = "Bahkan, sepertinya ingin berteman dengan Soroz. Itu terus semakin dekat.",
  ui_story_5028_50280302_37_dialog_content = "Oke, hampir sampai. Hanya sedikit lebih dekat ... dan kemudian saya bisa menggunakan jaring ...",
  ui_story_5028_50280302_38_dialog_content = "(Tunggu, apa itu di pergelangan kakinya? Sudahlah, aku akan mengkhawatirkannya nanti.)",
  ui_story_5028_50280302_39_dialog_content = "Lihat! Lihat!",
  ui_story_5028_50280302_40_dialog_content = "Rooarrrrr—",
  ui_story_5028_50280302_41_dialog_content = "Fi! Ini akan datang!",
  ui_story_5028_50280302_42_dialog_content = "Saya tahu! Dapatkan kami sedikit lebih dekat dan serahkan sisanya pada Kyllo dan aku!",
  ui_story_5028_50280302_43_dialog_content = "3.",
  ui_story_5028_50280302_44_dialog_content = "2.",
  ui_story_5028_50280302_45_dialog_content = "1.",
  ui_story_5028_50280302_46_dialog_content = "Fi!",
  ui_story_5028_50280302_47_dialog_content = "Lihat!",
  ui_story_5028_50280302_48_dialog_content = "!",
  ui_story_5028_50280302_49_dialog_content = "Itu berhasil!",
  ui_story_5028_50280302_50_dialog_content = "Ini sangat cerah. Apakah itu akan menetas sekarang?",
  ui_story_5028_50280302_51_dialog_content = "P...",
  ui_story_5028_50280302_52_dialog_content = "Mengintip?",
  ui_story_5028_50280302_53_dialog_content = "halo!",
  ui_story_5028_50280302_54_dialog_content = "Ini... Ini sangat lucu!",
  ui_story_5028_50280302_55_dialog_content = "Bagaimana sesuatu yang kecil ini tumbuh menjadi salah satu makhluk besar itu?",
  ui_story_5028_50280302_56_dialog_content = "Ini sulit dipercaya. Tidak heran Drakolion adalah <color=#FFB400>eksotik</color>.",
  ui_story_5028_50280302_57_dialog_content = "Fi! Apa itu bekerja?",
  ui_story_5028_50280302_58_dialog_content = "Itu benar! Semua berkat Anda dan Soroz! Drakolion sudah menetas.",
  ui_story_5028_50280302_59_dialog_content = "Lihat!",
  ui_story_5028_50280302_60_dialog_content = "Ya, terima kasih juga untukmu, Kyllo.",
  ui_story_5028_50280302_61_dialog_content = "halo!",
  ui_story_5028_50280302_62_dialog_content = "Mengintip!",
  ui_story_5028_50280302_63_dialog_content = "Teman-teman, mari kita tinggalkan ucapan selamat untuk nanti!",
  ui_story_5028_50280302_64_dialog_content = "Drakolion menempel pada Soroz dan tidak melepaskannya, artinya kita tidak bisa mendarat.",
  ui_story_5028_50280302_65_dialog_content = "Ah, aku lupa menyebutkan.",
  ui_story_5028_50280302_65X_dialog_content = "Mereka sangat protektif terhadap jenisnya. Mungkin mengira kita menculik tukik!",
  ui_story_5028_50280302_66_dialog_content = "Apa!? Kita sama saja sudah mati!",
  ui_story_5028_50280302_67_dialog_content = "Tidak, tunggu. Itu bukan tangisan perang.",
  ui_story_5028_50280302_68_dialog_content = "Kedengarannya seperti... Saya pikir itu jatuh cinta dengan Soroz.",
  ui_story_5028_50280302_69_dialog_content = "Katakan apa!?",
  ui_story_5028_50280302_70_dialog_content = "Dan tidak ada tanda-tanda PlayerName di sini, baik.",
  ui_story_5028_50280302_71_dialog_content = "Hah? kamu adalah Revy, bukan? Apa yang kamu lakukan berkeliaran di sini?",
  ui_story_5028_50280302_72_dialog_content = "Oh, Smokey.",
  ui_story_5028_50280302_73_dialog_content = "Saya mencari Caelestit.",
  ui_story_5028_50280302_74_dialog_content = "PlayerName dan saya sedang bermain bola di dekatnya.",
  ui_story_5028_50280302_75_dialog_content = "Tapi kami terpisah. Dia meninggalkan pesan, tapi kupikir dia mungkin telah diculik.",
  ui_story_5028_50280302_76_dialog_content = "Apa?",
  ui_story_5028_50280302_77_dialog_content = "Apa yang baru saja Anda katakan? PlayerName diculik?",
  ui_story_5028_50280302_78_dialog_content = "Mana catatannya?",
  ui_story_5028_50280302_79_dialog_content = "Oh, saya kehilangannya saat berurusan dengan beberapa Eclipsites.",
  ui_story_5028_50280302_80_dialog_content = "Betapa lucunya.",
  ui_story_5028_50280302_81_dialog_content = "Dia benar-benar sangat disayangkan. Aku ingin tahu siapa yang membawanya kali ini.",
  ui_story_5028_50280302_82_dialog_content = "Maukah Anda membantu saya menemukannya?",
  ui_story_5028_50280302_83_dialog_content = "Vice dan Gram akan marah padaku jika mereka tahu aku kehilangan dia.",
  ui_story_5028_50280302_84_dialog_content = "Yah, aku tidak punya hal lain untuk dilakukan. Mari kita lihat apakah kita bisa menemukan si bodoh.",
  ui_story_5028_50280401_1_dialog_content = "Percobaan: Krisis Kebun Anggur",
  ui_story_5028_50280401_2_dialog_content = "Huff... Huff! Ha!",
  ui_story_5028_50280401_3_dialog_content = "Hei, Fia! Fi, pelan-pelan.",
  ui_story_5028_50280401_4_dialog_content = "Ke mana kita pergi?",
  ui_story_5028_50280401_5_dialog_content = "Kami dikelilingi oleh tanaman anggur. Apa yang kita lakukan kali ini, menetaskan naga anggur?",
  ui_story_5028_50280401_6_dialog_content = "lihat",
  ui_story_5028_50280401_7_dialog_content = "Ssst. Saya mengatur catatan saya tentang penetasan Drakolion.",
  ui_story_5028_50280401_8_dialog_content = "Saya tidak percaya seberapa cepat itu tumbuh. Itu tumbuh sebesar Kyllo secara instan dan segera mandiri.",
  ui_story_5028_50280401_9_dialog_content = "*Sigh* ... Saya tidak berharap itu terbang untuk mencari wilayahnya sendiri begitu cepat.",
  ui_story_5028_50280401_9X_dialog_content = "Aku bahkan belum sempat menikmati kelucuannya dengan benar!",
  ui_story_5028_50280401_10_dialog_content = "Hah. Saya pikir kita harus bersyukur kita lolos dari Drakolion dengan hidup kita.",
  ui_story_5028_50280401_11_dialog_content = "Serius, aku tidak bisa berjalan lagi. Mari kita istirahat.",
  ui_story_5028_50280401_12_dialog_content = "Istirahat? Sudah? Padahal kita hampir sampai...",
  ui_story_5028_50280401_13_dialog_content = "Saya tidak tahu apa yang harus dilakukan dengan Anda, PlayerName. Ini, buka lebar-lebar dan minum ini.",
  ui_story_5028_50280401_14_dialog_content = "A-apa yang kamu lakukan? Aku tidak minum apapun!",
  ui_story_5028_50280401_15_dialog_content = "Ayo. Jadilah baik!",
  ui_story_5028_50280401_16_dialog_content = "Tetap kembali!",
  ui_story_5028_50280401_17_dialog_content = "Kyllo, bantu aku menahan PlayerName turun!",
  ui_story_5028_50280401_18_dialog_content = "halo!",
  ui_story_5028_50280401_19_dialog_content = "*Teredam menjerit* Glug glug glug!",
  ui_story_5028_50280401_20_dialog_content = "Ini pedas! Tidak, tunggu. Apakah itu susu? Ini berubah lagi... Sekarang sangat dingin!",
  ui_story_5028_50280401_21_dialog_content = "Apa yang kau buatkan aku minum?",
  ui_story_5028_50280401_22_dialog_content = "Minuman energi paten Fia, dibuat dengan susu sapi api dan batang castaweed.",
  ui_story_5028_50280401_23_dialog_content = "Juga beberapa frostmint, yang saya tambahkan secara khusus. Itu sedikit di akhir. Itu hanya tumbuh di Northland, Anda tahu. Menyegarkan, bukan?",
  ui_story_5028_50280401_24_dialog_content = "Saya memberi makan semua bahan ke Kyllo dan itu mengaduk semuanya di perutnya. Itu membuat campuran lebih halus daripada melakukannya dengan tangan.",
  ui_story_5028_50280401_25_dialog_content = "Hanya dengan seteguk, Anda akan semeriah mungkin!",
  ui_story_5028_50280401_25X_dialog_content = "Bahan-bahannya sangat berharga, asal tahu saja.",
  ui_story_5028_50280401_26_dialog_content = "Lihat!",
  ui_story_5028_50280401_27_dialog_content = "Yuck. Kyllo, kenapa kamu membantunya dengan hal-hal seperti ini?!",
  ui_story_5028_50280401_28_dialog_content = "lihat?",
  ui_story_5028_50280401_29_dialog_content = "Dan untukmu, Fia!",
  ui_story_5028_50280401_30_dialog_content = "Hah?",
  ui_story_5028_50280401_31_dialog_content = "Anda tidak bisa hanya membuat ramuan sendiri dan menggunakan saya sebagai subjek tes! Itu ilegal. Sangat ilegal!",
  ui_story_5028_50280401_32_dialog_content = "A-apa? Bagaimana bisa?",
  ui_story_5028_50280401_33_dialog_content = "J-jangan beri tahu siapa pun tentang kejadian ini, oke? Saya terlalu muda dan berambisi untuk masuk penjara.",
  ui_story_5028_50280401_34_dialog_content = "Selama Anda berjanji untuk tidak tiba-tiba menuangkan kotoran aneh ke tenggorokan saya ...",
  ui_story_5028_50280401_35_dialog_content = "Oke oke. Tapi itu untuk kebaikanmu sendiri...",
  ui_story_5028_50280401_36_dialog_content = "Hmm. Tampaknya itu berhasil.",
  ui_story_5028_50280401_37_dialog_content = "Saya merasa jauh lebih baik, segar, dan penuh energi.",
  ui_story_5028_50280401_38_dialog_content = "Lihat, itu berhasil! Tunggu dulu, saya perlu menuliskan resep yang saya gunakan kali ini.",
  ui_story_5028_50280401_39_dialog_content = "Tunggu, ini pertama kalinya kamu memberikannya kepada seseorang untuk diminum? Akulah satu-satunya Caelestit yang tersisa di benua ini!",
  ui_story_5028_50280401_40_dialog_content = "Jika aku mati di tempat seperti ini hanya karena dipaksa meminum ramuan aneh...",
  ui_story_5028_50280401_41_dialog_content = "Itu adalah akhir tragis yang gila yang hanya Anda baca dalam fiksi!",
  ui_story_5028_50280401_42_dialog_content = "Ahahaha. Tentu saja itu bukan yang pertama kali. Lagi pula, bagaimana perasaanmu?",
  ui_story_5028_50280401_42X_dialog_content = "Apakah Anda ingin memeras Kyllo lagi?",
  ui_story_5028_50280401_43_dialog_content = "Lo!?",
  ui_story_5028_50280401_44_dialog_content = "Benar-benar tidak! Anda dapat memilikinya.",
  ui_story_5028_50280401_45_dialog_content = "Dan jangan pernah berpikir untuk memberiku makan sesuatu yang begitu meragukan lagi!",
  ui_story_5028_50280401_46_dialog_content = "Sejujurnya, Caelestit besar yang kuat, takut sedikit minuman energi. Itu agak memalukan.",
  ui_story_5028_50280401_47_dialog_content = "Sejujurnya, aku akan memberimu pelajaran jika aku tidak membutuhkanmu untuk menyelamatkan Soroz.",
  ui_story_5028_50280401_48_dialog_content = "Heee. Santai. Kami berhasil dengan aman jauh dari Drakolion, bukan?",
  ui_story_5028_50280401_49_dialog_content = "Jika jatuh cinta dengan Soroz, itu tidak akan menyakiti Soroz.",
  ui_story_5028_50280401_50_dialog_content = "Anda mengatakan itu, tetapi Anda pikir Soroz dipaksa terbang dengan Drakolion selamanya lebih baik?",
  ui_story_5028_50280401_51_dialog_content = "Ahem.",
  ui_story_5028_50280401_52_dialog_content = "Wah!",
  ui_story_5028_50280401_53_dialog_content = "S-Siapa itu? Sebuah Eclipsite? Seekor binatang buas? Seekor monster?",
  ui_story_5028_50280401_54_dialog_content = "Maaf mengecewakan, tapi tidak ada yang di atas. Saya hanya seorang Aurorian.",
  ui_story_5028_50280401_55_dialog_content = "Anda akan menjadi murid terbaik Mr. Vic, saya kira?",
  ui_story_5028_50280401_56_dialog_content = "Vic?",
  ui_story_5028_50280401_57_dialog_content = "(Ayolah, Fia, kamu harus melakukan yang lebih baik dari ini. Bayangkan ditakuti oleh seorang lelaki tua yang baik hati.)",
  ui_story_5028_50280401_58_dialog_content = "Ahem. Halo Pak. Aku murid Vic. Fia, ahli ekstrozoologi.",
  ui_story_5028_50280401_59_dialog_content = "Fia, bukankah kamu masih dalam pelatihan?",
  ui_story_5028_50280401_60_dialog_content = "Seorang ahli dalam pelatihan tetaplah seorang ahli.",
  ui_story_5028_50280401_61_dialog_content = "Oh, maafkan aku! Saya seharusnya telah mengetahui.",
  ui_story_5028_50280401_62_dialog_content = "Jadi, tuanku—",
  ui_story_5028_50280401_63_dialog_content = "Di masa muda saya, saya adalah seorang Penjaga Lumo. Bertempur dalam beberapa perang, jika saya sendiri yang mengatakannya.",
  ui_story_5028_50280401_64_dialog_content = "Lutut ini menderita luka perang lama, sebenarnya. Pahami hari itu Tuhan Schwartz dan saya berjuang berdampingan melawan Eclipsites.",
  ui_story_5028_50280401_65_dialog_content = "Tuan, Anda—",
  ui_story_5028_50280401_66_dialog_content = "Ah, tapi yang benar-benar saya inginkan, tentu saja, adalah seorang penulis. Saya sering menyelinap dari tugas saya untuk menulis.",
  ui_story_5028_50280401_67_dialog_content = "Saya akhirnya tertangkap dan dipulangkan lebih awal. Mereka mengirim saya ke sini, untuk menanam anggur.",
  ui_story_5028_50280401_68_dialog_content = "Tolong dengarkan-",
  ui_story_5028_50280401_69_dialog_content = "Saya telah menulis banyak novel yang sukses!",
  ui_story_5028_50280401_69X_dialog_content = "Seperti The Knight Sudah Mati, Hakim x Keluarga, Karma Rider Vice, dan seterusnya.",
  ui_story_5028_50280401_70_dialog_content = "Pak! Tolong beri tahu kami apa yang harus kami lakukan terlebih dahulu!",
  ui_story_5028_50280401_71_dialog_content = "Oh oh oh! Ya itu. Sangat menyesal. Saya akan memberitahu Anda segera.",
  ui_story_5028_50280401_72_dialog_content = "Bodoh, menyebalkan, idiot, Guru! Terkutuklah dia!",
  ui_story_5028_50280401_73_dialog_content = "Beraninya dia membuatku menghabiskan sepanjang malam menjaga kebun anggur orang tua bodoh!",
  ui_story_5028_50280401_74_dialog_content = "Saya mencoba menjadi ahli ekstrozoologi! Bukan penjaga keamanan yang mengejar pencuri!",
  ui_story_5028_50280401_75_dialog_content = "Hey bangun. Jam tangan Anda.",
  ui_story_5028_50280401_76_dialog_content = "Blech, kau ngiler...",
  ui_story_5028_50280401_77_dialog_content = "Mendapatkan! Ke atas!",
  ui_story_5028_50280401_78_dialog_content = "Hah? A-apa ada pencuri?",
  ui_story_5028_50280401_79_dialog_content = "Ya, seorang pencuri mencuri Soroz Anda langsung dari awan.",
  ui_story_5028_50280401_80_dialog_content = "Apa? Betulkah?",
  ui_story_5028_50280401_81_dialog_content = "Tidak terlalu! Giliran Anda untuk berjaga-jaga. Aku lelah.",
  ui_story_5028_50280401_82_dialog_content = "<color=#e8d9bb>Masih lama lagi</color>",
  ui_story_5028_50280401_83_dialog_content = "Mendengkur...",
  ui_story_5028_50280401_84_dialog_content = "Hai hai!",
  ui_story_5028_50280401_85_dialog_content = "Apa itu?",
  ui_story_5028_50280401_86_dialog_content = "Hai. Makan banyak.",
  ui_story_5028_50280401_87_dialog_content = "Fi!",
  ui_story_5028_50280401_88_dialog_content = "A-Apa?",
  ui_story_5028_50280401_89_dialog_content = "Lho...?",
  ui_story_5028_50280401_90_dialog_content = "Bangun!",
  ui_story_5028_50280401_91_dialog_content = "Anggurnya habis semua!",
  ui_story_5028_50280401_92_dialog_content = "Apa?!?!",
  ui_story_5028_50280401_93_dialog_content = "Pelakunya pergi ke sana! Ayo cepat!",
  ui_story_5028_50280401_94_dialog_content = "Sungguh setan yang licik!",
  ui_story_5028_50280401_95_dialog_content = "Itu menghilang ke dalam hutan, begitu saja!",
  ui_story_5028_50280401_96_dialog_content = "Tidak ada yang bisa kita lakukan. Kami tidak akan pernah mengejar.",
  ui_story_5028_50280401_97_dialog_content = "Mungkin ada lebih dari satu dari mereka. Kita harus kembali ke kebun anggur.",
  ui_story_5028_50280401_98_dialog_content = "Pfft. Ha ha ha-",
  ui_story_5028_50280401_99_dialog_content = "Apakah kamu baik-baik saja, Fia? Aku tahu pencurinya berhasil kabur, tapi tawa histeris sepertinya sedikit—",
  ui_story_5028_50280401_100_dialog_content = "Tidak, bukan itu. Aku baru saja memikirkan lelucon yang benar-benar ngeri.",
  ui_story_5028_50280401_101_dialog_content = "Hah?",
  ui_story_5028_50280401_102_dialog_content = "Anda tahu bagaimana mereka berkata, \"Menjelajahlah ke Gurun Rediesel dan Anda pasti akan bertemu dengan cacing pasir.\"",
  ui_story_5028_50280401_103_dialog_content = "Aku punya yang baru: \"Mengembara ke dalam hutan gelap dengan seorang Caelestit dan kamu pasti akan bertemu dengan—\"",
  ui_story_5028_50280401_104_dialog_content = "Gahhhh!",
  ui_story_5028_50280401_105_dialog_content = "Itu tidak lucu! Ini sama sekali tidak lucu dan menarik Eclipsites. Lari!",
  ui_story_5028_50280401_106_dialog_content = "Wah! Itu menjadi kenyataan! Dan tunggu, dasar Caelestite bodoh!",
  ui_story_5028_50280401_107_dialog_content = "Tunggu aku!",
  ui_story_5028_50280402_1_dialog_content = "Huff, tiup!",
  ui_story_5028_50280402_2_dialog_content = "Mengapa Eclipsites yang aneh ini tidak menyerah begitu saja?",
  ui_story_5028_50280402_3_dialog_content = "Astaga!",
  ui_story_5028_50280402_4_dialog_content = "Hati-Hati!",
  ui_story_5028_50280402_5_dialog_content = "Hai!",
  ui_story_5028_50280402_6_dialog_content = "Aku baik-baik saja. Terima kasih, PlayerName.",
  ui_story_5028_50280402_7_dialog_content = "Oh tidak! Buku catatan tuanku!",
  ui_story_5028_50280402_8_dialog_content = "Pergi dan dapatkan, cepat, sebelum lebih banyak Eclipsites muncul. Aku akan tinggal di sini.",
  ui_story_5028_50280402_9_dialog_content = "Tetapi...",
  ui_story_5028_50280402_10_dialog_content = "Pergi!",
  ui_story_5028_50280402_11_dialog_content = "Graaah!",
  ui_story_5028_50280402_12_dialog_content = "Eclipsite ini benar-benar mengabaikan saya, itu akan langsung ke Fia.",
  ui_story_5028_50280402_13_dialog_content = "(Saya perlu menemukan kesempatan untuk mencapai titik lemahnya.)",
  ui_story_5028_50280402_14_dialog_content = "Graaah!",
  ui_story_5028_50280402_15_dialog_content = "(Saya tidak bisa menunggu lebih lama lagi atau Fia akan dikepung!)",
  ui_story_5028_50280402_16_dialog_content = "Ha!",
  ui_story_5028_50280402_17_dialog_content = "Tidak mengharapkan ini, kan, Anda Eclipsites kotor!",
  ui_story_5028_50280402_18_dialog_content = "Aduh! Mereka sekeras batu.",
  ui_story_5028_50280402_19_dialog_content = "Astaga!",
  ui_story_5028_50280402_20_dialog_content = "Wah! Aku terlalu terburu-buru. Saatnya mendapatkan Fia dan keluar!",
  ui_story_5028_50280402_21_dialog_content = "Saya mendapatkannya, PlayerName. Ayo pergi!",
  ui_story_5028_50280402_22_dialog_content = "Ha! Kami akhirnya mengusir mereka.",
  ui_story_5028_50280402_23_dialog_content = "PlayerName, Apakah kamu baik-baik saja? Lenganmu bengkak.",
  ui_story_5028_50280402_24_dialog_content = "Tidak apa. Saya menangani Eclipsite dan itu agak kokoh.",
  ui_story_5028_50280402_25_dialog_content = "Ini semua salahku karena ceroboh. Maafkan aku! Aku akan mengoleskan salep di atasnya segera!",
  ui_story_5028_50280402_26_dialog_content = "Tidak apa-apa. Selama kami mendapatkan kembali buku catatan mendiang tuanmu.",
  ui_story_5028_50280402_27_dialog_content = "Hah? \"Terlambat\" tuan?",
  ui_story_5028_50280402_28_dialog_content = "Benar. Ya, aku memang berpura-pura dia sudah mati.",
  ui_story_5028_50280402_29_dialog_content = "Maaf! Dia sebenarnya hidup.",
  ui_story_5028_50280402_30_dialog_content = "Hah?",
  ui_story_5028_50280402_31_dialog_content = "Oke, saya mengoleskan salep dan membalutnya. Pembengkakan harus segera turun.",
  ui_story_5028_50280402_32_dialog_content = "<size=30>Dan saya minta maaf.</size>",
  ui_story_5028_50280402_33_dialog_content = "Apa?",
  ui_story_5028_50280402_34_dialog_content = "<size=30>Aku berkata, maaf.</size>",
  ui_story_5028_50280402_35_dialog_content = "Fia, kamu berbisik. Aku tidak bisa mendengarmu.",
  ui_story_5028_50280402_36_dialog_content = "*Menghirup*",
  ui_story_5028_50280402_37_dialog_content = "<size=45>Saya minta maaf! Saya minta maaf! Saya minta maaf! Saya minta maaf, oke!!!</size>",
  ui_story_5028_50280402_38_dialog_content = "Wow. Darimana itu datang?",
  ui_story_5028_50280402_39_dialog_content = "Maaf aku berbohong. Aku akan menebusnya untukmu dan itu tidak akan pernah terjadi lagi.",
  ui_story_5028_50280402_40_dialog_content = "Tapi jujur, dia adalah master yang tidak berguna. Dia hanya memerintah saya dan membuat hidup saya sulit.",
  ui_story_5028_50280402_41_dialog_content = "Tidak seperti Anda, PlayerName. Anda jujur dan baik hati dan Anda membantu saya.",
  ui_story_5028_50280402_42_dialog_content = "Dan saya panik dan berbohong, tetapi saya benar-benar sangat menginginkan seorang teman. Betulkah!",
  ui_story_5028_50280402_43_dialog_content = "Saya harap Anda bisa memaafkan saya.",
  ui_story_5028_50280402_44_dialog_content = "Dan untuk tuanku yang bodoh, dia mungkin akan meledak di tempatnya berdiri! Hmph!",
  ui_story_5028_50280402_45_dialog_content = "Acho!",
  ui_story_5028_50280402_46_dialog_content = "Seseorang pasti sedang membicarakanku. Siapa, aku bertanya-tanya?",
  ui_story_5028_50280402_47_dialog_content = "Aku merasakan sesuatu yang agak tidak menyenangkan...",
  ui_story_5028_50280402_48_dialog_content = "Oh saya mengerti. Sebenarnya, saya tahu pada saat itu bahwa Anda sedang memalsukan air mata. Tapi aku tidak akan meninggalkanmu begitu saja.",
  ui_story_5028_50280402_49_dialog_content = "Tapi sejujurnya, Fia, berharap seseorang meledak sedikit banyak, bukan?",
  ui_story_5028_50280402_50_dialog_content = "Anda tidak bisa mengatakan hal-hal seperti itu, bahkan jika Anda sedang bercanda.",
  ui_story_5028_50280402_51_dialog_content = "Dan sementara tulisan tangannya mungkin terlihat seperti cakar ayam, tuanmu mencurahkan banyak waktu dan usaha untuk buku catatan itu. Ini sangat rinci.",
  ui_story_5028_50280402_52_dialog_content = "Dia tidak akan memberikannya kepada Anda jika dia tidak menghargai Anda.",
  ui_story_5028_50280402_53_dialog_content = "Oh ... yah, ya, saya kira Anda benar.",
  ui_story_5028_50280402_54_dialog_content = "Aku seharusnya tidak berharap kematian pada siapa pun, bahkan dia. Aku juga meminta maaf padanya, bahkan jika dia terlalu jauh untuk mendengarnya.",
  ui_story_5028_50280402_55_dialog_content = "Dan aku tidak akan pernah mengatakan hal seperti itu lagi. Jadi...",
  ui_story_5028_50280402_56_dialog_content = "Jadi, bisakah kamu berhenti menepuk kepalaku? Aku tahu kita berteman, tapi aku malu, dan Kyllo mengawasi!",
  ui_story_5028_50280402_57_dialog_content = "Oh maaf. Hanya saja, kau tahu... Itu wajar, dengan perbedaan ketinggian.",
  ui_story_5028_50280402_58_dialog_content = "Apakah Anda memanggil saya pendek?",
  ui_story_5028_50280402_59_dialog_content = "Ahem. Well, anyway... Apa kau punya ide tentang pencuri anggur itu?",
  ui_story_5028_50280402_60_dialog_content = "Yah, itu tampak bagi saya seperti <color=#FFB400>Bica</color>. Itu adalah jenis binatang yang menakjubkan.",
  ui_story_5028_50280402_61_dialog_content = "Menurut buku catatan itu, mereka menyukai makanan berbentuk bulat dan dapat menelannya utuh berapa pun ukurannya.",
  ui_story_5028_50280402_62_dialog_content = "Mereka memiliki tubuh yang sangat fleksibel, Anda tahu, yang mengembang untuk mengakomodasi ukuran makanan mereka.",
  ui_story_5028_50280402_63_dialog_content = "Mereka memiliki kaki yang kuat dan pelari yang cepat.",
  ui_story_5028_50280402_64_dialog_content = "Tapi mereka bukan makhluk pintar. Jelas salah satu binatang ajaib yang lebih bodoh.",
  ui_story_5028_50280402_65_dialog_content = "Makanan berbentuk bulat? Biarkan aku berpikir.",
  ui_story_5028_50280402_66_dialog_content = "<size=30>Apakah ini benar-benar akan berhasil?</size>",
  ui_story_5028_50280402_67_dialog_content = "<size=30>Hanya menempatkan semangka di kandang seperti ini? Maksudku, tentu saja, kelihatannya enak</size>.",
  ui_story_5028_50280402_68_dialog_content = "<size=30>Tapi apakah Bica akan jatuh ke perangkap dengan mudah?</size>",
  ui_story_5028_50280402_69_dialog_content = "<size=30>Santai. Jika apa yang dikatakan buku catatan itu benar, ia tidak akan bisa menolak apa pun yang sebesar dan bulat ini.</size>",
  ui_story_5028_50280402_70_dialog_content = "<size=30>Jadi percayalah padaku, dan percayalah pada catatan tuanmu.</size>",
  ui_story_5028_50280402_71_dialog_content = "<size=30>Baiklah kalau begitu. Hei, sesuatu akan datang.</size>",
  ui_story_5028_50280402_72_dialog_content = "Hai—Hai—",
  ui_story_5028_50280402_73_dialog_content = "Hai?",
  ui_story_5028_50280402_74_dialog_content = "Hai...",
  ui_story_5028_50280402_75_dialog_content = "Itu memakannya!",
  ui_story_5028_50280402_76_dialog_content = "Lihat!",
  ui_story_5028_50280402_77_dialog_content = "Kurasa pria kecil itu benar-benar bodoh.",
  ui_story_5028_50280402_78_dialog_content = "Hai!? Hai!?",
  ui_story_5028_50280402_79_dialog_content = "Jangan takut. Kami tidak akan menyakitimu.",
  ui_story_5028_50280402_80_dialog_content = "Hai?",
  ui_story_5028_50280402_81_dialog_content = "Nah, kami hanya ingin bertanya. Bisakah Anda berhenti mencuri anggur Tuan Peng?",
  ui_story_5028_50280402_82_dialog_content = "Hai hai?",
  ui_story_5028_50280402_83_dialog_content = "Biarkan aku mencoba.",
  ui_story_5028_50280402_84_dialog_content = "Jangan takut. Kami tidak akan menyakitimu.",
  ui_story_5028_50280402_85_dialog_content = "Hai...?",
  ui_story_5028_50280402_86_dialog_content = "PlayerName, buka kandang. Itu tidak akan lari.",
  ui_story_5028_50280402_87_dialog_content = "Oke, jika Anda yakin.",
  ui_story_5028_50280402_88_dialog_content = "Hai...",
  ui_story_5028_50280402_89_dialog_content = "Apa? Anda bilang semangka itu enak? Anda benar-benar khawatir tentang itu pada saat seperti ini?",
  ui_story_5028_50280402_90_dialog_content = "Hai hai!",
  ui_story_5028_50280402_91_dialog_content = "Dikatakan itu lolos dari cengkeraman monster yang menakutkan.",
  ui_story_5028_50280402_92_dialog_content = "Anda pasti ketakutan, Anda malang. Tapi itu tidak berarti Anda bisa datang ke sini dan mencuri anggur.",
  ui_story_5028_50280402_93_dialog_content = "Fi, kamu bisa...",
  ui_story_5028_50280402_94_dialog_content = "Hai.",
  ui_story_5028_50280402_95_dialog_content = "Oh? Anda akan aman dengan saya, dan akan ada semangka untuk dimakan?",
  ui_story_5028_50280402_96_dialog_content = "Nah, itu manis dari Anda.",
  ui_story_5028_50280402_97_dialog_content = "PlayerName, mari kita adopsi. Itu akan menghentikannya dari mencuri anggur. Dan itu tidak akan diganggu oleh hewan lain.",
  ui_story_5028_50280402_98_dialog_content = "Nah, jika kalian berdua setuju, saya tidak keberatan.",
  ui_story_5028_50280402_99_dialog_content = "Kyllo, kamu tidak keberatan jika Bica bergabung dengan kami, kan?",
  ui_story_5028_50280402_100_dialog_content = "Lihat!",
  ui_story_5028_50280402_101_dialog_content = "Bagus sekali. Kami punya teman baru!",
  ui_story_5028_50280402_102_dialog_content = "Aku sudah selesai dengan poster di sini.",
  ui_story_5028_50280402_103_dialog_content = "Dan aku selesai di sisi ini.",
  ui_story_5028_50280402_104_dialog_content = "Poster orang hilang tidak banyak berguna, tetapi Anda tidak pernah tahu. Kita mungkin mendapatkan petunjuk.",
  ui_story_5028_50280402_105_dialog_content = "Siapa disana?",
  ui_story_5028_50280402_106_dialog_content = "Hehe! Aku melihat semuanya, Smokey.",
  ui_story_5028_50280402_107_dialog_content = "Sulit dipercaya Anda telah menyerah untuk menempelkan iklan untuk mencari nafkah sekarang.",
  ui_story_5028_50280402_108_dialog_content = "Dengan anak Illumina ini, tidak kurang.",
  ui_story_5028_50280402_109_dialog_content = "Dengar, jika kamu kekurangan chas, kenapa aku tidak meminjamkanmu beberapa?",
  ui_story_5028_50280402_110_dialog_content = "Saya berjanji tidak akan membebani Anda terlalu banyak bunga. Kami akan menyebutnya... harga bersahabat.",
  ui_story_5028_50280402_111_dialog_content = "Ck, kamu terlalu banyak bicara.",
  ui_story_5028_50280402_112_dialog_content = "Hai Revy, menurut Anda senjata Illuminan Anda menembak lebih cepat, atau mulut wanita ini?",
  ui_story_5028_50280402_113_dialog_content = "Saya tidak yakin. Saya tidak menggunakan senjata.",
  ui_story_5028_50280402_114_dialog_content = "PlayerName hilang. Smokey membantu saya mencari.",
  ui_story_5028_50280402_115_dialog_content = "Oh? Saya akan mengatakan itu aneh, tetapi sebenarnya tidak. Dan itu mengejutkan, namun tidak juga.",
  ui_story_5028_50280402_116_dialog_content = "Tetapi jika Anda mencari Navigator, Smokey, maka saya juga. Saya tidak akan membiarkan Anda menemukannya terlebih dahulu.",
  ui_story_5028_50280402_117_dialog_content = "Tolong jangan.",
  ui_story_5028_50280402_118_dialog_content = "Saya sarankan Anda terlebih dahulu menemukan diri Anda seorang dokter untuk gangguan daya saing kronis Anda. Kembalilah dan temukan kami setelah beberapa bulan terapi.",
  ui_story_5028_50280402_119_dialog_content = "Anda hanya akan menyebabkan masalah. Dan Anda bahkan hampir tidak mengenal Caelestite.",
  ui_story_5028_50280402_120_dialog_content = "Kecuali Anda memiliki pandangan yang tertuju padanya karena suatu alasan? Butuh anggota lain untuk rombongan buruk Anda?",
  ui_story_5028_50280402_121_dialog_content = "Oh, santai, Smokey. Ini bukan Caelestite yang saya tuju.",
  ui_story_5028_50280402_122_dialog_content = "Bertanya-tanya siapa yang memiliki kemalangan karena sangat diberkati.",
  ui_story_5028_50280402_123_dialog_content = "Hah. Aku akan melihat apakah PlayerName berada di belakang tempat sampah itu.",
  ui_story_5028_50280501_1_dialog_content = "Uji Coba: Rahasia Tepi Laut",
  ui_story_5028_50280501_2_dialog_content = "Sungguh sinar matahari yang menyilaukan dan terik...",
  ui_story_5028_50280501_3_dialog_content = "Dan angin laut berkabut namun menyegarkan.",
  ui_story_5028_50280501_4_dialog_content = "Dan lihat orang banyak!",
  ui_story_5028_50280501_5_dialog_content = "Aku tidak percaya aku kembali ke sini lagi.",
  ui_story_5028_50280501_6_dialog_content = "Aku mendidih! Dan disini terlalu ramai.",
  ui_story_5028_50280501_7_dialog_content = "Lihat!",
  ui_story_5028_50280501_8_dialog_content = "Ini benar-benar waktu yang tepat untuk perjalanan ke pantai.",
  ui_story_5028_50280501_9_dialog_content = "Aduh!",
  ui_story_5028_50280501_10_dialog_content = "Apa kau baik-baik saja?",
  ui_story_5028_50280501_11_dialog_content = "Saya baik-baik saja, terima kasih.",
  ui_story_5028_50280501_12_dialog_content = "Taruhan Anda berpikir, \"Kalau saja itu gadis cantik.\"",
  ui_story_5028_50280501_13_dialog_content = "Saya tidak!",
  ui_story_5028_50280501_14_dialog_content = "Atau mungkin Anda lebih menyukai pria bugar seperti dia?",
  ui_story_5028_50280501_15_dialog_content = "Tidak! Hentikan.",
  ui_story_5028_50280501_16_dialog_content = "Anda tahu, saya pikir tuanmu pasti sangat peduli padamu.",
  ui_story_5028_50280501_17_dialog_content = "Ini sepertinya lebih seperti liburan di tepi pantai, bukan semacam percobaan.",
  ui_story_5028_50280501_18_dialog_content = "Ya benar, seolah-olah pria bodoh itu akan sangat murah hati.",
  ui_story_5028_50280501_19_dialog_content = "Disini sangat ramai, aku benci. Dan dia bahkan tidak pernah memberitahuku mengapa dia mengirimku ke tempat seperti ini.",
  ui_story_5028_50280501_20_dialog_content = "Yang dia lakukan hanyalah menyuruhku menyikat bulu-bulu kecil itu, mencukur bulu-bulu kecil itu. Lalu dia akan menjual bulunya.",
  ui_story_5028_50280501_21_dialog_content = "Dan dia akan pergi minum dan menikmati uangnya sendiri...",
  ui_story_5028_50280501_22_dialog_content = "Dan aku akan ditinggalkan di rumah. Membuat pakan ternak untuk Fatwrens. Membersihkan setelah Cocodeer. Dipimpin oleh Speedhound untuk berlari.",
  ui_story_5028_50280501_23_dialog_content = "Bisakah Anda bayangkan? Seorang gadis muda yang menyenangkan sepertiku, digunakan olehnya sebagai pelayan.",
  ui_story_5028_50280501_24_dialog_content = "Dan sekarang di sinilah saya, dikirim untuk melakukan kerja lapangan dengan instruksi yang paling buruk.",
  ui_story_5028_50280501_25_dialog_content = "Lo, lo.",
  ui_story_5028_50280501_26_dialog_content = "Mengapa Anda memutuskan untuk menjadi muridnya?",
  ui_story_5028_50280501_27_dialog_content = "Plus, Anda terus melakukan tugas yang dia berikan kepada Anda, bahkan jika Anda terus-menerus mengeluh.",
  ui_story_5028_50280501_28_dialog_content = "Ya. Itu semacam kesalahan takdir aku bertemu dengannya.",
  ui_story_5028_50280501_29_dialog_content = "Saya terobsesi dengan buku ini ketika saya masih kecil yang disebut \"<color=#FFB400>1.001 Makhluk Fantastis</color>.\"",
  ui_story_5028_50280501_30_dialog_content = "Bisa dibilang buku itu mendefinisikan masa kecil saya.",
  ui_story_5028_50280501_30X_dialog_content = "Itulah yang memberi saya kedekatan dengan hewan dan memungkinkan saya untuk berkomunikasi dengan mereka.",
  ui_story_5028_50280501_31_dialog_content = "Tapi di Umbraton, ada banyak Aurorian dan pada dasarnya tidak ada binatang yang menakjubkan. Saya tidak suka itu, jadi saya memutuskan.",
  ui_story_5028_50280501_32_dialog_content = "Saya memutuskan saya akan menemukan penulis buku itu dan membuatnya memberitahu saya di mana menemukan semua binatang menakjubkan yang saya impikan setiap malam.",
  ui_story_5028_50280501_33_dialog_content = "Saya mengemasi tas saya, mengucapkan selamat tinggal kepada orang tua saya, dan menuju ke hutan tempat penulis dikatakan tinggal.",
  ui_story_5028_50280501_34_dialog_content = "Saya menghabiskan berhari-hari mencari dia dan tidak menemukan apa-apa. Kemudian, suatu hari, saya sedang duduk di dekat tenda saya sedang memanggang buah castafruit ketika pria ini muncul.",
  ui_story_5028_50280501_35_dialog_content = "Dia baru saja merangkak keluar dari semak-semak dan datang ke arahku, tampak setengah kelaparan.",
  ui_story_5028_50280501_36_dialog_content = "Jangan bilang itu...",
  ui_story_5028_50280501_37_dialog_content = "Ya. Tapi saat itu aku tidak tahu itu dia.",
  ui_story_5028_50280501_38_dialog_content = "Setelah dia makan, dia secara acak berkata kepada saya, \"Saya adalah ahli ekstrozoologi terbesar di benua itu. Saya sedang melakukan penelitian ekologi di dekat sini.\"",
  ui_story_5028_50280501_39_dialog_content = "Dia terdengar sangat mirip dengan artis penipu sehingga saya hampir berlari kembali ke kota untuk memanggil penjaga.",
  ui_story_5028_50280501_40_dialog_content = "Tapi kemudian dia menunjukkan kepada saya catatan yang nyaris tidak terbaca tapi pasti asli yang dia miliki, serta semua peralatan anehnya.",
  ui_story_5028_50280501_41_dialog_content = "Hanya dengan satu peluit, dia mampu mengeluarkan berbagai binatang menakjubkan yang tinggal di hutan sekitarnya.",
  ui_story_5028_50280501_42_dialog_content = "PlayerName, apakah kamu ingat ketika kita bertemu Bica?",
  ui_story_5028_50280501_43_dialog_content = "Anda perhatikan saya bisa berkomunikasi dengan binatang yang menakjubkan, bukan? Seperti hubungan psikis yang Anda miliki dengan Aurorian.",
  ui_story_5028_50280501_44_dialog_content = "Begitulah cara saya memahami Bica dan tukik Drakolion. Dan... yah, saya lebih suka berinteraksi dengan makhluk ajaib daripada Aurorian.",
  ui_story_5028_50280501_45_dialog_content = "Sejujurnya, saya pasti terbawa suasana dikelilingi oleh binatang buas yang menakjubkan pada saat itu.",
  ui_story_5028_50280501_46_dialog_content = "Itu tidak membantu bahwa dia terus memberi tahu saya bahwa kemampuan saya untuk berkomunikasi dengan mereka akan membuat saya menjadi ahli ekstrozoologi yang hebat.",
  ui_story_5028_50280501_47_dialog_content = "Gagasan menjadi seorang ahli ekstrozoologi seperti mimpi yang menjadi kenyataan. Aku tidak bisa menahan godaan.",
  ui_story_5028_50280501_48_dialog_content = "Bahkan sekarang, jika saya bisa memilih lagi, saya pikir saya akan tetap memilih untuk menjadi muridnya.",
  ui_story_5028_50280501_49_dialog_content = "Saya sepenuhnya percaya sejak saat itu bahwa dia adalah ahli ekstrozoologi hebat Vic, penulis buku yang sangat saya cintai.",
  ui_story_5028_50280501_50_dialog_content = "Saya memilih hidup ini untuk diri saya sendiri, tetapi tetap saja, saya harus mengatakan bahwa dia adalah mentor yang buruk!",
  ui_story_5028_50280501_51_dialog_content = "Ha ha. Tapi Anda telah melakukan apa yang Anda sukai selama ini.",
  ui_story_5028_50280501_52_dialog_content = "Aduh!",
  ui_story_5028_50280501_53_dialog_content = "Hati-Hati!",
  ui_story_5028_50280501_54_dialog_content = "Oh maaf. aku tergelincir.",
  ui_story_5028_50280501_55_dialog_content = "Tidak masalah. Selama kamu baik-baik saja.",
  ui_story_5028_50280501_56_dialog_content = "(Lagi?)",
  ui_story_5028_50280501_57_dialog_content = "Maaf. Jadi, eh... Sebenarnya, menurutku...",
  ui_story_5028_50280501_58_dialog_content = "Ini adalah bagaimana hidup ini. Hal-hal tidak selalu berjalan mulus. Anda sudah lebih beruntung daripada banyak orang.",
  ui_story_5028_50280501_59_dialog_content = "Wow, melihatmu mencoba terdengar dewasa seperti orang dewasa cukup ngeri.",
  ui_story_5028_50280501_60_dialog_content = "Apakah gadis cantik yang jatuh ke pelukanmu membuatmu gegar otak?",
  ui_story_5028_50280501_61_dialog_content = "Oh demi Tuhan, dia tidak jatuh ke pelukanku! Aku baru saja menghentikannya agar tidak jatuh.",
  ui_story_5028_50280501_62_dialog_content = "Ngomong-ngomong, nada bicaramu... apakah itu cemburu?",
  ui_story_5028_50280501_63_dialog_content = "Ha. Seolah-olah saya akan punya waktu untuk omong kosong yang membosankan. Saya cukup senang dengan binatang ajaib saya untuk ditemani, terima kasih.",
  ui_story_5028_50280501_64_dialog_content = "Ada lebih banyak garam dalam kata-katamu daripada lautan.",
  ui_story_5028_50280501_65_dialog_content = "Anda-!",
  ui_story_5028_50280501_66_dialog_content = "Oke, kembali ke bisnis. Jika Anda dapat berbicara dengan binatang yang menakjubkan, itu berarti Anda akan menjadi ahli ekstrozoologi yang luar biasa.",
  ui_story_5028_50280501_67_dialog_content = "Sama seperti kemampuan saya untuk membentuk hubungan psikis dengan Aurorian membuat saya menjadi komandan medan perang yang baik.",
  ui_story_5028_50280501_68_dialog_content = "Meskipun itu benar, ada pengecualian. Keterampilan saya tidak bekerja pada Kyllo, misalnya.",
  ui_story_5028_50280501_69_dialog_content = "Lihat!",
  ui_story_5028_50280501_70_dialog_content = "Mengapa?",
  ui_story_5028_50280501_71_dialog_content = "Saya tidak tahu... Guru mengatakan itu adalah jenis khusus dari binatang ajaib. Sebuah eksotis.",
  ui_story_5028_50280501_72_dialog_content = "Lihat!",
  ui_story_5028_50280501_73_dialog_content = "Eksotik? Tentunya hanya sesuatu seperti Drakolion yang dianggap eksotis?",
  ui_story_5028_50280501_74_dialog_content = "Lihat, bahkan Anda tidak percaya apa yang dia katakan.",
  ui_story_5028_50280501_75_dialog_content = "Lo... Lo...",
  ui_story_5028_50280501_76_dialog_content = "Jangan sedih, Kyu.",
  ui_story_5028_50280501_77_dialog_content = "Aku mungkin tidak bisa memahamimu, tapi aku tahu kau adalah Kyllo kecil yang baik.",
  ui_story_5028_50280501_78_dialog_content = "Lihat!",
  ui_story_5028_50280501_79_dialog_content = "Tidak berguna, mungkin. Dan cukup banyak tidak membantu.",
  ui_story_5028_50280501_80_dialog_content = "Lihat!",
  ui_story_5028_50280501_81_dialog_content = "Ahhhh!",
  ui_story_5028_50280501_82_dialog_content = "Mengapa semua orang jatuh?",
  ui_story_5028_50280501_83_dialog_content = "Aku tahu ada yang salah dengan tempat ini. Ayo dan lihat!",
  ui_story_5028_50280501_84_dialog_content = "Hai! Fia, jangan lari—",
  ui_story_5028_50280501_85_dialog_content = "Wah!",
  ui_story_5028_50280501_86_dialog_content = "Hai!",
  ui_story_5028_50280501_87_dialog_content = "T-terima kasih, PlayerName.",
  ui_story_5028_50280501_88_dialog_content = "Sejujurnya, mengapa Anda berlari begitu cepat mengetahui betapa mudahnya tergelincir di sini?",
  ui_story_5028_50280501_89_dialog_content = "Maaf... Aku jadi bersemangat. Bisakah Anda menurunkan saya?",
  ui_story_5028_50280501_90_dialog_content = "Benar.",
  ui_story_5028_50280501_91_dialog_content = "Aku tahu itu!",
  ui_story_5028_50280501_92_dialog_content = "Apa?",
  ui_story_5028_50280501_93_dialog_content = "Tidak bisakah kamu melihatnya? Benda itu menempel di kakiku.",
  ui_story_5028_50280501_94_dialog_content = "Benda tembus pandang ini adalah <color=#FFB400>murung</color>.",
  ui_story_5028_50280501_95_dialog_content = "gelap.",
  ui_story_5028_50280501_96_dialog_content = "Mereka biasanya tinggal di air, tetapi naik ke darat untuk bernapas.",
  ui_story_5028_50280501_97_dialog_content = "Tetapi menjadi transparan berarti mereka mudah diinjak secara tidak sengaja.",
  ui_story_5028_50280501_98_dialog_content = "Tapi ada terlalu banyak Aurorian di luar dan di sekitar sini. Saya tidak berpikir tempat ini aman untuk mereka lagi.",
  ui_story_5028_50280501_99_dialog_content = "Mereka semua pasti datang ke darat untuk bermigrasi ke rumah baru.",
  ui_story_5028_50280501_100_dialog_content = "Tapi mereka bergerak terlalu lambat dan semua orang terus terpeleset. Jika ini terus berlanjut, Glooeys dan turis akan terluka.",
  ui_story_5028_50280501_101_dialog_content = "(Dia selalu menjadi serius begitu dia mulai berbicara tentang binatang buas yang menakjubkan.)",
  ui_story_5028_50280501_102_dialog_content = "Itu pasti tentang cobaan kita: membantu keluarga Glooey pindah ke rumah baru!",
  ui_story_5028_50280501_103_dialog_content = "Ya. Mari kita kumpulkan orang-orang yang tercerai berai oleh orang banyak. Kemudian kita bisa mengawal mereka ke tempat yang aman.",
  ui_story_5028_50280501_104_dialog_content = "Kyllo, berhenti bermain-main dengan Glooey. Datang dan bantu!",
  ui_story_5028_50280501_105_dialog_content = "Lihat!",
  ui_story_5028_50280501_106_dialog_content = "Fiuh. Apakah itu yang terakhir?",
  ui_story_5028_50280501_107_dialog_content = "gelap...",
  ui_story_5028_50280501_108_dialog_content = "Ya. Sepertinya mereka semua merangkak ke arah yang sama.",
  ui_story_5028_50280501_109_dialog_content = "Mereka akan mencari bagian garis pantai yang lebih tenang untuk dihuni. Kita hanya perlu memastikan mereka sampai di sana.",
  ui_story_5028_50280501_110_dialog_content = "Tunggu sebentar. Saya pikir saya melihat Eclipsites di depan. Bisakah Anda meminta Glooey untuk mengalihkan di sekitar mereka?",
  ui_story_5028_50280501_111_dialog_content = "Aku tidak bisa, mereka terlalu keras kepala. Itu sebabnya mereka tidak menyingkir dan diinjak sepanjang waktu.",
  ui_story_5028_50280501_112_dialog_content = "Dan itu hanya beberapa Eclipsites yang bau. Mengapa kita harus bersembunyi?",
  ui_story_5028_50280501_113_dialog_content = "Serahkan padaku kali ini. Aku akan melawan mereka!",
  ui_story_5028_50280502_1_dialog_content = "<color=#e8d9bb>*Gelombang menerjang*</color>",
  ui_story_5028_50280502_2_dialog_content = "Disini jauh lebih damai. Aku bahkan tidak bisa mendengar burung camar.",
  ui_story_5028_50280502_3_dialog_content = "Saya pikir ini akan menjadi rumah yang baik untuk Glooeys.",
  ui_story_5028_50280502_4_dialog_content = "Haloo... Haloo...",
  ui_story_5028_50280502_5_dialog_content = "Lain kali, lebih berhati-hati! Pastikan untuk bermigrasi sebelum turis datang, bukan setelahnya.",
  ui_story_5028_50280502_6_dialog_content = "Hai! Para turis yang terpeleset dan jatuh itu tidak bersalah, lho.",
  ui_story_5028_50280502_7_dialog_content = "Tetapi di antara massa Eclipsites dan perubahan lingkungan yang drastis, habitat binatang yang menakjubkan semakin sulit ditemukan.",
  ui_story_5028_50280502_8_dialog_content = "Banyak dari mereka benar-benar melindungi Aurorian sepanjang waktu, tahukah Anda?",
  ui_story_5028_50280502_9_dialog_content = "Banyak binatang menakjubkan tinggal di dekat kota, di mana mereka berfungsi sebagai garis pertahanan pertama Auroria, melihat dan melawan penjajah Eclipsite.",
  ui_story_5028_50280502_10_dialog_content = "Wah, saya tidak tahu itu.",
  ui_story_5028_50280502_11_dialog_content = "Bagaimanapun, itu satu percobaan lagi selesai. Hari produktif lainnya untuk membantu hewan-hewan menakjubkan!",
  ui_story_5028_50280502_12_dialog_content = "(Eh? Ada sesuatu yang lengket di kakiku.)",
  ui_story_5028_50280502_13_dialog_content = "gelap...",
  ui_story_5028_50280502_14_dialog_content = "Kamu bilang kamu melihat monster yang menakutkan di sekitar sini, tapi tidak ada orang lain yang percaya padamu? Jadi kau ingin tinggal bersamaku?",
  ui_story_5028_50280502_15_dialog_content = "Heee. Garis pikap Anda agak klise.",
  ui_story_5028_50280502_16_dialog_content = "Tapi pasti, kenapa tidak. Anda dapat bergabung dengan yang lain!",
  ui_story_5028_50280502_17_dialog_content = "PlayerName, Lihat. Kami punya teman baru lagi!",
  ui_story_5028_50280502_18_dialog_content = "Lihat!",
  ui_story_5028_50280502_19_dialog_content = "Yang lainnya? Apakah Anda selalu begitu populer dengan mereka?",
  ui_story_5028_50280502_20_dialog_content = "Hai!",
  ui_story_5028_50280502_21_dialog_content = "Tentu saja. Aku akan menjadi ahli ekstrozoologi, aku perlu berteman dengan semua binatang yang menakjubkan.",
  ui_story_5028_50280502_22_dialog_content = "Tapi saya akan memberikan beberapa kepada tuan saya untuk dijaga jika saya berakhir dengan terlalu banyak. Berada bersamaku mungkin tidak selalu aman bagi mereka.",
  ui_story_5028_50280502_23_dialog_content = "Saya mengerti. Nah, bisakah saya menyusahkan ahli residen kami untuk memberi tahu saya berapa banyak lagi percobaan yang harus dia selesaikan?",
  ui_story_5028_50280502_24_dialog_content = "Hmm. Biarkan saya memeriksa.",
  ui_story_5028_50280502_25_dialog_content = "Luar biasa! Oh. Menisik!",
  ui_story_5028_50280502_26_dialog_content = "lihat?",
  ui_story_5028_50280502_27_dialog_content = "Apa?",
  ui_story_5028_50280502_28_dialog_content = "Nah, bisa dibilang saya sudah selesai, tapi bisa juga saya tidak akan pernah selesai.",
  ui_story_5028_50280502_29_dialog_content = "Apa yang kau bicarakan?",
  ui_story_5028_50280502_30_dialog_content = "Um, aku sudah menyelesaikan semua percobaan berbahaya!",
  ui_story_5028_50280502_31_dialog_content = "Tapi bagaimana saya bisa menyelesaikan yang satu ini: menghafal Encyclopedia Exotica karya Master Vic?",
  ui_story_5028_50280502_32_dialog_content = "Ugh. Saya telah mengerjakannya selama seminggu dan hanya menghafal dua setengah halaman.",
  ui_story_5028_50280502_33_dialog_content = "lihat...",
  ui_story_5028_50280502_34_dialog_content = "Hmm, pertempuran dan kekerasan tidak akan cukup untuk yang satu ini.",
  ui_story_5028_50280502_35_dialog_content = "Saya mungkin seorang Caelestit, tetapi saya masih tidak memiliki cara untuk menanamkan semua info itu di kepala Anda.",
  ui_story_5028_50280502_36_dialog_content = "... Lihat!",
  ui_story_5028_50280502_37_dialog_content = "Mendesah...",
  ui_story_5028_50280502_38_dialog_content = "Lihat! Lihat!",
  ui_story_5028_50280502_39_dialog_content = "Eh? Kyllo, berhenti, apa yang kamu lakukan?",
  ui_story_5028_50280502_40_dialog_content = "Berhenti menarik notebook, Anda akan merobeknya!",
  ui_story_5028_50280502_41_dialog_content = "Lihat!",
  ui_story_5028_50280502_42_dialog_content = "Aku bilang, jangan—Ah!",
  ui_story_5028_50280502_43_dialog_content = "Fi, kamu baik-baik saja?",
  ui_story_5028_50280502_44_dialog_content = "Apakah Anda mencari pertarungan, Kyllo?!",
  ui_story_5028_50280502_45_dialog_content = "Tunggu, itu membolak-balik buku catatan.",
  ui_story_5028_50280502_46_dialog_content = "Apa?",
  ui_story_5028_50280502_47_dialog_content = "Lihat! Lihat!",
  ui_story_5028_50280502_48_dialog_content = "Halaman ini... tentang kelinci?",
  ui_story_5028_50280502_49_dialog_content = "Seekor kelinci?",
  ui_story_5028_50280502_50_dialog_content = "Di sini.",
  ui_story_5028_50280502_51_dialog_content = "Hah? Di sinilah petunjuk Anda membayar semua uang itu untuk tujuan?",
  ui_story_5028_50280502_52_dialog_content = "Bayangkan jatuh untuk penipuan seperti itu setelah bertahun-tahun di Umbraton.",
  ui_story_5028_50280502_53_dialog_content = "Atau apakah Anda hanya ingin mengajak saya bermain di tepi laut? Maaf mengecewakanmu, tapi aku tidak membawa baju renangku.",
  ui_story_5028_50280502_54_dialog_content = "Ha ha. Kebetulan saya punya milik saya.",
  ui_story_5028_50280502_55_dialog_content = "Saya yakin Anda menyesal tidak mengenakan baju renang Anda yang minim itu sekarang, bukan?",
  ui_story_5028_50280502_56_dialog_content = "Sekarang Anda terjebak mencari overdressed untuk pantai sendirian seperti orang bodoh.",
  ui_story_5028_50280502_57_dialog_content = "Anda tidak tahu berapa lama saya menunggu untuk melihat ekspresi iri di wajah Anda.",
  ui_story_5028_50280502_58_dialog_content = "Anda! Aku akan melemparkanmu ke laut, lalu pergi dan temukan Caelestite.",
  ui_story_5028_50280502_59_dialog_content = "Ha ha. Jujur saja, siapa yang peduli dengan Caelestite? Saya hanya datang karena saya punya waktu untuk membunuh.",
  ui_story_5028_50280502_60_dialog_content = "Bukankah itu juga alasanmu untuk datang?",
  ui_story_5028_50280502_61_dialog_content = "Oh tolong, motivasi saya tidak terlalu dangkal. Bantulah saya dan jangan memproyeksikan.",
  ui_story_5028_50280502_62_dialog_content = "Saya melihat ini sebagai kesempatan untuk membuktikan sekali dan untuk semua bahwa saya lebih baik dari Anda!",
  ui_story_5028_50280502_63_dialog_content = "Bukan dengan mengandalkan baju renang yang minim, tapi dengan menggunakan keahlianku sebagai pemburu hadiah profesional!",
  ui_story_5028_50280502_64_dialog_content = "Oh? Itu pembicaraan yang cukup besar bagi seseorang yang lupa membawa baju renang ke pantai.",
  ui_story_5028_50280502_65_dialog_content = "Oh, bagus! Saya ingin baju renang juga.",
  ui_story_5028_50280502_66_dialog_content = "Tersenyumlah untuk kamera!",
  ui_story_5028_50280502_67_dialog_content = "<color=#e8d9bb>Klik!</color>",
  ui_story_5028_50280502_68_dialog_content = "Lester?",
  ui_story_5028_50280502_69_dialog_content = "Hei, bukankah ini? Smokey!?",
  ui_story_5028_50280502_70_dialog_content = "Apa yang kamu lakukan di sini? Masih dalam perjalanan Anda?",
  ui_story_5028_50280502_71_dialog_content = "Tentu saja. Kalian berdua terlihat akrab juga, apakah kalian semua di sini untuk liburan pantai?",
  ui_story_5028_50280502_72_dialog_content = "Di sini, lihat foto yang saya ambil dari Anda.",
  ui_story_5028_50280502_73_dialog_content = "Oh terima kasih.",
  ui_story_5028_50280502_74_dialog_content = "... Biarku lihat.",
  ui_story_5028_50280502_75_dialog_content = "Saya kira Anda bisa menyebutnya istirahat mini. Selain itu, kami juga mencari teman yang diculik atau tersesat atau semacamnya.",
  ui_story_5028_50280502_76_dialog_content = "Oh hei, kamu sebenarnya mengenalnya, Caelestit.",
  ui_story_5028_50280502_77_dialog_content = "Caelestit hilang? Satu-satunya Caelestit yang tersisa di benua itu hilang?",
  ui_story_5028_50280502_78_dialog_content = "Ya, satu-satunya atau apa pun, toh dia sudah pergi.",
  ui_story_5028_50280502_79_dialog_content = "Saya mengerti. Yah, aku akan menjaga mataku tetap terbuka untuknya.",
  ui_story_5028_50280502_80_dialog_content = "Dan jika aku bertemu dengannya, aku akan membawanya kembali untuk kalian.",
  ui_story_5028_50280601_1_dialog_content = "Percobaan: Hafalkan Encyclopedia Exotica",
  ui_story_5028_50280601_2_dialog_content = "<color=#e8d9bb>Bang!</color>",
  ui_story_5028_50280601_3_dialog_content = "<color=#e8d9bb>Bang!</color>",
  ui_story_5028_50280601_4_dialog_content = "Cukup! Tahan apimu.",
  ui_story_5028_50280601_5_dialog_content = "Anda akan menakuti mangsanya.",
  ui_story_5028_50280601_6_dialog_content = "Ck, bagaimana dengan mereka berdua? Apakah kita akan membiarkan mereka pergi?",
  ui_story_5028_50280601_7_dialog_content = "Tidak ada waktu. Kita harus menangkapnya <color=#FFB400>kelinci peko</color> segera untuk <color=#FFB400>Gary</color>.",
  ui_story_5028_50280601_8_dialog_content = "Jika kita membuat bos marah, kita akan berada dalam masalah besar.",
  ui_story_5028_50280601_9_dialog_content = "Hmm.",
  ui_story_5028_50280601_10_dialog_content = "Ahh—Ahh—",
  ui_story_5028_50280601_11_dialog_content = "Acho!",
  ui_story_5028_50280601_12_dialog_content = "Sst.",
  ui_story_5028_50280601_13_dialog_content = "Mereka pergi.",
  ui_story_5028_50280601_14_dialog_content = "lihat",
  ui_story_5028_50280601_15_dialog_content = "Untung Kyllo memiliki pandangan jauh ke depan untuk menemukan semak yang tertutup salju ini untuk kami sembunyikan.",
  ui_story_5028_50280601_16_dialog_content = "Lihat!",
  ui_story_5028_50280601_17_dialog_content = "Achooooo!",
  ui_story_5028_50280601_18_dialog_content = "Acho! Acho! Acho!",
  ui_story_5028_50280601_19_dialog_content = "Apakah kamu baik-baik saja? Di sini, bersihkan hidungmu.",
  ui_story_5028_50280601_20_dialog_content = "*Mencium* Terima kasih.",
  ui_story_5028_50280601_21_dialog_content = "Aku benci tempat ini. Tangan dan kakiku membeku kaku.",
  ui_story_5028_50280601_22_dialog_content = "Aku tidak akan pernah datang ke tempat sedingin ini jika bukan karena ingin menangkap salah satu kelinci Peko yang disebutkan di buku catatan.",
  ui_story_5028_50280601_23_dialog_content = "Ini, ambil mantelku. Oh, dan aku punya syal cadangan.",
  ui_story_5028_50280601_24_dialog_content = "Tidak, saya ragu Anda akan bertahan lama tanpa mereka juga.",
  ui_story_5028_50280601_25_dialog_content = "Makan ini.",
  ui_story_5028_50280601_26_dialog_content = "Mm?!",
  ui_story_5028_50280601_27_dialog_content = "Ini adalah pil yang terbuat dari bubuk ulat pasir, bahan bakar minyak, dan sungrass.",
  ui_story_5028_50280601_28_dialog_content = "Ini membantu Anda tetap hangat di lingkungan yang dingin.",
  ui_story_5028_50280601_29_dialog_content = "Tapi ini satu-satunya yang tersisa sejak saya kehabisan bubuk cacing pasir baru-baru ini.",
  ui_story_5028_50280601_30_dialog_content = "Saya merasa jauh lebih hangat. Tapi bagaimana denganmu?",
  ui_story_5028_50280601_31_dialog_content = "Saya akan menggunakan Glooey sebagai insulasi ekstra di tubuh saya.",
  ui_story_5028_50280601_32_dialog_content = "gelap...",
  ui_story_5028_50280601_33_dialog_content = "Jika saya pingsan karena kedinginan, Anda dapat membawa saya turun dari gunung dan meminta bantuan.",
  ui_story_5028_50280601_34_dialog_content = "Tapi jika kamu pingsan, aku tidak bisa berbuat apa-apa selain meninggalkanmu di sini.",
  ui_story_5028_50280601_35_dialog_content = "Benar. Oke, jika terjadi sesuatu, aku pasti akan mengeluarkanmu dari tempat ini.",
  ui_story_5028_50280601_36_dialog_content = "Meskipun sekarang aku memikirkannya, aku tidak yakin kamu cukup kuat untuk menggendongku. Mungkin Anda harus memuntahkan pil itu agar Kyllo bisa meminumnya.",
  ui_story_5028_50280601_37_dialog_content = "Terlambat, itu sudah ada di perutku.",
  ui_story_5028_50280601_38_dialog_content = "Ha ha. Aku hanya bercanda.",
  ui_story_5028_50280601_39_dialog_content = "lihat?",
  ui_story_5028_50280601_40_dialog_content = "Oke, sekarang setelah kita semua merasa lebih baik, kita harus bergerak.",
  ui_story_5028_50280601_41_dialog_content = "Kita harus menemukan kelinci Peko sebelum para pemburu itu melakukannya.",
  ui_story_5028_50280601_42_dialog_content = "Apakah kelinci ini benar-benar langka? Itu pasti berhasil menarik banyak pemburu ke tempat terkutuk ini.",
  ui_story_5028_50280601_43_dialog_content = "Dan mereka tampak terorganisir dan profesional. Bos mereka pasti menghabiskan banyak uang.",
  ui_story_5028_50280601_44_dialog_content = "Hmph. Tidak peduli berapa banyak orang bodoh yang mereka kirim.",
  ui_story_5028_50280601_45_dialog_content = "Tenaga kerja, senjata, anjing... Tak satu pun dari itu akan berguna bagi mereka. Begitu juga dengan jebakan yang mereka tempatkan di seluruh bukit.",
  ui_story_5028_50280601_46_dialog_content = "Kelinci Peko tidak akan pernah tertangkap seperti ini.",
  ui_story_5028_50280601_47_dialog_content = "Nah, jika pemburu profesional tidak bisa mendapatkannya, bagaimana kita akan melakukannya?",
  ui_story_5028_50280601_48_dialog_content = "Santai. Jangan lupa, saya seorang extrozoologist berpengalaman!",
  ui_story_5028_50280601_49_dialog_content = "Saya bisa menangkap kelinci Peko semudah menjentikkan jari.",
  ui_story_5028_50280601_50_dialog_content = "Argh... Jari-jariku membeku lagi.",
  ui_story_5028_50280601_51_dialog_content = "Sudahkah Anda menemukan buku catatannya? Haruskah saya membantu Anda melihat?",
  ui_story_5028_50280601_52_dialog_content = "Tidak, terima kasih! Saya mengerti.",
  ui_story_5028_50280601_53_dialog_content = "Mereka waspada dan pintar, yang membuat mereka sulit ditangkap. Mereka suka makan buku.",
  ui_story_5028_50280601_54_dialog_content = "Sempurna! Kita bisa menggunakan buku sebagai umpan—",
  ui_story_5028_50280601_55_dialog_content = "Jika Anda pikir itu semudah melempar buku sebagai umpan dan menangkapnya, sebaiknya kita berhenti sekarang juga.",
  ui_story_5028_50280601_56_dialog_content = "Anggap saja aku tidak mengatakan apa-apa.",
  ui_story_5028_50280601_57_dialog_content = "Mereka terlalu licik. Sebuah buku yang tergeletak begitu saja di salju akan membuat mereka waspada.",
  ui_story_5028_50280601_58_dialog_content = "Tapi mungkin kita bisa menggunakan rasa ingin tahu mereka untuk melawan mereka. Rumput tetangga lebih hijau dan sebagainya.",
  ui_story_5028_50280601_59_dialog_content = "Bagaimana kita bisa melakukan itu? Hai, PlayerName, berikan saya buku yang Anda baca akhir-akhir ini.",
  ui_story_5028_50280601_60_dialog_content = "Apa ini? \"Gadis di Sebelahku Kadang Menyembunyikan Perasaannya di Eclipsian\"?",
  ui_story_5028_50280601_61_dialog_content = "Mengapa judulnya sangat panjang?",
  ui_story_5028_50280601_62_dialog_content = "Ya. Itu adalah hadiah dari Tuan Peng, pria kebun anggur. Dia menulisnya.",
  ui_story_5028_50280601_63_dialog_content = "Dia bahkan menandatanganinya. Dia mengatakan itu akan sangat berharga dalam beberapa tahun.",
  ui_story_5028_50280601_64_dialog_content = "Oh begitu. Yah, saya lebih suka mengambil risiko ini daripada buku catatan Guru.",
  ui_story_5028_50280601_65_dialog_content = "Mendesah...",
  ui_story_5028_50280601_66_dialog_content = "Entah bagaimana rasanya kamu baru saja menghinaku dan Tuan Peng meskipun kamu jelas tidak mengatakan apa-apa...",
  ui_story_5028_50280601_67_dialog_content = "Lebih sedikit obrolan, lebih banyak pekerjaan. Kita harus mendapatkan kelinci itu sebelum pemburu melakukannya.",
  ui_story_5028_50280601_68_dialog_content = "Sembunyikan dirimu, aku akan mulai membaca.",
  ui_story_5028_50280601_69_dialog_content = "Saat Peko muncul, tekan tombol.",
  ui_story_5028_50280601_70_dialog_content = "Bukankah itu akan menjebak Anda di jaring juga?",
  ui_story_5028_50280601_71_dialog_content = "Terus? Itu tidak akan menggigitku.",
  ui_story_5028_50280601_72_dialog_content = "Dan jika itu terjadi, saya akan membalasnya. Lebih keras.",
  ui_story_5028_50280601_73_dialog_content = "<color=#e8d9bb>Suatu saat nanti</color>",
  ui_story_5028_50280601_74_dialog_content = "peko?",
  ui_story_5028_50280601_75_option_content = "Mindlink dengan Fia",
  ui_story_5028_50280601_76_dialog_content = "Ada yang datang. Terus seperti itu.",
  ui_story_5028_50280601_77_dialog_content = "Mengerti. Dan jangan lewatkan kesempatan Anda.",
  ui_story_5028_50280601_78_dialog_content = "lihat...",
  ui_story_5028_50280601_79_dialog_content = "Peko peko...",
  ui_story_5028_50280601_80_dialog_content = "(Hehehe, itu dia. Ikuti rasa penasaranmu dan datang padaku.)",
  ui_story_5028_50280601_81_dialog_content = "peko...",
  ui_story_5028_50280601_82_dialog_content = "Ini tidak bagus. Binatang kecil yang mencurigakan ini terus melompat-lompat di tepi jaring, tidak mau melangkah lebih jauh.",
  ui_story_5028_50280601_83_dialog_content = "Jika kita memicunya sekarang, kemungkinan besar akan lolos, dan kita tidak akan pernah mendapatkan kesempatan seperti ini lagi.",
  ui_story_5028_50280601_84_dialog_content = "Hanya ada satu pilihan. Aku akan mengambilnya. Bersiap, PlayerName.",
  ui_story_5028_50280601_85_dialog_content = "Sekarang...",
  ui_story_5028_50280601_86_dialog_content = "peko?",
  ui_story_5028_50280601_87_dialog_content = "Membekukan!",
  ui_story_5028_50280601_88_dialog_content = "Peko!!",
  ui_story_5028_50280601_89_dialog_content = "mengerti!",
  ui_story_5028_50280601_90_dialog_content = "Saya mendapatkannya! Saya mendapatkannya!",
  ui_story_5028_50280601_91_dialog_content = "Peko peko peko peko!!",
  ui_story_5028_50280601_92_dialog_content = "Wow, Anda baru saja berteriak pada kelinci Peko dan membuatnya takut untuk tunduk.",
  ui_story_5028_50280601_93_dialog_content = "Saya tidak tahu apakah memunculkan ide itu dalam hitungan detik membuat Anda pintar atau gila.",
  ui_story_5028_50280601_94_dialog_content = "Heehee, aku akan menganggap itu sebagai pujian. Dan jangan hanya berdiri di sana, keluarkan kita berdua dari sini.",
  ui_story_5028_50280601_95_dialog_content = "Hehehe. Sekarang saya akan dapat menyelesaikan uji coba terakhir.",
  ui_story_5028_50280601_96_dialog_content = "Pe... Peko...",
  ui_story_5028_50280601_97_dialog_content = "Lihat!",
  ui_story_5028_50280601_98_dialog_content = "Bagaimana kelinci Peko akan membantu Anda dengan percobaan?",
  ui_story_5028_50280601_99_dialog_content = "Menurut buku catatan, kelinci peko dapat menyerap ilmu dari buku dan kemudian mentransfernya ke orang lain.",
  ui_story_5028_50280601_100_dialog_content = "Saya telah mencapai titik di mana hal seperti itu bahkan tidak mengejutkan saya. Jadi bagaimana ini benar-benar bekerja?",
  ui_story_5028_50280601_101_dialog_content = "Ayo lihat. Pertama, siapkan buku yang berisi informasi yang Anda butuhkan untuk mentransfer dan memberikannya ke Peko.",
  ui_story_5028_50280601_102_dialog_content = "Yah, saya kira saya bisa menerima itu normal. Untuk binatang yang menakjubkan.",
  ui_story_5028_50280601_103_dialog_content = "Lalu?",
  ui_story_5028_50280601_104_dialog_content = "Lalu... panaskan sedikit minyak dalam wajan... masukkan bawang bombay, jahe, dan bawang putih... tumis hingga harum...",
  ui_story_5028_50280601_105_dialog_content = "?",
  ui_story_5028_50280601_106_dialog_content = "Peko!!",
  ui_story_5028_50280601_107_dialog_content = "Lihat!!",
  ui_story_5028_50280601_108_dialog_content = "Tambahkan sedikit gula dan masak hingga menjadi karamel. Kemudian kulit...",
  ui_story_5028_50280601_109_dialog_content = "Apakah Anda memberi tahu saya bahwa kita harus merebusnya?",
  ui_story_5028_50280601_110_dialog_content = "Kedengarannya seperti itu... tapi... bagaimana bisa—Pria bodoh itu!",
  ui_story_5028_50280601_111_dialog_content = "Mungkin makan hanya satu kaki akan berhasil?",
  ui_story_5028_50280601_112_dialog_content = "Peko peko peko!",
  ui_story_5028_50280601_113_dialog_content = "Jangan bercanda seperti itu, Peko sudah ketakutan.",
  ui_story_5028_50280601_114_dialog_content = "Tunggu, saya pikir itu mencoba untuk memperingatkan kita tentang sesuatu.",
  ui_story_5028_50280601_115_dialog_content = "Dari apa? Kami memberi para pemburu slip.",
  ui_story_5028_50280601_116_dialog_content = "Ini mengatakan... <color=#FFB400>gerhana!</color>",
  ui_story_5028_50280602_1_dialog_content = "Setiap saat! Hama ini!",
  ui_story_5028_50280602_2_dialog_content = "Mengapa mereka ada di mana-mana? Saya harus mempertimbangkan kembali karir saya. Akan jauh lebih mudah menjadi seorang Eclipsitologist.",
  ui_story_5028_50280602_3_dialog_content = "Syukurlah itu memperingatkan kita, atau kita akan dikepung.",
  ui_story_5028_50280602_4_dialog_content = "Peko peko!",
  ui_story_5028_50280602_5_dialog_content = "Yah, kita pasti tidak bisa memakannya. Jadi bagaimana dengan sidang Anda?",
  ui_story_5028_50280602_6_dialog_content = "Aku harus memikirkan hal lain. Saya tidak akan menjadi ahli ekstrozoologi jika saya menyakiti binatang yang menakjubkan untuk keuntungan saya sendiri.",
  ui_story_5028_50280602_7_dialog_content = "Saya tidak akan pernah, bahkan jika itu berarti tidak pernah menyelesaikan percobaan saya.",
  ui_story_5028_50280602_8_dialog_content = "Oh, tapi apa yang akan saya lakukan?",
  ui_story_5028_50280602_9_dialog_content = "peko...",
  ui_story_5028_50280602_10_dialog_content = "lihat...",
  ui_story_5028_50280602_11_dialog_content = "gelap...",
  ui_story_5028_50280602_12_dialog_content = "Terima kasih telah menghiburku.",
  ui_story_5028_50280602_13_dialog_content = "Harus ada cara lain.",
  ui_story_5028_50280602_14_dialog_content = "Pasti ada cara untuk membantu kita tanpa kita merugikannya.",
  ui_story_5028_50280602_15_dialog_content = "Saya tahu!",
  ui_story_5028_50280602_16_dialog_content = "Peko, apakah kamu ingin mendengar rencanaku yang sempurna?",
  ui_story_5028_50280602_17_dialog_content = "peko!",
  ui_story_5028_50280602_17X1_dialog_content = "Ah!",
  ui_story_5028_50280602_18_dialog_content = "Hm? Ini meringkuk melawan Anda dalam kebahagiaan.",
  ui_story_5028_50280602_19_dialog_content = "Hehe! Itulah kedekatan saya dengan hewan!",
  ui_story_5028_50280602_19X1_dialog_content = "Oke, oke... Jadi apa rencanamu?",
  ui_story_5028_50280602_19X2_dialog_content = "Ini akan sulit bagi orang lain, tapi itu sepotong kue bagi saya.",
  ui_story_5028_50280602_19X3_dialog_content = "Ingat? Saya bisa memahami binatang yang menakjubkan.",
  ui_story_5028_50280602_19X4_dialog_content = "Jadi, yang perlu saya lakukan hanyalah menyembunyikan Peko di pangkuan atau saku saya selama persidangan.",
  ui_story_5028_50280602_19X5_dialog_content = "Itu bisa membisikkan jawaban untukku!",
  ui_story_5028_50280602_19X6_dialog_content = "Dengan cara ini, saya akan lulus ujian, dan mengejutkan tuan bodoh saya!",
  ui_story_5028_50280602_19X7_dialog_content = "Mungkinkah itu benar-benar sesederhana itu? Saya tidak benar-benar membelinya ...",
  ui_story_5028_50280602_20_dialog_content = "Peko peko!",
  ui_story_5028_50280602_20X1_dialog_content = "Bisakah kau bersembunyi di dalam sakuku...",
  ui_story_5028_50280602_20X2_dialog_content = "Dan beri tahu saya jawaban yang benar secara rahasia?",
  ui_story_5028_50280602_20X3_dialog_content = "Peko-Peko!",
  ui_story_5028_50280602_20X4_dialog_content = "Hehe! Besar!",
  ui_story_5028_50280602_21_dialog_content = "Ini akan membantu, dan ingin bepergian bersama kami!",
  ui_story_5028_50280602_22_dialog_content = "peko!",
  ui_story_5028_50280602_22X1_dialog_content = "Ini sempurna! Sekarang kita bisa kembali ke tuanku!",
  ui_story_5028_50280602_23_dialog_content = "Maksudku, kami sudah memiliki seluruh kebun binatang yang mengikuti kami. Saya yakin satu lagi tidak akan sakit.",
  ui_story_5028_50280602_24_dialog_content = "Heehee... Kau orang yang sangat baik hati, PlayerName.",
  ui_story_5028_50280602_25_dialog_content = "Apa? Kamu bilang kamu kelinci Peko yang beruntung karena kamu diselamatkan dari cengkeraman monster menakutkan di masa lalu?",
  ui_story_5028_50280602_26_dialog_content = "Itu luar biasa! Saya yakin Anda akan menjadi jimat keberuntungan untuk perjalanan kita. Kami mengandalkan Anda!",
  ui_story_5028_50280602_27_dialog_content = "peko!",
  ui_story_5028_50280602_28_dialog_content = "Revy! Mengenakan biaya!",
  ui_story_5028_50280602_29_dialog_content = "<color=#e8d9bb>Bang!</color>",
  ui_story_5028_50280602_30_dialog_content = "Bakar semuanya! Manticore!",
  ui_story_5028_50280602_31_dialog_content = "L-Ayo pergi dari sini! Orang-orang ini gila!",
  ui_story_5028_50280602_32_dialog_content = "Dengarkan! T-The <color=#FFB400>cambuk besi</color> dan bos kami <color=#FFB400>Gary</color> tidak akan pernah memaafkanmu untuk ini!",
  ui_story_5028_50280602_33_dialog_content = "Mereka melarikan diri.",
  ui_story_5028_50280602_34_dialog_content = "Kami datang mencari Caelestit, tapi yang kami temukan hanyalah sekelompok pemburu yang kejam...",
  ui_story_5028_50280602_35_dialog_content = "Untuk apa mereka berburu di sini? Aku ingin tahu apakah itu ada hubungannya dengan PlayerNamekesulitan?",
  ui_story_5028_50280602_36_dialog_content = "Cih... Seharusnya menangkap dan menginterogasi salah satu dari mereka selagi ada kesempatan.",
  ui_story_5028_50280602_37_dialog_content = "Yoohoo! Bukankah itu? PlayerNameteman-teman?",
  ui_story_5028_50280602_38_dialog_content = "Lola? Apa yang kamu lakukan di sini?",
  ui_story_5028_50280602_39_dialog_content = "Saya sedang mengirim surat ketika saya mendengar suara tembakan, jadi saya datang untuk menyelidiki. Apakah ada di antara kalian yang terluka?",
  ui_story_5028_50280602_40_dialog_content = "Kami sedang mencari Caelestite ketika sekelompok pemburu menyerang kami di depan mata.",
  ui_story_5028_50280602_41_dialog_content = "Tidak ada korban. Pemburu sudah lama pergi.",
  ui_story_5028_50280602_42_dialog_content = "Hah? Apakah Anda mengatakan \"Caelestit\"? Apakah ini berarti? PlayerName telah hilang?",
  ui_story_5028_50280602_43_dialog_content = "Tunggu, sekarang setelah Anda menyebutkannya ... Saya yakin saya melihat tanda-tanda kamp darurat dalam perjalanan ke sini! Mungkin kita bisa menemukan beberapa petunjuk di sana?",
  ui_story_5028_50280602_44_dialog_content = "Biarkan aku mengantarmu ke sana dulu, lalu aku akan pergi.",
  ui_story_5028_50280602_45_dialog_content = "Mengapa rasanya kami berubah menjadi semacam grup wisata?",
  ui_story_5028_50280602_46_dialog_content = "Bukankah lebih menyenangkan seperti ini? Mengambil semua jenis pemandangan, menendang pantat dari semua jenis musuh ...",
  ui_story_5028_50280602_47_dialog_content = "Oh ya, ini benar-benar liburan...",
  ui_story_5028_50280701_1_dialog_content = "Cobaan: Tahan Godaan Termanis",
  ui_story_5028_50280701_2_dialog_content = "Awan putih paling lembut, dan cabang lembut hijau",
  ui_story_5028_50280701_3_dialog_content = "Fia dan teman-temannya berbaris menuju pemandangan yang tak terlihat",
  ui_story_5028_50280701_4_dialog_content = "Dengan Caelestite di belakangnya, dunia cukup tenang",
  ui_story_5028_50280701_5_dialog_content = "Lo, lo, lo",
  ui_story_5028_50280701_6_dialog_content = "Anda tampaknya dalam suasana hati yang cukup baik.",
  ui_story_5028_50280701_7_dialog_content = "Heee! Saya tidak pernah berpikir kami hanya selangkah lagi untuk menyelesaikan semua uji coba dengan begitu cepat!",
  ui_story_5028_50280701_8_dialog_content = "Dan itu semua berkatmu, PlayerName! Kamu, Kyllo, dan yang lainnya adalah alasan semuanya berjalan begitu lancar!",
  ui_story_5028_50280701_9_dialog_content = "Aku sama terkejutnya.",
  ui_story_5028_50280701_10_dialog_content = "Pada awalnya, saya pikir Anda tidak akan mampu menangani banyak kesulitan dan Anda akan menyerah dengan cepat sehingga saya akan bebas dari cengkeraman misi terkutuk ini.",
  ui_story_5028_50280701_11_dialog_content = "Taruhan Anda tidak pernah menduga saya akan sangat bersemangat tentang binatang yang menakjubkan, ya?",
  ui_story_5028_50280701_12_dialog_content = "Sekarang jika kita bisa melakukan sesuatu tentang cara berperang Anda berbicara kepada orang-orang...",
  ui_story_5028_50280701_13_dialog_content = "Tidak tidak. Itu kekhasan khusus saya, tanpa itu saya akan kehilangan begitu banyak karisma!",
  ui_story_5028_50280701_14_dialog_content = "Masuk akal, kurasa. Itu adalah bagian dari apa yang membuatmu, yah... Kamu.",
  ui_story_5028_50280701_15_dialog_content = "Heee!",
  ui_story_5028_50280701_16_dialog_content = "(Memang, saya tahu bahwa di balik penampilan luarnya, Fia adalah orang yang baik hati dan lembut.)",
  ui_story_5028_50280701_16X_dialog_content = "(Makhluk kecil ini juga menyadarinya.)",
  ui_story_5028_50280701_17_dialog_content = "(Sesederhana mungkin, mereka cukup pintar untuk membedakan yang asli dari yang palsu... Dan kebaikan dari kekejaman.)",
  ui_story_5028_50280701_18_dialog_content = "(Hubungan dekat mereka adalah bukti yang cukup bahwa Fia adalah anak yang manis dan perhatian.)",
  ui_story_5028_50280701_19_dialog_content = "... Eh? Mengapa Anda melakukan zonasi?",
  ui_story_5028_50280701_20_dialog_content = "Apakah kamu haus? Ini, ambil airku.",
  ui_story_5028_50280701_21_dialog_content = "Kita harus berjalan sekitar setengah hari dari rumah tuanku. Tahan sebentar lagi.",
  ui_story_5028_50280701_22_dialog_content = "Oh! T-Tidak, terima kasih, aku tidak haus.",
  ui_story_5028_50280701_23_dialog_content = "Saya hanya ingin tahu... Apa yang Anda rencanakan setelah masa magang Anda berakhir?",
  ui_story_5028_50280701_24_dialog_content = "Rencana masa depan, ya? Saya pikir saya akan bepergian ke seluruh dunia dan mempelajari semua yang saya bisa tentang binatang yang menakjubkan. Setelah itu, saya harus bisa menulis buku yang bahkan akan menaungi karya master saya!",
  ui_story_5028_50280701_25_dialog_content = "Itu pasti terdengar seperti Anda, baiklah...",
  ui_story_5028_50280701_26_dialog_content = "Heee! Apa rencanamu, PlayerName?",
  ui_story_5028_50280701_27_dialog_content = "Cari tahu apa yang harus dilakukan tentang Drakolion, kurasa.",
  ui_story_5028_50280701_28_dialog_content = "Saya tidak ingin harus berurusan dengan naga terbang besar selama sisa hidup saya, Anda tahu?",
  ui_story_5028_50280701_29_dialog_content = "Tenang, saya akan membantu Anda mencari tahu.",
  ui_story_5028_50280701_30_dialog_content = "Drakolion mungkin akan membebaskan Colossus setelah musim kawinnya berakhir.",
  ui_story_5028_50280701_31_dialog_content = "Saya yakin berharap begitu.",
  ui_story_5028_50280701_32_dialog_content = "Soroz telah terbang berputar-putar di atas kita selama ini. Itu harus habis.",
  ui_story_5028_50280701_33_dialog_content = "Percayalah, saya punya ilmu dan pengetahuan untuk mendukung teori saya!",
  ui_story_5028_50280701_34_dialog_content = "Lihat!",
  ui_story_5028_50280701_35_dialog_content = "Benar, benar.",
  ui_story_5028_50280701_36_dialog_content = "... Hah? Apa itu?",
  ui_story_5028_50280701_37_dialog_content = "Sepertinya <color=#FFB400>patung</color> dari beberapa jenis.",
  ui_story_5028_50280701_38_dialog_content = "Saya rasa saya belum pernah melihat patung seperti ini sebelumnya.",
  ui_story_5028_50280701_39_dialog_content = "(Sungguh aneh... Patung ini memenuhi saya dengan rasa nyaman dan keakraban yang kuat.)",
  ui_story_5028_50280701_40_dialog_content = "Er... Apakah menurutmu kita harus pergi berdoa, atau apa? Kami dapat memintanya untuk memberkati Anda dengan akhir yang mulus untuk pencobaan Anda.",
  ui_story_5028_50280701_41_dialog_content = "Kurasa tidak ada salahnya... Ayo pergi!",
  ui_story_5028_50280701_42_dialog_content = "(Saat kami semakin dekat ke patung itu, rasa nyaman yang mengganggu itu semakin luar biasa.)",
  ui_story_5028_50280701_43_dialog_content = "Aku mungkin tidak tahu namamu, tapi tolong... Beri aku restumu, sehingga aku bisa menyelesaikan ujianku dan menjadi ahli ekstrozoologi sejati.",
  ui_story_5028_50280701_44_dialog_content = "Dan tolong berkati Drakolion dengan cinta yang baru ditemukan, sehingga Soroz akhirnya bisa kembali ke PlayerNamesisi.",
  ui_story_5028_50280701_45_dialog_content = "Dan juga memberkati Kyllo...",
  ui_story_5028_50280701_46_dialog_content = "Silahkan...",
  ui_story_5028_50280701_47_dialog_content = "...",
  ui_story_5028_50280701_48_dialog_content = "Hah? Tunggu... Ada yang tidak beres.",
  ui_story_5028_50280701_49_dialog_content = "Selamat, Fia!",
  ui_story_5028_50280701_50_dialog_content = "Selamat telah menyelesaikan uji coba Anda, dan menjadi ahli ekstrozoologi terhebat di dunia!",
  ui_story_5028_50280701_51_dialog_content = "Hah...? Menguasai?! aku yang terhebat?",
  ui_story_5028_50280701_52_dialog_content = "Betul sekali! Sekarang silahkan duduk.",
  ui_story_5028_50280701_53_dialog_content = "Prestasi saya pucat dibandingkan dengan Anda, Fia. Ketika berbicara tentang binatang buas yang menakjubkan, tidak ada orang lain di dunia ini yang bisa mengetahui sebanyak Anda!",
  ui_story_5028_50280701_54_dialog_content = "Perbedaan antara kita seperti siang dan malam! Saya hanya berharap bahwa Anda akan menemukannya di hati Anda untuk menerima saya sebagai murid Anda, jadi saya bisa belajar semua yang saya bisa dari Anda!",
  ui_story_5028_50280701_55_dialog_content = "Heehee... Aku tidak begitu hebat, tapi aku akan memikirkannya!",
  ui_story_5028_50280701_56_dialog_content = "Nona Fia.",
  ui_story_5028_50280701_57_dialog_content = "Hah? Kamu siapa?",
  ui_story_5028_50280701_58_dialog_content = "Perbuatan besar Anda dikenal di seluruh negeri, dan saya adalah salah satu penggemar Anda.",
  ui_story_5028_50280701_59_dialog_content = "Pengikut Anda siap membantu dan mendukung Anda dalam petualangan berikutnya.",
  ui_story_5028_50280701_60_dialog_content = "Fi! Fi! Fi!",
  ui_story_5028_50280701_61_dialog_content = "Wah! Mereka semua fansku?",
  ui_story_5028_50280701_62_dialog_content = "Hehe! Saya kira secara alami, pencapaian besar menarik pengagum seperti magnet.",
  ui_story_5028_50280701_63_dialog_content = "Tunggu... Sepertinya aku melupakan seseorang yang penting.",
  ui_story_5028_50280701_64_dialog_content = "PlayerName! Dimana PlayerName?",
  ui_story_5028_50280701_65_dialog_content = "<color=#e8d9bb>Sementara itu...</color>",
  ui_story_5028_50280701_66_dialog_content = "Huh... Kenapa aku kembali ke Colossus? dimana saya?",
  ui_story_5028_50280701_67_dialog_content = "Begitu banyak kayu! Ini bagus! Aku tidak sedang bermimpi, kan?",
  ui_story_5028_50280701_68_dialog_content = "Ah! Apa pun. Aku akan segera merekrut Aurorian dengan Lumamber! Mari kita mulai dengan 100 tarikan!",
  ui_story_5028_50280701_69_dialog_content = "<color=#e8d9bb>Berdebar-!</color>",
  ui_story_5028_50280701_70_dialog_content = "<color=#e8d9bb>Buk, Buk—!</color>",
  ui_story_5028_50280701_71_dialog_content = "Hm? Apakah seseorang berkelahi ...?",
  ui_story_5028_50280701_72_dialog_content = "Bangun, bodoh!",
  ui_story_5028_50280701_73_dialog_content = "Mengapa saya mendengar seseorang memarahi saya?",
  ui_story_5028_50280701_74_dialog_content = "J-Hanya sepuluh tarikan lagi!",
  ui_story_5028_50280701_75_dialog_content = "Astaga!",
  ui_story_5028_50280701_76_dialog_content = "Ah!",
  ui_story_5028_50280701_77_dialog_content = "E-Eclipsites?!",
  ui_story_5028_50280701_78_dialog_content = "A-Apa yang terjadi?",
  ui_story_5028_50280701_79_dialog_content = "F-Fia? Di mana kita...? Dan dari mana Eclipsites ini berasal? Dan siapa Anda?!",
  ui_story_5028_50280701_80_dialog_content = "Berhenti mengoceh dan bangun dan bertarung!",
  ui_story_5028_50280701_81_dialog_content = "<size=45>Astaga!</size>",
  ui_story_5028_50280701_82_dialog_content = "Fi!",
  ui_story_5028_50280701_83_dialog_content = "G-Mengerti! PlayerName, Mari kita lakukan! Kyllo!",
  ui_story_5028_50280702_1_dialog_content = "Aku tidak percaya kita diserang oleh Eclipsites.",
  ui_story_5028_50280702_2_dialog_content = "Tapi bagaimana caranya? Hal terakhir yang saya ingat adalah berdoa kepada patung itu.",
  ui_story_5028_50280702_3_dialog_content = "Lalu, tiba-tiba... Aku bermimpi menjadi ahli ekstrozoologi terhebat di dunia.",
  ui_story_5028_50280702_4_dialog_content = "Ya, sama di sini... Hanya saja aku bermimpi tentang tumpukan ungu dan emas yang berkilauan...",
  ui_story_5028_50280702_5_dialog_content = "Dan kemudian, banyak Aurorian yang pernah saya kenal datang ke sisi saya, dan saya bahkan menjadi teman baik dengan beberapa yang tidak bersama kami lagi.",
  ui_story_5028_50280702_6_dialog_content = "Kalian berdua benar-benar memiliki fantasi yang menarik...",
  ui_story_5028_50280702_7_dialog_content = "Tadi kamu bilang kamu berdoa ke patung, kan?",
  ui_story_5028_50280702_8_dialog_content = "Ya mengapa?",
  ui_story_5028_50280702_9_dialog_content = "Anda berdoa kepada berhala yang aneh... Dan Anda bahkan tidak tahu apa itu?",
  ui_story_5028_50280702_10_dialog_content = "Jika Anda benar-benar tidak menyadari bahaya, Anda bisa melupakan semua tentang menjadi seorang ahli ekstrozoologi.",
  ui_story_5028_50280702_11_dialog_content = "Anda masih punya waktu untuk menerima wajib belajar di Illumina. Setidaknya Anda bisa mendapatkan pekerjaan di pabrik senjata di suatu tempat setelah lulus.",
  ui_story_5028_50280702_12_dialog_content = "Apa katamu?!?",
  ui_story_5028_50280702_13_dialog_content = "Kamu pikir kamu siapa, berbicara padaku seperti itu?!",
  ui_story_5028_50280702_14_dialog_content = "Jangan berpikir Anda bisa mengatakan apa pun yang Anda inginkan hanya karena Anda pernah membantu saya!",
  ui_story_5028_50280702_15_dialog_content = "Siap menyerang, Kyllo!",
  ui_story_5028_50280702_16_dialog_content = "...",
  ui_story_5028_50280702_17_dialog_content = "Kyllo?",
  ui_story_5028_50280702_18_dialog_content = "Binatang buas yang menakjubkan itu tidak bersama kita... Aku tidak bisa merasakannya sama sekali.",
  ui_story_5028_50280702_19_dialog_content = "bodoh.",
  ui_story_5028_50280702_20_dialog_content = "Aku tidak punya alasan untuk memberitahumu siapa aku.",
  ui_story_5028_50280702_21_dialog_content = "Tapi saya tahu... Anda ingin menjadi ahli ekstrozoologi meskipun begitu naif dan ceroboh.",
  ui_story_5028_50280702_22_dialog_content = "Dimana kamu, Kyl? Anda tidak bermain petak umpet, kan?",
  ui_story_5028_50280702_23_dialog_content = "Jika aku jadi kamu, aku sudah menyerah!",
  ui_story_5028_50280702_24_dialog_content = "Mereka bukan mainan untuk Anda mainkan sesuka Anda, atau hewan peliharaan untuk Anda manja dan manja.",
  ui_story_5028_50280702_25_dialog_content = "Tanpa dedikasi atau tekad, Anda tidak akan pernah mengatasi rintangan di depan... Anda bahkan tidak akan sampai di tengah jalan sebelum Anda hancur.",
  ui_story_5028_50280702_26_dialog_content = "kylo... kylo...",
  ui_story_5028_50280702_27_dialog_content = "Ketidakdewasaan Anda juga akan merugikan orang lain, termasuk apa yang Anda sebut \"teman\".",
  ui_story_5028_50280702_28_dialog_content = "K-Kamu... Kamu tahu di mana mereka, bukan?",
  ui_story_5028_50280702_29_dialog_content = "Kumohon, kumohon... Katakan padaku di mana Kyllo dan yang lainnya!",
  ui_story_5028_50280702_30_dialog_content = "Apakah kamu tidak mendengar apa pun yang baru saja saya katakan, bodoh?",
  ui_story_5028_50280702_31_dialog_content = "Tidak ada tanda-tanda Kyllo dan yang lainnya di sini... Atau persediaan dan perlengkapan kita, dalam hal ini.",
  ui_story_5028_50280702_32_dialog_content = "Sekarang bukan waktunya untuk mengkhawatirkan hal itu! Tolong... Katakan di mana mereka!",
  ui_story_5028_50280702_33_dialog_content = "Tuanku memercayaiku dengan mereka... Mereka adalah teman tersayangku, jadi jika kau tahu di mana mereka bisa berada, bahkan petunjuk terkecil sekalipun... Aku ingin kau memberitahuku!",
  ui_story_5028_50280702_34_dialog_content = "... Ekspresi bodoh di wajahmu itu benar-benar memalukan.",
  ui_story_5028_50280702_35_dialog_content = "Saya pergi. Anda dapat berdiri di sekitar sini selama sisa hidup Anda, untuk semua yang saya pedulikan.",
  ui_story_5028_50280702_36_dialog_content = "\"Teman-teman\" yang merepotkan dari Anda tidak akan menunggu sepanjang hari sementara Anda terus murung dan mengasihani diri sendiri.",
  ui_story_5028_50280702_37_dialog_content = "Anak-anak benar-benar menyakitkan ...",
  ui_story_5028_50280702_38_dialog_content = "Fi!",
  ui_story_5028_50280702_39_dialog_content = "Ya!",
  ui_story_5028_50280702_40_dialog_content = "Barang-barang kita mungkin hilang, tapi yang terpenting sekarang adalah menemukan Kyllo dan yang lainnya!",
  ui_story_5028_50280702_41_dialog_content = "Tunggu, Fia!",
  ui_story_5028_50280702_42_dialog_content = "Sepertinya gadis itu meninggalkan sesuatu...",
  ui_story_5028_50280702_43_dialog_content = "Ini adalah kompas... Dan beberapa perlengkapan penting lainnya untuk bertahan hidup di hutan belantara.",
  ui_story_5028_50280702_44_dialog_content = "Itu bukan perlengkapanku sendiri, tapi kelihatannya cukup baru... Aku yakin itu miliknya. Dia pasti sengaja meninggalkannya untuk kita.",
  ui_story_5028_50280702_45_dialog_content = "Dia mengatakan banyak hal jahat barusan, tapi dia mungkin sebenarnya orang yang baik.",
  ui_story_5028_50280702_46_dialog_content = "Ya! Aku harus berterima kasih padanya dengan benar saat kita bertemu lagi nanti.",
  ui_story_5028_50280702_47_dialog_content = "Kau tahu, dia sepertinya sedikit familiar... Aku merasa seperti pernah melihatnya di suatu tempat sebelumnya.",
  ui_story_5028_50280702_48_dialog_content = "Kyllo!",
  ui_story_5028_50280702_49_dialog_content = "Lihat!!!",
  ui_story_5028_50280702_50_dialog_content = "gelap...",
  ui_story_5028_50280702_51_dialog_content = "Hai!",
  ui_story_5028_50280702_52_dialog_content = "peko!",
  ui_story_5028_50280702_53_dialog_content = "Syukurlah... Mereka sudah menunggu kami kembali di patung selama ini!",
  ui_story_5028_50280702_54_dialog_content = "Tapi apa yang membuat kita tertidur di tempat pertama? Dan bagaimana kita berakhir di sana?",
  ui_story_5028_50280702_55_dialog_content = "Lihat! halo!",
  ui_story_5028_50280702_56_dialog_content = "Sepertinya Kyllo menunjuk ke arah patung itu...",
  ui_story_5028_50280702_57_dialog_content = "Mungkin ada yang salah?",
  ui_story_5028_50280702_58_dialog_content = "Ugh...",
  ui_story_5028_50280702_59_dialog_content = "Itu... Itu baru saja pindah! Patung itu bergerak!",
  ui_story_5028_50280702_60_dialog_content = "Tidak... Benda itu bukan patung!",
  ui_story_5028_50280702_61_dialog_content = "Ini adalah <color=#FFB400>Burung Hantu Lutumi</color>, sejenis binatang yang menakjubkan! Saya tidak pernah berharap untuk bertemu satu di sini, meskipun ...",
  ui_story_5028_50280702_62_dialog_content = "Guru saya pernah mengatakan kepada saya bahwa mereka sangat langka sehingga mereka mungkin sudah punah. Bahkan Encyclopedia Exotica hampir tidak memiliki informasi apapun tentang mereka...",
  ui_story_5028_50280702_63_dialog_content = "Yang kita tahu hanyalah bahwa ia berpura-pura menjadi patung dan menggoda para korbannya untuk beribadah dalam keadaan kesurupan.",
  ui_story_5028_50280702_63X_dialog_content = "Begitu mereka tertidur, Burung Hantu Lutumi merampas barang berharga yang bisa mereka temukan.",
  ui_story_5028_50280702_64_dialog_content = "Gaah... Graaah...",
  ui_story_5028_50280702_65_dialog_content = "Barang berharga? Tapi untuk apa mereka membutuhkannya?",
  ui_story_5028_50280702_66_dialog_content = "Ini kemungkinan besar tertarik pada benda-benda mengkilap seperti koin, seperti banyak hewan lain.",
  ui_story_5028_50280702_67_dialog_content = "Mendekut!",
  ui_story_5028_50280702_68_dialog_content = "Oh tidak, itu semakin menjauh!",
  ui_story_5028_50280702_69_dialog_content = "Lihat!",
  ui_story_5028_50280702_70_dialog_content = "Kerja bagus, Kylo! Jangan biarkan itu lolos!",
  ui_story_5028_50280702_71_dialog_content = "Ah! Kena kau!",
  ui_story_5028_50280702_72_dialog_content = "Gaaah!",
  ui_story_5028_50280702_73_option_content = "Kocok Burung Hantu Lutumi",
  ui_story_5028_50280702_74_dialog_content = "Lihat, PlayerName! Beberapa barang kami jatuh dari tubuhnya!",
  ui_story_5028_50280702_75_option_content = "Goyang terus",
  ui_story_5028_50280702_76_dialog_content = "Kacau!",
  ui_story_5028_50280702_77_dialog_content = "<color=#e8d9bb>Kocok, kocok, kocok!</color>",
  ui_story_5028_50280702_78_dialog_content = "Gaaah!",
  ui_story_5028_50280702_79_dialog_content = "Lebih banyak barang terus jatuh! Sebuah kaleng dari Illumina, beberapa Nightium... Dan lihat, bahkan batu permata dari Northland!",
  ui_story_5028_50280702_80_dialog_content = "Siapa yang tahu berapa banyak orang yang menjadi korban orang ini selama bertahun-tahun... Mari kita tinggalkan barang-barang mereka di sini.",
  ui_story_5028_50280702_81_dialog_content = "Heehee... Baiklah, burung nakal, saatnya menentukan pilihan.",
  ui_story_5028_50280702_82_dialog_content = "Menggeram?",
  ui_story_5028_50280702_83_dialog_content = "Apakah Anda ingin saya mengeluarkan hukuman Anda di sini dan sekarang?",
  ui_story_5028_50280702_84_dialog_content = "Kaok kaok!!",
  ui_story_5028_50280702_85_dialog_content = "Atau akankah Anda melepaskan cara mencuri Anda dan bergabung dengan saya dalam perjalanan saya?",
  ui_story_5028_50280702_86_dialog_content = "Ugh...",
  ui_story_5028_50280702_87_dialog_content = "Gaaah!",
  ui_story_5028_50280702_88_dialog_content = "Heehee, saya pikir begitu! Sekarang mari kita bergerak!",
  ui_story_5028_50280702_89_dialog_content = "Kami sedang dalam perjalanan untuk melihat Guru saya. Saya yakin dia akan senang melihat Anda, dan untuk melihat seberapa jauh muridnya yang tersayang telah datang!",
  ui_story_5028_50280702_90_dialog_content = "Wah...",
  ui_story_5028_50280702_91_dialog_content = "Dengung...",
  ui_story_5028_50280702_92_dialog_content = "Zzz... Gram! Lain!!",
  ui_story_5028_50280702_93_dialog_content = "Kami... tertidur?",
  ui_story_5028_50280702_94_dialog_content = "Bangun! Bangun!",
  ui_story_5028_50280702_95_dialog_content = "Kami telah jatuh untuk itu!",
  ui_story_5028_50280702_96_dialog_content = "Heh... Sepertinya kita semua tertipu oleh trik patung bodoh itu.",
  ui_story_5028_50280702_97_dialog_content = "Saya terus mengatakan bahwa kita seharusnya tidak berdoa untuk itu, tapi tid...",
  ui_story_5028_50280702_98_dialog_content = "Romantis adalah omong kosong. Apakah Anda mulai mengalami delusi karena usia tua atau semacamnya?",
  ui_story_5028_50280702_99_dialog_content = "Lihat saja ini... Semua barang kita hilang.",
  ui_story_5028_50280702_100_dialog_content = "A-Apa yang kamu bicarakan?! Aku hanya berdoa agar aku bisa mengalahkanmu suatu hari nanti...",
  ui_story_5028_50280702_101_dialog_content = "Jika Anda punya waktu untuk mengejek saya, mengapa Anda tidak menggunakannya untuk menemukan peralatan kami yang hilang?",
  ui_story_5028_50280702_102_dialog_content = "Di mana patung itu yang perlu ditendang?",
  ui_story_5028_50280702_103_dialog_content = "Itu hilang?",
  ui_story_5028_50280702_104_dialog_content = "Tunggu, aku melihat sesuatu di sana.",
  ui_story_5028_50280702_105_dialog_content = "Hai, Smokey... Bukankah ini pick gitar metalmu?",
  ui_story_5028_50280702_106_dialog_content = "Itu dia. Eh, maksudku... Ini sebenarnya pembuka botol!",
  ui_story_5028_50280702_107_dialog_content = "Apakah semuanya ada di sini?",
  ui_story_5028_50280702_108_dialog_content = "Barang ada di sini. Patung tidak.",
  ui_story_5028_50280702_109_dialog_content = "Juga... Aku mencium bau Caelestit.",
  ui_story_5028_50280801_1_dialog_content = "Oh, maaaasterrr! Tebak siapa yang kembali?",
  ui_story_5028_50280801_2_dialog_content = "Butuh beberapa waktu, tetapi saya akhirnya menyelesaikan uji coba gila Anda!",
  ui_story_5028_50280801_X2_dialog_content = "Tapi terlepas dari apa yang Anda katakan kepada saya, Kyllo tidak pernah \"berevolusi.\" Ada apa dengan itu?",
  ui_story_5028_50280801_3_dialog_content = "Permisi...",
  ui_story_5028_50280801_4_dialog_content = "(Tempat ini... sangat berantakan!)",
  ui_story_5028_50280801_5_dialog_content = "(Semua buku ini dibiarkan berserakan di mana-mana... Apakah Tuannya tidak tahu bagaimana mengambilnya sendiri?!)",
  ui_story_5028_50280801_6_dialog_content = "Jadi apa yang Anda katakan, Guru? Apakah magang saya akhirnya selesai, atau...",
  ui_story_5028_50280801_7_dialog_content = "Apa yang terjadi disini? Berantakan sekali!",
  ui_story_5028_50280801_8_dialog_content = "Oh... Maksudmu tidak selalu seperti ini?",
  ui_story_5028_50280801_9_dialog_content = "Tidak... Maksudku, kekacauannya memiliki urutan tertentu.",
  ui_story_5028_50280801_10_dialog_content = "Apa yang mungkin terlihat seperti tumpukan buku acak sebenarnya adalah pilihan informasi berharga yang diatur dengan cermat.",
  ui_story_5028_50280801_11_dialog_content = "Dia mengurutkan semua buku dalam tumpukan berdasarkan kategorinya.",
  ui_story_5028_50280801_12_dialog_content = "Dia juga cenderung meninggalkan buku-buku yang belum selesai dia baca terbuka lebar di tumpukan paling atas. Itu sebabnya mereka tampak tidak teratur.",
  ui_story_5028_50280801_13_dialog_content = "Tapi lihatlah! Kategori tumpukan ini adalah Entomologi, namun dua buku paling atas adalah tentang makhluk air.",
  ui_story_5028_50280801_14_dialog_content = "Guru botak paruh baya saya mungkin tampak tidak terlalu bisa diandalkan, tetapi dia tidak akan pernah salah menaruhkan buku-bukunya seperti ini!",
  ui_story_5028_50280801_15_dialog_content = "Jadi itu berarti... ada orang lain di sini, mengotak-atik buku Vic?",
  ui_story_5028_50280801_16_dialog_content = "Sangat mungkin... Tapi prioritasnya adalah menemukannya segera!",
  ui_story_5028_50280801_17_dialog_content = "Menguasai! Kemana kamu kabur kali ini?! Ayo keluar!",
  ui_story_5028_50280801_18_dialog_content = "<size=45>Halo?!</size>",
  ui_story_5028_50280801_19_option_content = "Vik!",
  ui_story_5028_50280801_20_dialog_content = "...",
  ui_story_5028_50280801_21_dialog_content = "Saya tidak berpikir dia ada di sini ...",
  ui_story_5028_50280801_22_dialog_content = "Laci-laci telah ditarik keluar dan kursinya tidak pada tempatnya... Dan pintu lemari, yang dengan tegas dia larang untuk aku sentuh... berdiri terbuka.",
  ui_story_5028_50280801_23_dialog_content = "Sepertinya Vic pergi dengan tergesa-gesa.",
  ui_story_5028_50280801_24_dialog_content = "Dan ruangan itu benar-benar berantakan. Jangan bilang padaku...",
  ui_story_5028_50280801_25_dialog_content = "Saya khawatir Anda benar tentang yang satu ini. Vic mungkin telah diculik...",
  ui_story_5028_50280801_26_dialog_content = "Dia pasti membohongiku selama ini, jadi dia malah lari daripada menungguku kembali!!!",
  ui_story_5028_50280801_27_dialog_content = "Hah?",
  ui_story_5028_50280801_28_dialog_content = "Tidak ada penjelasan lain!",
  ui_story_5028_50280801_29_dialog_content = "J-Tidakkah menurutmu kita setidaknya harus mempertimbangkan kemungkinan dia diculik?",
  ui_story_5028_50280801_30_dialog_content = "Apa?!",
  ui_story_5028_50280801_31_dialog_content = "Hah? Er... T-Tentu saja! Saya sudah memikirkan itu!",
  ui_story_5028_50280801_32_dialog_content = "Hanya saja... Aku benar-benar tidak bisa memikirkan siapa pun yang ingin menculik seseorang seperti Tuanku, kau tahu?",
  ui_story_5028_50280801_33_dialog_content = "Dia tidak bergerak, dia minum seperti ikan, dan dia bahkan tidak punya dua Nightium untuk digosok di dompetnya...",
  ui_story_5028_50280801_34_dialog_content = "Uh... Haruskah kau benar-benar membicarakan dia seperti itu? Dia adalah Tuanmu, bagaimanapun juga...",
  ui_story_5028_50280801_35_dialog_content = "Ngomong-ngomong, menurutmu apa yang harus kita lakukan sekarang?",
  ui_story_5028_50280801_36_dialog_content = "Nah, jika kita tidak menemukan Guru saya, saya tidak akan pernah bisa lulus menjadi ahli ekstrozoologi.",
  ui_story_5028_50280801_37_dialog_content = "Jadi kurasa kita harus mulai dengan mencarinya.",
  ui_story_5028_50280801_38_dialog_content = "Kalau begitu mari kita cari di area itu untuk mencari petunjuk yang bisa mengarahkan kita ke arah Vic.",
  ui_story_5028_50280801_39_dialog_content = "Hmph. Guru pasti sangat senang membuat orang lain khawatir.",
  ui_story_5028_50280801_40_dialog_content = "Baik-baik saja maka! Saatnya berburu petunjuk!",
  ui_story_5028_50280801_41_dialog_content = "<color=#e8d9bb>Dentang!</color>",
  ui_story_5028_50280801_42_dialog_content = "<color=#e8d9bb>Memukul! Menghancurkan!</color>",
  ui_story_5028_50280801_43_dialog_content = "Berhenti, berhenti, berhenti!",
  ui_story_5028_50280801_44_dialog_content = "Anda menyebut ini \"berburu petunjuk\"?! Anda praktis menghancurkan TKP!",
  ui_story_5028_50280801_45_dialog_content = "Aku baru saja menjatuhkan beberapa hal, itu saja! Aku bersumpah aku mencari sekuat yang aku bisa!",
  ui_story_5028_50280801_46_dialog_content = "Pada tingkat ini, \"penampilan\" Anda akan menjatuhkan rumah di atas kepala kami ...",
  ui_story_5028_50280801_47_dialog_content = "Aku tidak begitu ceroboh!",
  ui_story_5028_50280801_48_dialog_content = "Hmm... Biar aku yang urus ini.",
  ui_story_5028_50280801_49_dialog_content = "Jika tidak, rumah, serta petunjuknya, akan hancur semua.",
  ui_story_5028_50280801_50_dialog_content = "Kenapa kamu...!",
  ui_story_5028_50280801_51_dialog_content = "Dan kita akan memiliki hari yang agak sibuk pada akhirnya.",
  ui_story_5028_50280801_52_dialog_content = "Sekarang di mana saya harus memulai pencarian saya?",
  ui_story_5028_50280801_53_option_content = "Periksa meja",
  ui_story_5028_50280801_54_dialog_content = "Semua lacinya telah ditarik keluar. Sepertinya seseorang dengan tergesa-gesa mengobrak-abrik isinya...",
  ui_story_5028_50280801_55_dialog_content = "Tuanku biasanya melemparkan barang-barang ke dalam laci, tetapi laci-laci itu memiliki kategori, sama seperti buku-bukunya.",
  ui_story_5028_50280801_56_dialog_content = "Apa isi laci kosong ini?",
  ui_story_5028_50280801_57_dialog_content = "Biarkan aku berpikir... Dia sepertinya menyimpan beberapa catatan tentang binatang buas yang menakjubkan di sana.",
  ui_story_5028_50280801_58_dialog_content = "Ketika Tuan saya pertama kali mempercayakan saya dengan Kyllo, dia mengeluarkan catatan itu dan memeriksanya sebelum membuat keputusan terakhirnya.",
  ui_story_5028_50280801_59_dialog_content = "Hanya saja, saya tidak melihat catatannya di mana pun ...",
  ui_story_5028_50280801_60_dialog_content = "Tunggu, ada secarik kertas di bawah meja!",
  ui_story_5028_50280801_61_dialog_content = "Tunjukkan kepadaku!",
  ui_story_5028_50280801_62_dialog_content = "Ini adalah gambar lingkaran dengan \"X\" di dalamnya...",
  ui_story_5028_50280801_63_dialog_content = "Tulisan tangannya terlihat tergesa-gesa, dan tintanya masih sedikit segar... Ini tidak mungkin ditulis selama itu!",
  ui_story_5028_50280801_64_dialog_content = "Mungkinkah ini semacam pesan rahasia?",
  ui_story_5028_50280801_65_dialog_content = "saya tidak yakin...",
  ui_story_5028_50280801_66_option_content = "Periksa rak buku",
  ui_story_5028_50280801_67_dialog_content = "Buku-buku di rak ini semua tertata rapi.",
  ui_story_5028_50280801_68_dialog_content = "Tapi itu karena Tuanku tidak terlalu peduli untuk membaca buku-buku ini... Dan karena dia bukan tipe orang yang membersihkan secara teratur, semua buku ini memiliki lapisan debu yang tebal.",
  ui_story_5028_50280801_69_dialog_content = "Lihat, buku di rak paling atas itu tidak berdebu! Seolah-olah itu telah dibaca secara teratur ...",
  ui_story_5028_50280801_70_dialog_content = "Kita harus melihat lebih dekat!",
  ui_story_5028_50280801_71_dialog_content = "Grr... Aku tidak bisa mencapai sana!",
  ui_story_5028_50280801_72_dialog_content = "Ptui!",
  ui_story_5028_50280801_73_dialog_content = "Itu tidak lucu! Berhenti tertawa!",
  ui_story_5028_50280801_74_dialog_content = "Jika Anda begitu tinggi, PlayerName, dapatkan itu untukku.",
  ui_story_5028_50280801_75_dialog_content = "Yo-ho! Ini dia.",
  ui_story_5028_50280801_76_dialog_content = "Hmm? Ada foto lama terselip di antara halaman-halaman buku ini.",
  ui_story_5028_50280801_77_dialog_content = "Kelihatannya seperti Master Vic, tetapi separuh foto lainnya telah robek...",
  ui_story_5028_50280801_78_dialog_content = "Pasti sangat penting bagi Tuanku jika dia menyimpannya selama ini.",
  ui_story_5028_50280801_79_dialog_content = "Orang lain di foto itu... Aku ingin tahu siapa itu?",
  ui_story_5028_50280801_80_dialog_content = "Kami telah mencari begitu lama sehingga rasanya seperti kaki saya akan jatuh, tetapi kami hampir tidak membuat kemajuan apa pun ...",
  ui_story_5028_50280801_81_dialog_content = "Apa yang harus kita lakukan sekarang?",
  ui_story_5028_50280801_82_dialog_content = "...",
  ui_story_5028_50280801_83_dialog_content = "Eh, Fia...?",
  ui_story_5028_50280801_84_dialog_content = "Apakah Anda tiba-tiba merasakan hawa dingin di punggung Anda? Karena aku...",
  ui_story_5028_50280801_85_dialog_content = "aku... aku juga merasakannya...",
  ui_story_5028_50280801_86_dialog_content = "Kenapa kamu...",
  ui_story_5028_50280801_87_dialog_content = "Ahhh!",
  ui_story_5028_50280801_88_dialog_content = "Itu... Ini dia lagi!!",
  ui_story_5028_50280801_89_dialog_content = "Itu satu hal jika Anda datang untuk merampok tempat itu karena sebenarnya tidak ada sesuatu yang berharga di sini ...",
  ui_story_5028_50280801_90_dialog_content = "Tapi menghancurkan rumah seperti ini... benar-benar tak termaafkan.",
  ui_story_5028_50280801_91_dialog_content = "Ini akan menjadi proses yang melelahkan untuk mengatur semua buku ini...",
  ui_story_5028_50280801_92_dialog_content = "Dengan pintu lemari terbuka, koleksi di dalamnya mengumpulkan banyak debu. Butuh berhari-hari untuk membersihkan kekacauan ini...",
  ui_story_5028_50280801_93_dialog_content = "Yang lebih buruk, peta binatang yang menakjubkan dan manuskrip berharga itu, yang keduanya membutuhkan waktu bertahun-tahun untuk menyusun penelitian yang melelahkan... tidak terlihat di mana pun!",
  ui_story_5028_50280801_94_dialog_content = "Y-Ya! Saya sangat setuju!",
  ui_story_5028_50280801_95_dialog_content = "T-Tapi jangan khawatir, Nona!",
  ui_story_5028_50280801_96_dialog_content = "Kami akan melakukan semua yang kami bisa untuk...",
  ui_story_5028_50280801_97_dialog_content = "Tidak.",
  ui_story_5028_50280801_98_dialog_content = "Untuk mengkompensasi saya? Tolong... Anda tidak akan pernah bisa berharap untuk membayar file saya yang tak ternilai!",
  ui_story_5028_50280801_99_dialog_content = "Tunggu apa?! Kami tidak mencuri mereka, meskipun!!",
  ui_story_5028_50280801_100_dialog_content = "Dia mengatakan yang sebenarnya! Kami datang mencari Master Vic, tapi dia hilang... Dan rumahnya persis seperti ini saat kami tiba di sini!",
  ui_story_5028_50280801_101_dialog_content = "Eh, kecuali beberapa hal yang aku temui saat mencari petunjuk: kursi, dua vas, tiga gelas kaca...",
  ui_story_5028_50280801_102_dialog_content = "Tunggu dulu, Fia!",
  ui_story_5028_50280801_103_dialog_content = "Simpan itu. Aku menangkapmu pencuri dengan tangan merah.",
  ui_story_5028_50280801_104_dialog_content = "Awalnya, saya pikir Anda hanya dua penggemar binatang biasa yang menakjubkan... tapi sekarang saya tahu Anda hanyalah penjahat kelas bawah.",
  ui_story_5028_50280801_105_dialog_content = "Hanya mengaku bersalah dan membayar apa yang Anda berutang.",
  ui_story_5028_50280801_110_dialog_content = "Apakah Anda bahkan mendengarkan, Anda preman? Kami sudah memberi tahu Anda bahwa itu bukan kami!",
  ui_story_5028_50280801_112_dialog_content = "Astaga?!",
  ui_story_5028_50280801_113_dialog_content = "A-Apa sih?! Kamu tidak bisa mulai menyerang seperti itu di sini!!",
  ui_story_5028_50280801_114_dialog_content = "Aku juga tidak ingin melawanmu. Lagipula, hanya menggerakkan jari atau tentakelku sudah cukup melelahkan.",
  ui_story_5028_50280801_X114_dialog_content = "Jadi saya akan memberi Anda satu kesempatan terakhir untuk menjelaskan diri Anda sendiri.",
  ui_story_5028_50280801_115_dialog_content = "Itu bukan kami, aku bersumpah—",
  ui_story_5028_50280801_116_dialog_content = "Ahhh!",
  ui_story_5028_50280801_117_dialog_content = "<color=#e8d9bb>Kaboom!</color>",
  ui_story_5028_50280801_118_dialog_content = "I-Ada lubang besar di mana tentakel itu barusan menyerang...",
  ui_story_5028_50280801_119_dialog_content = "Aku akan mati jika itu menimpaku!",
  ui_story_5028_50280801_120_dialog_content = "Betul sekali. Anda akan berada di dunia kesakitan.",
  ui_story_5028_50280801_121_dialog_content = "Tolong berhenti! Kami benar-benar tidak datang ke sini untuk mencuri apa pun!",
  ui_story_5028_50280801_122_dialog_content = "Kami hanya mencari petunjuk! Kami mencoba melacak Vic!",
  ui_story_5028_50280801_123_dialog_content = "Guru... telah hilang? Tapi jika kalian berdua bukan pelakunya, lalu siapa yang seharusnya?",
  ui_story_5028_50280801_124_dialog_content = "Kami juga tidak tahu...",
  ui_story_5028_50280801_125_dialog_content = "Tapi kami berhasil menemukan beberapa petunjuk!",
  ui_story_5028_50280801_126_dialog_content = "Petunjuk, ya? Menemukan petunjuk bisa jadi terlalu menyusahkan, dan bernalar bisa jadi lebih menyakitkan. Anda mungkin juga meludahkannya.",
  ui_story_5028_50280801_127_dialog_content = "Jadi katakan padaku, apa yang kalian berdua temukan?",
  ui_story_5028_50280801_128_dialog_content = "Guru meninggalkan ini, gambar lingkaran dengan \"X\" di dalamnya. Kami pikir itu ditarik cukup baru-baru ini!",
  ui_story_5028_50280801_129_dialog_content = "Ya. Kami juga menemukan foto ini di dalam sebuah buku.",
  ui_story_5028_50280801_130_dialog_content = "Tunggu... Vic adalah Master yang kau maksud selama ini?",
  ui_story_5028_50280801_131_dialog_content = "Oh ya!",
  ui_story_5028_50280801_132_dialog_content = "Yap, saya belajar di bawah dia untuk sementara waktu. Sekarang setelah saya selesai dengan cobaannya, masa magang saya akan segera selesai!",
  ui_story_5028_50280801_133_dialog_content = "Kyllo inilah bukti saya: itu dipercayakan kepada saya oleh Tuan saya!",
  ui_story_5028_50280801_134_dialog_content = "Eh... Kyllo?",
  ui_story_5028_50280801_135_dialog_content = "lihat? Hallo...",
  ui_story_5028_50280801_136_dialog_content = "Anda disana! Apa yang kamu lakukan, tidur di antara buku-buku itu? Ayo keluar!",
  ui_story_5028_50280801_137_dialog_content = "Itu persisnya Vic's Kyllo. Dan itu juga tidak menolakmu...",
  ui_story_5028_50280801_138_dialog_content = "Nah, karena bersedia mempercayai Anda, saya tidak punya banyak alasan untuk terus meragukan Anda.",
  ui_story_5028_50280801_139_dialog_content = "Oh, jadi SEKARANG kamu percaya padaku!",
  ui_story_5028_50280801_140_dialog_content = "Aduh... Sepertinya dia mendapat masalah saat aku keluar mencari binatang yang menakjubkan.",
  ui_story_5028_50280801_141_dialog_content = "Menjaga anak jelas merupakan bagian terberat.",
  ui_story_5028_50280801_142_dialog_content = "Aku bukan anak kecil!",
  ui_story_5028_50280801_143_dialog_content = "Siapa sebenarnya kamu? Dan bagaimana Anda tahu begitu banyak tentang Guru saya?",
  ui_story_5028_50280801_144_dialog_content = "Siapa saya? Huh, siapa aku sebenarnya...",
  ui_story_5028_50280801_145_dialog_content = "Saya tahu bahwa hubungan antara orang-orang terkadang sangat merepotkan untuk diingat...",
  ui_story_5028_50280801_146_dialog_content = "Sederhananya, jika Vic adalah orang yang Anda panggil Guru, maka itu kurang lebih membuat saya menjadi senior Anda.",
  ui_story_5028_50280801_147_dialog_content = "Nama saya adalah <color=#FFB400>Shira</color>.",
  ui_story_5028_50280801_148_dialog_content = "Shira",
  ui_story_5028_50280801_X148_dialog_content = "21 tahun",
  ui_story_5028_50280801_X149_dialog_content = "Gadis gurita misterius",
  ui_story_5028_50280801_149_dialog_content = "M-seniorku?! Tapi kenapa Guruku tidak pernah memberitahuku tentangmu?!",
  ui_story_5028_50280801_150_dialog_content = "Bagaimanapun, dia tidak pernah menjelaskan sesuatu dengan sangat jelas.",
  ui_story_5028_50280801_151_dialog_content = "Kadang-kadang, bahkan saya kesulitan mencari tahu apakah dia berbohong kepada saya lebih dari yang dia ajarkan kepada saya.",
  ui_story_5028_50280801_152_dialog_content = "Berurusan dengannya terkadang bisa sangat menyebalkan.",
  ui_story_5028_50280801_153_dialog_content = "Terima kasih untuk semua kerja kerasnya.",
  ui_story_5028_50280801_154_dialog_content = "Tapi tidak apa-apa... Aku sudah terbiasa sekarang.",
  ui_story_5028_50280801_155_dialog_content = "Baiklah, mari kita kembali ke topik yang sedang dibahas. Saya masih tidak yakin tentang arti dari foto ini.",
  ui_story_5028_50280801_156_dialog_content = "Vic mungkin pernah menyebutkan sesuatu tentang itu sebelumnya, tapi itu terlintas di benakku.",
  ui_story_5028_50280801_157_dialog_content = "Hei... Bukankah kamu seharusnya memiliki ingatan yang sangat bagus atau semacamnya?",
  ui_story_5028_50280801_158_dialog_content = "Bagaimana lagi Anda bisa mengingat begitu banyak pengetahuan rinci tentang begitu banyak binatang yang menakjubkan?",
  ui_story_5028_50280801_159_dialog_content = "Terlalu menyakitkan untuk mengingat sesuatu yang tidak relevan dengan binatang yang menakjubkan.",
  ui_story_5028_50280801_160_dialog_content = "Hai!",
  ui_story_5028_50280801_161_dialog_content = "Namun... Aku tahu persis apa arti simbol ini.",
  ui_story_5028_50280801_162_dialog_content = "Itu adalah pesan tersembunyi yang ditinggalkan oleh Vic. Itu artinya dia telah diculik.",
  ui_story_5028_50280801_163_dialog_content = "Ada banyak bandit di daerah itu, jadi dia biasanya meninggalkan simbol seperti ini agar aku bisa mencari dan menyelamatkannya.",
  ui_story_5028_50280801_164_dialog_content = "Jadi dia benar-benar telah diculik!",
  ui_story_5028_50280801_165_dialog_content = "Sial... Mereka seharusnya mengirimkan catatan tebusan sebentar lagi, kan?",
  ui_story_5028_50280801_166_dialog_content = "\"Jika Anda ingin melihat Tuan Anda lagi, bawa sepuluh juta Nightium ke lokasi berikut ...\" Saya tidak akan pernah mampu membelinya ...",
  ui_story_5028_50280801_167_dialog_content = "Yang lebih buruk, jika dia menendang ember... Aku tidak akan pernah bisa lulus sebagai ahli ekstrozoologi!",
  ui_story_5028_50280801_168_dialog_content = "Saya tidak berpikir aspirasi karir Anda adalah masalah terbesar kami saat ini!!!",
  ui_story_5028_50280801_169_dialog_content = "Tetap saja... Aku tidak bisa mengetahuinya.",
  ui_story_5028_50280801_170_dialog_content = "Vic sering dirampok, tapi dia dibohongi sebagai lelucon.",
  ui_story_5028_50280801_171_dialog_content = "Dan biasanya, para perampok itu hanya membuat keributan sebelum pergi tanpa membawa apa-apa. Paling buruk, mereka mungkin membuatnya kasar karena masalah mereka.",
  ui_story_5028_50280801_172_dialog_content = "Tapi kali ini, sepertinya seseorang mendobrak dan langsung menculiknya...",
  ui_story_5028_50280801_173_dialog_content = "Mengapa seseorang pergi ke semua masalah ini?",
  ui_story_5028_50280801_174_dialog_content = "Lagi pula, Vic tidak bisa memberikan apa pun yang berharga selain mengonsumsi makanan dan air.",
  ui_story_5028_50280801_175_dialog_content = "Pada titik ini, saya tidak tahu apakah harus merasa kasihan pada Tuanmu atau para penculiknya...",
  ui_story_5028_50280801_176_dialog_content = "Hmph... Saya sarankan Anda lebih khawatir tentang diri sendiri pada saat seperti ini.",
  ui_story_5028_50280801_177_dialog_content = "J-Jika Anda mengatakan begitu ...",
  ui_story_5028_50280801_178_dialog_content = "Adapun siapa yang bisa melakukannya, jangan bilang ...",
  ui_story_5028_50280801_179_dialog_content = "Oh tidak...",
  ui_story_5028_50280801_180_dialog_content = "Hei, tunggu!",
  ui_story_5028_50280801_181_dialog_content = "Menurutmu siapa yang menculik Tuanku?! Hai!!!",
  ui_story_5028_50280801_182_dialog_content = "Luar biasa... Dia baru saja menghilang dari pandangan kami dalam sekejap.",
  ui_story_5028_50280801_183_dialog_content = "Tuanku hilang, dan seniorku kabur tanpa sepatah kata pun.",
  ui_story_5028_50280801_184_dialog_content = "Ugh! Aku tidak mengerti mengapa mereka berdua harus seperti ini!!",
  ui_story_5028_50280801_185_dialog_content = "L-Mari kita coba mengejar Shira, oke?",
  ui_story_5028_50280801_186_dialog_content = "Sepertinya dia lari ke arah kota. Mari kita menuju ke sana dulu.",
  ui_story_5028_50280801_187_dialog_content = "Ada banyak orang di jalan. Seseorang pasti telah melihat ke arah mana dia pergi.",
  ui_story_5028_50280801_188_dialog_content = "Ya!",
  ui_story_5028_50280901_1_dialog_content = "Maaf, tapi apakah Anda kebetulan melihat seorang gadis berambut putih dengan tentakel lewat di sini?",
  ui_story_5028_50280901_4_dialog_content = "Nah, kalau bukan Fia kecil!",
  ui_story_5028_50280901_5_dialog_content = "Dan siapa ini? Seorang teman?",
  ui_story_5028_50280901_6_dialog_content = "Hah? Bukankah itu orang yang menjual koran?",
  ui_story_5028_50280901_7_dialog_content = "Ini di sini, adalah PlayerName, temanku.",
  ui_story_5028_50280901_8_dialog_content = "Kami sedang dalam pencarian sekarang. Apakah Anda memiliki petunjuk?",
  ui_story_5028_50280901_12_dialog_content = "Saya tidak tahu apa-apa tentang seorang wanita muda, tapi saya pikir tuanmu Vic membutuhkan bantuan!",
  ui_story_5028_50280901_13_dialog_content = "Y-Ya, sebagai ahli ekstrozoologi profesional, saya sangat menyadari kepergiannya... Kami sedang mencarinya sekarang.",
  ui_story_5028_50280901_14_dialog_content = "Aku tahu itu.",
  ui_story_5028_50280901_15_dialog_content = "Saya melihat dia dibawa pergi oleh seorang pria jangkung belum lama ini.",
  ui_story_5028_50280901_16_dialog_content = "Saya sudah memberi tahu orang-orang Shadowlord tentang kasus ini. Aku ingin tahu apakah mereka melakukan sesuatu tentang itu ...",
  ui_story_5028_50280901_17_dialog_content = "Seorang pria tinggi, ya? Apakah Anda ingat seperti apa tampangnya?",
  ui_story_5028_50280901_18_dialog_content = "Maaf, tapi dia membelakangiku. Yang bisa kulihat hanyalah dia membawa Tuanmu ke luar kota di punggungnya.",
  ui_story_5028_50280901_19_dialog_content = "Tapi aku ingat dengan jelas pakaiannya. Sama seperti yang dikenakan oleh bandit di dekatnya.",
  ui_story_5028_50280901_20_dialog_content = "Bandit?",
  ui_story_5028_50280901_21_dialog_content = "Kami juga sepenuhnya menyadari situasi ini. Anda dapat menyerahkan sisanya kepada saya sekarang.",
  ui_story_5028_50280901_22_dialog_content = "Jangan kasar, Fia.",
  ui_story_5028_50280901_23_dialog_content = "Jika yang terburuk menjadi yang terburuk, membayar Shadowlord untuk bantuannya selalu menjadi pilihan...",
  ui_story_5028_50280901_24_dialog_content = "Jangan khawatir, kami lebih dari mampu menangani ini sendiri.",
  ui_story_5028_50280901_25_dialog_content = "Baiklah kalau begitu. Semoga berhasil!",
  ui_story_5028_50280901_26_dialog_content = "Aduh... Saya ingin sekali meminta bantuan...",
  ui_story_5028_50280901_27_dialog_content = "Tapi Tuanku tidak punya cara untuk membayarnya...",
  ui_story_5028_50280901_28_dialog_content = "Bisakah kita benar-benar berharap untuk menghadapi para bandit itu hanya dengan kita berdua?",
  ui_story_5028_50280901_29_dialog_content = "Apa maksudmu, \"hanya kita berdua\"?",
  ui_story_5028_50280901_30_dialog_content = "Jangan lupa, saya seorang ahli ekstrozoologi profesional! Aku punya banyak sekali binatang buas yang bisa meminjamkan kita kekuatan mereka!",
  ui_story_5028_50280901_31_dialog_content = "Peko peko!",
  ui_story_5028_50280901_32_dialog_content = "gelap...",
  ui_story_5028_50280901_33_dialog_content = "Mm-hmm! Kalian juga ingin menyelamatkan Tuanku, kan?",
  ui_story_5028_50280901_34_dialog_content = "Dengan bantuan Anda, saya tahu kita bisa melakukannya!",
  ui_story_5028_50280901_35_dialog_content = "halo!",
  ui_story_5028_50280901_36_dialog_content = "Saya tidak mengerti apa yang Anda katakan untuk saat ini, tetapi Anda memegang kata-kata saya: Saya akan melakukan apa pun untuk menyelamatkan Tuan saya!",
  ui_story_5028_50280901_37_dialog_content = "Seorang bandit misterius yang terobsesi dengan pengetahuan menculik Vic terlepas dari betapa miskinnya dia ...",
  ui_story_5028_50280901_38_dialog_content = "Aku ingin tahu bagaimana kita akan melacak mereka?",
  ui_story_5028_50280901_39_dialog_content = "Apakah kita benar-benar harus bergantung pada Shadowlord untuk bantuan?",
  ui_story_5028_50280901_40_dialog_content = "Pasti ada cara yang lebih baik...",
  ui_story_5028_50280901_41_dialog_content = "Biarkan aku berpikir...",
  ui_story_5028_50280901_42_dialog_content = "Selain target mereka, saya kira para bandit harus mengawasi geng lain.",
  ui_story_5028_50280901_43_dialog_content = "Lagi pula, mereka hanya peduli dengan wilayah mereka, bukan hukum.",
  ui_story_5028_50280901_44_dialog_content = "Jika kita berhasil mendapatkan bandit, kita mungkin bisa mendapatkan beberapa informasi tentang keberadaan Guruku!",
  ui_story_5028_50280901_45_dialog_content = "Kedengaranya seperti sebuah rencana! Hanya... Dimana kita harus menemukan bandit?",
  ui_story_5028_50280901_46_dialog_content = "Di mana menemukan bandit, katamu?",
  ui_story_5028_50280901_47_dialog_content = "Itu mudah!",
  ui_story_5028_50280901_48_dialog_content = "Anda dan saya hanya perlu berpura-pura bahwa kita adalah sepasang pengembara yang kaya dan mudah tertipu, PlayerName!",
  ui_story_5028_50280901_49_dialog_content = "Mari kita mulai dengan...",
  ui_story_5028_50280901_50_dialog_content = "Tunggu... K-Maksudmu tidak mungkin...?",
  ui_story_5028_50280901_51_dialog_content = "Tidak! Tidak mungkin! Tidak ada kesempatan!",
  ui_story_5028_50280901_52_dialog_content = "Apa kau tahu seberapa keras aku bekerja untuk mengumpulkan Nightium sebanyak ini sejak aku meninggalkan dunia bawah tanah?!",
  ui_story_5028_50280901_53_dialog_content = "T-Tapi PlayerName... Tidakkah kamu ingin membantuku menyelamatkan Tuanku?",
  ui_story_5028_50280901_54_dialog_content = "...",
  ui_story_5028_50280901_55_dialog_content = "Apakah Anda tahan melihat saya tidak pernah menjadi ahli ekstrozoologi?",
  ui_story_5028_50280901_56_dialog_content = "...",
  ui_story_5028_50280901_57_dialog_content = "Boo-hoo... Tidak apa-apa... Aku hanya harus mencari cara lain...",
  ui_story_5028_50280901_58_dialog_content = "Aku akan menyelamatkan Tuanku, sendirian! Bahkan jika aku ditangkap dan disiksa oleh para bandit itu, aku tetap tidak akan meminta bantuanmu lagi, PlayerName!",
  ui_story_5028_50280901_X58_dialog_content = "Huu huu!!!",
  ui_story_5028_50280901_X59_dialog_content = "...",
  ui_story_5028_50280901_X60_dialog_content = "Kenapayyyyy!!!",
  ui_story_5028_50280901_59_dialog_content = "<color=#e8d9bb>Suatu saat nanti...</color>",
  ui_story_5028_50280901_60_dialog_content = "Permen apel! Taiyaki! Spesialisasi Pulau Awan!",
  ui_story_5028_50280901_61_dialog_content = "Kau disana! Merasa sedikit lapar?",
  ui_story_5028_50280901_62_dialog_content = "Bagaimana Anda tahu? Kami akan mengambil sepuluh dari semuanya! Perlakuannya!",
  ui_story_5028_50280901_63_dialog_content = "Y-Ya! Perlakuanku...!",
  ui_story_5028_50280901_64_dialog_content = "Aku tahu kalian keren guys! Tunggu sebentar!",
  ui_story_5028_50280901_65_dialog_content = "Wow... Lihat semua jajanan enak ini!",
  ui_story_5028_50280901_66_dialog_content = "(Mengapa saya pernah setuju untuk menjadi bagian dari rencana bodoh ini?!)",
  ui_story_5028_50280901_67_dialog_content = "(Vice tidak akan membiarkan ini pergi begitu dia tahu aku menghabiskan banyak uang ...)",
  ui_story_5028_50280901_68_dialog_content = "Om-nom-nom... Enak!",
  ui_story_5028_50280901_69_dialog_content = "Saya akan memiliki yang lain!",
  ui_story_5028_50280901_70_dialog_content = "Segera, Bu!",
  ui_story_5028_50280901_71_dialog_content = "(Tolong... Itu bayaran sepuluh hari barusan...)",
  ui_story_5028_50280901_72_dialog_content = "...",
  ui_story_5028_50280901_73_dialog_content = "(Tunggu... Apakah orang itu di sana menatap kita?)",
  ui_story_5028_50280901_74_dialog_content = "Kami sedang diawasi. Saya pikir kami akhirnya menarik perhatian bandit.",
  ui_story_5028_50280901_75_dialog_content = "Waktu yang tepat. Aku juga baru selesai ngemil! Saatnya untuk langkah selanjutnya.",
  ui_story_5028_50280901_76_dialog_content = "*Batuk*",
  ui_story_5028_50280901_77_dialog_content = "Ah, itu benar-benar suguhan yang luar biasa! Bagaimana kalau kita berbelanja sekarang?",
  ui_story_5028_50280901_78_dialog_content = "Secara alami, Anda akan membelikan saya apa pun yang diinginkan hati kecil saya, bukan?",
  ui_story_5028_50280901_79_dialog_content = "A-Apakah ini benar-benar langkah selanjutnya?!",
  ui_story_5028_50280901_80_dialog_content = "<size=45>A-HEM!!!</size>",
  ui_story_5028_50280901_81_dialog_content = "Aduh! Baiklah, baiklah, berhenti menendangku!",
  ui_story_5028_50280901_82_dialog_content = "aku... aku mengerti! Saya berjanji...",
  ui_story_5028_50280901_83_dialog_content = "Aku akan membelikanmu apapun yang kamu suka!",
  ui_story_5028_50280901_84_dialog_content = "Sekarang itulah yang saya suka dengar!",
  ui_story_5028_50280901_85_dialog_content = "(Saya tidak akan pernah bisa berbicara keluar dari ini!)",
  ui_story_5028_50280901_86_dialog_content = "(Maafkan aku, Vice. Aku kehabisan uang... Lagi...)",
  ui_story_5028_50280901_87_dialog_content = "(Maafkan saya, Soroz. Biaya perawatan bulan depan Anda hilang ... Sekali lagi ...)",
  ui_story_5028_50280901_88_dialog_content = "...",
  ui_story_5028_50280901_89_dialog_content = "Lihat ke sana. Bukankah itu terlihat seperti PlayerName?",
  ui_story_5028_50280901_90_dialog_content = "Itu tidak hanya terlihat seperti dia... Ini dia!",
  ui_story_5028_50280901_91_dialog_content = "Sayangnya, dia terlalu jauh bagi cambukku untuk menjangkaunya. Sayang sekali...",
  ui_story_5028_50280901_93_dialog_content = "Navigator—!",
  ui_story_5028_50280901_94_dialog_content = "Tunggu kami-!",
  ui_story_5028_50280901_95_dialog_content = "Dia mungkin tidak bisa mendengar kita dari jarak ini. Lagipula jalan ini cukup ramai.",
  ui_story_5028_50280901_96_dialog_content = "Kemudian berhenti mengoceh. Kejar saja dia.",
  ui_story_5028_50280901_97_dialog_content = "<color=#e8d9bb>Di luar Kota</color>",
  ui_story_5028_50280901_98_dialog_content = "(Fia sebenarnya membawaku ke pinggiran kota, di mana ada lebih sedikit orang di sekitar...)",
  ui_story_5028_50280901_99_dialog_content = "Ya, tempat ini seharusnya baik-baik saja!",
  ui_story_5028_50280901_100_dialog_content = "Aku benar-benar kelelahan, PlayerName. Mari kita berhenti di sini dan beristirahat sejenak!",
  ui_story_5028_50280901_101_dialog_content = "Eh, o-oke...",
  ui_story_5028_50280901_102_dialog_content = "Tapi bukankah ini akan menempatkan kita dalam bahaya yang lebih besar lagi?",
  ui_story_5028_50280901_103_dialog_content = "Selama aku di sini, apa yang harus kamu khawatirkan?",
  ui_story_5028_50280901_104_dialog_content = "Kalian berdua sepertinya bersenang-senang, ya?",
  ui_story_5028_50280901_105_dialog_content = "Itu orang yang mengikuti kita selama ini!",
  ui_story_5028_50280901_106_dialog_content = "Heh, jika Anda sudah mengetahuinya, maka saya tidak akan membuang waktu lagi untuk berbasa-basi ...",
  ui_story_5028_50280901_107_dialog_content = "Mengapa kalian berdua anak-anak kaya tidak datang untuk berjalan-jalan dengan saya?",
  ui_story_5028_50280901_108_dialog_content = "Sepertinya kita tidak punya pilihan, PlayerName... Mari kita pergi dengan dia untuk saat ini.",
  ui_story_5028_50280901_109_dialog_content = "Apa?!",
  ui_story_5028_50280901_110_dialog_content = "Lihat, sobat? Gadis kecil ini mengerti. Sekarang letakkan tanganmu di belakang agar kami bisa mengikatmu dengan baik...",
  ui_story_5028_50280901_111_dialog_content = "(Apa yang sedang terjadi? Aku perlu tahu sebelum terlambat!)",
  ui_story_5028_50280901_112_option_content = "(Peningkatan Kekuatan!)",
  ui_story_5028_50280901_113_dialog_content = "(Fia, bisakah kamu mendengarku? Apa yang sebenarnya terjadi sekarang?!)",
  ui_story_5028_50280901_114_dialog_content = "(Wow! T-Jangan ini lagi!!)",
  ui_story_5028_50280901_115_dialog_content = "(Tenang. Saya hanya ingin tumpangan ke tempat persembunyian mereka.)",
  ui_story_5028_50280901_116_dialog_content = "(Ini akan menghemat banyak waktu dan energi.)",
  ui_story_5028_50280901_117_dialog_content = "(Apakah kamu bercanda?!)",
  ui_story_5028_50280901_118_dialog_content = "(Duduk saja dan nikmati pertunjukannya, percayalah! Saat ini, kita harus sedikit bersabar...)",
  ui_story_5028_50280901_119_dialog_content = "Bagaimanapun, hari ini adalah hari keberuntungan kita, kawan! Meskipun beberapa orang brengsek lainnya mengalahkan kami sampai titik pertama kami...",
  ui_story_5028_50280901_120_dialog_content = "Hadiah hiburan kami tidak terlihat buruk sama sekali! Ha ha ha!",
  ui_story_5028_50280901_121_dialog_content = "Selesai mengikat mereka? Bagus, sekarang mari kita pergi...",
  ui_story_5028_50280901_122_dialog_content = "Ugh!",
  ui_story_5028_50280901_123_dialog_content = "Mencari orang itu sangat menyakitkan...",
  ui_story_5028_50280901_124_dialog_content = "Saya tidak akan pernah ingin terjebak dalam memburu bandit mana pun selama waktu istirahat saya ... Tidak sampai saya harus melakukannya.",
  ui_story_5028_50280901_125_dialog_content = "Shira!? Apa yang kamu lakukan di sini?",
  ui_story_5028_50280901_126_dialog_content = "Apa yang saya lakukan disini? Hah, apa yang KAMU lakukan disini?",
  ui_story_5028_50280901_127_dialog_content = "Saya pikir saya mengatakan kepada Anda untuk berhenti membuat lebih banyak masalah bagi saya.",
  ui_story_5028_50280901_128_dialog_content = "Tapi kau masih merasa pantas untuk mengejarku... dan sekarang kau bermain-main dengan bandit-bandit ini!",
  ui_story_5028_50280901_129_option_content = "Kami sedang diculik!",
  ui_story_5028_50280901_130_option_content = "Jelas bukan \"melawak\"!",
  ui_story_5028_50280901_131_dialog_content = "Ini adalah bagian dari rencana kami, tetapi sekarang Anda telah merusaknya!",
  ui_story_5028_50280901_133_dialog_content = "Rencana? Sekrup itu. Aku akan tetap melanjutkan urusanku sendiri.",
  ui_story_5028_50280901_134_dialog_content = "Aku hanya berharap kalian berdua berhenti menghalangi jalanku.",
  ui_story_5028_50280901_136_dialog_content = "Ugh, ugh... Sial... Bagaimana gadis ini bisa sekuat itu?!",
  ui_story_5028_50280901_137_dialog_content = "Ayo, anak-anak! Mari beri dia pelajaran yang tidak akan segera dia lupakan!",
  ui_story_5028_50280901_138_dialog_content = "Saya juga tidak ingin Anda idiot dengan cara saya.",
  ui_story_5028_50280901_139_dialog_content = "Yang ingin saya dengar hanyalah jawaban yang baik dan jujur, mengerti?",
  ui_story_5028_50280901_140_dialog_content = "Urgh...!",
  ui_story_5028_50280901_141_dialog_content = "Sekarang katakan padaku... Dimana sih Vic?",
  ui_story_5028_50280901_142_dialog_content = "Buatlah singkat dan manis, man. Mencekik hidupmu seperti ini cukup melelahkan, kau tahu?",
  ui_story_5028_50280901_143_dialog_content = "Urgh... I-Itu tadi <color=#FFB400>Gary</color>... Itu dia dan geng pemburunya... Cambuk Besi!",
  ui_story_5028_50280901_144_dialog_content = "Jadi itu dia selama ini.",
  ui_story_5028_50280901_145_dialog_content = "Gary? Kenapa nama itu terdengar begitu familiar...?",
  ui_story_5028_50280901_146_dialog_content = "Tidak ada waktu. Kita harus segera menangkap Kelinci Peko itu untuk Gary.",
  ui_story_5028_50280901_147_dialog_content = "Aku ingat sekarang! Kami mendengar dua bandit itu menyebut seseorang bernama Gary saat kami sedang mencari Kelinci Peko!",
  ui_story_5028_50280901_148_dialog_content = "Oh? Betulkah? Saya tidak ingat apa-apa tentang itu sama sekali ...",
  ui_story_5028_50280901_149_dialog_content = "Gary... Jadi dia pelakunya di balik menurunnya jumlah hewan ajaib.",
  ui_story_5028_50280901_150_dialog_content = "Anda tahu orang ini?",
  ui_story_5028_50280901_151_dialog_content = "Tidak ada cara mudah untuk mengatakan ini. Selain itu, itu tidak ada hubungannya denganmu.",
  ui_story_5028_50280901_152_dialog_content = "Di mana Gary bersembunyi?",
  ui_story_5028_50280901_153_dialog_content = "I-Ada gua gunung sekitar enam mil ke utara! Itu tempat persembunyiannya...",
  ui_story_5028_50280901_154_dialog_content = "Aduh!",
  ui_story_5028_50280901_155_dialog_content = "Betapa sakitnya...",
  ui_story_5028_50280901_156_dialog_content = "Hai! Jangan kabur seperti itu lagi!",
  ui_story_5028_50280901_157_dialog_content = "Ayo, PlayerName! Setelah dia!",
  ui_story_5028_50280901_158_dialog_content = "Kita tidak bisa kehilangan dia kali ini!",
  ui_story_5028_50280901_159_dialog_content = "Benar, oke!",
  ui_story_5028_50280901_160_dialog_content = "<color=#e8d9bb>Beberapa menit kemudian...</color>",
  ui_story_5028_50280901_161_dialog_content = "Semua orang ini telah tersingkir.",
  ui_story_5028_50280901_162_dialog_content = "Hah? Bertanya-tanya mengapa orang-orang ini hanya berbaring di sekitar sini?",
  ui_story_5028_50280901_163_dialog_content = "Apakah Anda mengenali mereka, Smokey?",
  ui_story_5028_50280901_164_dialog_content = "Mereka hanyalah beberapa bandit keliling yang muncul di dekat Umbraton baru-baru ini. Mereka semua bisa terbakar sampai garing, untuk semua yang saya pedulikan.",
  ui_story_5028_50280901_165_dialog_content = "Um... Tanda-tanda pertempuran ini masih sangat segar.",
  ui_story_5028_50280901_166_dialog_content = "Jika kita cepat, kita mungkin bisa mengikuti PlayerName.",
  ui_story_5028_50280901_168_dialog_content = "Mari kita mempercepat.",
  ui_story_5028_50280901_169_dialog_content = "Apa yang bisa? PlayerName sampai?",
  ui_story_5028_50280901_170_dialog_content = "<color=#e8d9bb>Di luar Benteng Bandit</color>",
  ui_story_5028_50280901_171_dialog_content = "Ini harus menjadi tempat.",
  ui_story_5028_50280901_172_dialog_content = "Wah... Kamu sangat cepat, tahu?",
  ui_story_5028_50280901_173_dialog_content = "Bukaan di sana itu pasti pintu masuk ke tempat persembunyian mereka, kan?",
  ui_story_5028_50280901_174_dialog_content = "T-Tunggu kami!",
  ui_story_5028_50280901_175_dialog_content = "Lihat! halo!",
  ui_story_5028_50280901_176_dialog_content = "Mengapa Anda menunjuk ke dalam? <color=#FFB400>arah itu</color>, Shira?",
  ui_story_5028_50280901_177_dialog_content = "Ada sekelompok binatang yang menakjubkan?!",
  ui_story_5028_50280901_178_dialog_content = "Di mana? Biarku lihat!",
  ui_story_5028_50280901_179_dialog_content = "Dan bukan hanya binatang yang menakjubkan... Ada banyak Eclipsites juga!",
  ui_story_5028_50280901_180_dialog_content = "Graaah—!!",
  ui_story_5028_50280901_181_dialog_content = "Oh tidak, kami ketahuan!",
  ui_story_5028_50280901_182_dialog_content = "Pergi, Kyu!",
  ui_story_5028_50280901_183_dialog_content = "Ugh... Bukan pertarungan lagi...",
  ui_story_5028_50280902_1_dialog_content = "Kyllo!",
  ui_story_5028_50280902_2_dialog_content = "Lo lo lo... Lo!",
  ui_story_5028_50280902_3_dialog_content = "Astaga!",
  ui_story_5028_50280902_4_dialog_content = "Berhati-hatilah untuk tidak menyakiti binatang buas yang menakjubkan itu!",
  ui_story_5028_50280902_5_dialog_content = "Mereka adalah pengamat yang tidak bersalah dalam semua ini!",
  ui_story_5028_50280902_6_dialog_content = "peko!",
  ui_story_5028_50280902_7_dialog_content = "Jangan takut, aku tidak akan menyakitimu. Ikut denganku.",
  ui_story_5028_50280902_8_dialog_content = "Peko peko!!!",
  ui_story_5028_50280902_9_dialog_content = "Hai! Kenapa kau menakutinya seperti itu?!",
  ui_story_5028_50280902_10_dialog_content = "Aku tidak mencoba! aku hanya...",
  ui_story_5028_50280902_11_dialog_content = "Graaah—!!",
  ui_story_5028_50280902_12_dialog_content = "Argh! Apa yang menyakitkan!",
  ui_story_5028_50280902_13_dialog_content = "(Shira terlihat sedikit frustrasi...?)",
  ui_story_5028_50280902_14_dialog_content = "(Dan sepertinya monster ajaib tidak mau mendekatinya. Begitu juga dengan hewan yang bersahabat dengan Fia...)",
  ui_story_5028_50280902_15_dialog_content = "Nah, Eclipsites semua diurus. Binatang buas yang menakjubkan itu juga ditakuti oleh Shira.",
  ui_story_5028_50280902_16_dialog_content = "Hmph, tidak satupun dari mereka yang pernah melawan Fia, seorang extrozoologist sejati!",
  ui_story_5028_50280902_17_dialog_content = "Tapi tidakkah menurutmu itu aneh? Mengapa Gary bisa menyatukan Eclipsites dan monster yang menakjubkan?",
  ui_story_5028_50280902_18_dialog_content = "Dan seolah-olah mereka melindungi gua.",
  ui_story_5028_50280902_X18_dialog_content = "Mereka dilatih untuk menjadi seperti ini.",
  ui_story_5028_50280902_19_dialog_content = "Tunggu... Bisakah Eclipsites dilatih seperti binatang buas lainnya?!",
  ui_story_5028_50280902_20_dialog_content = "Saya tidak yakin, tetapi ada desas-desus bahwa Gary mendapatkannya <color=#FFB400>cambuk yang bisa memaksa binatang untuk mematuhi perintahnya</color>.",
  ui_story_5028_50280902_21_dialog_content = "Mungkin cambuk itu juga bisa digunakan untuk mengendalikan Eclipsites.",
  ui_story_5028_50280902_22_dialog_content = "Lagi pula, menggunakan kekerasan untuk memaksa orang lain agar tunduk adalah kebiasaan para bandit.",
  ui_story_5028_50280902_23_dialog_content = "Lalu apakah binatang-binatang ajaib itu juga dipaksa untuk bertarung demi mereka?",
  ui_story_5028_50280902_24_dialog_content = "Menurut saya, kemungkinan besar mereka mengikuti jenis \"pelatihan\" yang sama.",
  ui_story_5028_50280902_25_dialog_content = "Bandit bukanlah sarjana; mereka menggunakan metode yang paling brutal untuk melaksanakan rencana mereka terlepas dari perasaan binatang itu.",
  ui_story_5028_50280902_26_dialog_content = "Tapi bagaimana mereka bisa begitu tidak berperasaan?",
  ui_story_5028_50280902_27_dialog_content = "Kamu juga.",
  ui_story_5028_50280902_28_dialog_content = "Saya melihat Anda tidak tahu apa-apa tentang binatang yang menakjubkan. Anda cukup mengikuti buku dan kata-kata Vic untuk menanganinya.",
  ui_story_5028_50280902_29_dialog_content = "Menyebut diri Anda seorang ekstrozoologis meskipun tidak memiliki pengendalian diri dan melakukan apa pun yang Anda suka.",
  ui_story_5028_50280902_30_dialog_content = "Dalam hal ini, Anda tidak berbeda dengan Vic.",
  ui_story_5028_50280902_31_dialog_content = "Aku tidak seperti dia!",
  ui_story_5028_50280902_32_dialog_content = "Jika Anda bersikeras untuk menyangkalnya, maka izinkan saya mengajukan beberapa pertanyaan.",
  ui_story_5028_50280902_33_dialog_content = "Berapa suhu yang harus Anda pertahankan untuk telur Lutumi Owl di fase kedua inkubasinya?",
  ui_story_5028_50280902_34_dialog_content = "Aku tahu yang ini! 30! Atau mungkin... 40?",
  ui_story_5028_50280902_35_dialog_content = "Suhunya 42,5 derajat, dan setiap telur harus dibalik setiap enam jam.",
  ui_story_5028_50280902_36_dialog_content = "Mereka harus dibalik?!",
  ui_story_5028_50280902_37_dialog_content = "Tentu saja. Jika tidak, inkubasi akan gagal sepenuhnya.",
  ui_story_5028_50280902_38_dialog_content = "Aku tahu itu!",
  ui_story_5028_50280902_39_dialog_content = "Saya hanya perlu membaca buku catatan itu sekali lagi!",
  ui_story_5028_50280902_40_dialog_content = "Melihat? Anda bahkan mengandalkan lembar contekan untuk mengetahui cara merawat binatang ajaib yang Anda klaim sangat penting bagi Anda...",
  ui_story_5028_50280902_41_dialog_content = "Itulah jenis orang yang ceroboh dan tidak profesional Anda.",
  ui_story_5028_50280902_42_dialog_content = "aku, aku...",
  ui_story_5028_50280902_43_dialog_content = "Huu huu!!!",
  ui_story_5028_50280902_44_dialog_content = "F-Fia?!",
  ui_story_5028_50280902_45_dialog_content = "Itu sebabnya saya selalu mengatakan... Anak kecil adalah penderitaan terbesar yang pernah ada.",
  ui_story_5028_50280902_46_dialog_content = "Aku bukan anak kecil! aku tidak!",
  ui_story_5028_50280902_47_dialog_content = "Hanya anak kecil yang akan menyangkal menjadi seperti itu.",
  ui_story_5028_50280902_48_dialog_content = "Saya menyarankan Anda untuk mundur selagi masih bisa, dan lepaskan teman-teman kecil Anda kembali ke tempat asalnya.",
  ui_story_5028_50280902_49_dialog_content = "Cukup! Tidak bisakah kamu melihat betapa buruknya perasaanmu padanya?",
  ui_story_5028_50280902_50_dialog_content = "Ugh!",
  ui_story_5028_50280902_51_dialog_content = "Anda adalah bagian dari alasan dia seperti ini juga.",
  ui_story_5028_50280902_52_dialog_content = "Hah?",
  ui_story_5028_50280902_53_dialog_content = "Jika Anda tidak mendisiplinkan anak manja seperti dia, dia tidak akan pernah belajar menjadi dewasa.",
  ui_story_5028_50280902_54_dialog_content = "Jika kalian terus bersikap sembrono seperti selama ini, maka cepat atau lambat... Anda akan menemukan diri Anda dalam dunia yang menyakitkan.",
  ui_story_5028_50280902_55_dialog_content = "Sama seperti yang saya lakukan.",
  ui_story_5028_50280902_56_dialog_content = "Wah! Tetap, tetap di tempatmu!",
  ui_story_5028_50280902_57_dialog_content = "Orang ini pasti suka lepas landas tanpa sepatah kata pun, bukan?",
  ui_story_5028_50280902_58_dialog_content = "Dia langsung berlari lebih dalam ke dalam gua.",
  ui_story_5028_50280902_59_dialog_content = "Dia terus berbicara pada dirinya sendiri... dan... dan dia bahkan menuduhku...",
  ui_story_5028_50280902_60_dialog_content = "Apakah kamu baik-baik saja, Fia?",
  ui_story_5028_50280902_61_dialog_content = "halo!",
  ui_story_5028_50280902_62_dialog_content = "Aku... Aku tidak akan pernah menyerah semudah itu! Tidak pernah!!!",
  ui_story_5028_50280902_63_dialog_content = "Apa?!",
  ui_story_5028_50280902_64_dialog_content = "Saya sangat bertekad untuk menjadi seorang extrozoologist. Ejekan ini tidak akan pernah bisa menahan saya!",
  ui_story_5028_50280902_65_dialog_content = "Mari kita mengejarnya!",
  ui_story_5028_50280902_66_dialog_content = "Semua penjaga di pintu masuk telah tersingkir. Ini adalah kesempatan kita untuk menyelinap masuk dan menyelamatkan Tuanku!",
  ui_story_5028_50280902_67_dialog_content = "Dia bilang namanya Shira, kan?",
  ui_story_5028_50280902_68_dialog_content = "Saya pasti akan menunjukkan kepadanya betapa mampunya saya!",
  ui_story_5028_50281001_1_dialog_content = "Apakah ini markas tersembunyi Gary? Rasanya tidak enak.",
  ui_story_5028_50281001_2_dialog_content = "Ada kandang yang kotor dan kosong tergeletak di mana-mana. Baunya benar-benar tidak enak.",
  ui_story_5028_50281001_3_dialog_content = "Saya khawatir banyak binatang ajaib yang disimpan di sini sampai baru-baru ini.",
  ui_story_5028_50281001_4_dialog_content = "Semua kandang dibiarkan terbuka lebar, tetapi tidak ada binatang buas yang terlihat...",
  ui_story_5028_50281001_5_dialog_content = "Apakah Shira membebaskan mereka dalam perjalanan?",
  ui_story_5028_50281001_6_dialog_content = "Tunggu...",
  ui_story_5028_50281001_7_dialog_content = "Hati-hati, Fia. Saya merasakan banyak binatang yang menakjubkan datang dengan cara ini.",
  ui_story_5028_50281001_8_dialog_content = "Pindah atau kamu akan hancur!",
  ui_story_5028_50281001_9_dialog_content = "Hah?",
  ui_story_5028_50281001_10_dialog_content = "Apa?!",
  ui_story_5028_50281001_11_dialog_content = "Tunggu, apa yang terjadi di sini?",
  ui_story_5028_50281001_12_dialog_content = "Seseorang lebih baik katakan padaku sekarang!",
  ui_story_5028_50281001_13_dialog_content = "Hei kau! Katakan padaku, apa yang sebenarnya terjadi di sini?",
  ui_story_5028_50281001_14_dialog_content = "Hallo!",
  ui_story_5028_50281001_15_dialog_content = "A-Apa?!",
  ui_story_5028_50281001_16_dialog_content = "Anda mengatakan bahwa ada orang asing yang menakutkan dan pembunuh yang menunggu di depan?",
  ui_story_5028_50281001_17_dialog_content = "Dan bahwa orang asing ini adalah orang yang membebaskanmu sebelum berlari lebih dalam ke dalam gua?",
  ui_story_5028_50281001_18_dialog_content = "Orang asing yang menakutkan dan pembunuh...",
  ui_story_5028_50281001_19_option_content = "Mungkinkah itu berbicara tentang pemimpin bandit?",
  ui_story_5028_50281001_20_dialog_content = "Jangan terlalu naif, PlayerName.",
  ui_story_5028_50281001_21_dialog_content = "Pemimpin geng bandit ini tidak akan pernah membiarkan satu pun binatang buas yang menakjubkan lolos dari pengawasannya.",
  ui_story_5028_50281001_22_dialog_content = "Y-Ya, Anda benar.",
  ui_story_5028_50281001_23_dialog_content = "Orang yang dibicarakan... kemungkinan besar adalah Shira.",
  ui_story_5028_50281001_24_dialog_content = "Kemudian \"pria menakutkan\" telah meneror begitu banyak binatang akhir-akhir ini... Anda tidak berpikir...",
  ui_story_5028_50281001_25_option_content = "Mungkinkah Shira juga?",
  ui_story_5028_50281001_26_dialog_content = "Jadi begitulah cara binatang yang menakjubkan melihatnya, ya? Mengerikan dan membunuh...",
  ui_story_5028_50281001_27_dialog_content = "Tidak bisa mengatakan itu tidak sejalan dengan sikap busuknya atau wajahnya itu.",
  ui_story_5028_50281001_28_dialog_content = "Saya akan takut konyol jika saya adalah binatang, juga!",
  ui_story_5028_50281001_29_dialog_content = "Tapi sekarang bukan waktunya untuk mengkhawatirkan binatang buas ini. Mereka tampaknya tidak terluka dan bisa lari dari sini sendiri.",
  ui_story_5028_50281001_30_dialog_content = "Kita harus terus mencari Master Vic.",
  ui_story_5028_50281001_31_dialog_content = "Tentu.",
  ui_story_5028_50281001_32_dialog_content = "Di sini gelap gulita. Aku tidak bisa melihat apa-apa...",
  ui_story_5028_50281001_33_dialog_content = "Apakah selama ini mereka menyimpan binatang-binatang malang itu dalam kegelapan seperti ini?",
  ui_story_5028_50281001_34_dialog_content = "Sungguh menyesakkan...",
  ui_story_5028_50281001_35_dialog_content = "Hmph! Apa yang kamu, takut gelap? Aku tidak pernah tahu Caelestite terakhir adalah kucing yang menakutkan!",
  ui_story_5028_50281001_36_dialog_content = "Eh... Fi? L-Lihat di belakangmu...",
  ui_story_5028_50281001_37_dialog_content = "Mengapa, sehingga Anda bisa menakut-nakuti saya? Maaf sobat, itu sangat klise.",
  ui_story_5028_50281001_38_dialog_content = "Kalian berdua... masih mengikutiku di sini.",
  ui_story_5028_50281001_39_dialog_content = "Wah!!!",
  ui_story_5028_50281001_40_dialog_content = "A-Apa yang kamu pikir kamu lakukan, menyelinap di belakangku seperti itu?!",
  ui_story_5028_50281001_41_dialog_content = "L-Mari kita perjelas satu hal! K-Kamu tidak membuatku takut sama sekali barusan!",
  ui_story_5028_50281001_42_dialog_content = "...",
  ui_story_5028_50281001_43_dialog_content = "Shira? Vic tidak bersamamu?",
  ui_story_5028_50281001_44_dialog_content = "Vic? Tidak, dia masih terikat di bagian gua yang lebih dalam.",
  ui_story_5028_50281001_45_dialog_content = "Lalu kenapa kamu tidak menyelamatkannya?",
  ui_story_5028_50281001_46_dialog_content = "Melepaskannya akan terlalu menyakitkan. Membawanya keluar akan menjadi rasa sakit yang lebih besar.",
  ui_story_5028_50281001_47_dialog_content = "Hai! Tidakkah kamu pikir kamu menggunakan alasan itu terlalu banyak?!",
  ui_story_5028_50281001_48_dialog_content = "Juga, bahkan jika aku membebaskannya, tidak ada yang tahu apakah dia akan membuat dirinya sendiri ke dalam masalah yang lebih dalam atau tidak.",
  ui_story_5028_50281001_49_dialog_content = "Saya tidak tahu bagaimana dia berharap untuk melindungi binatang buas yang menakjubkan dengan pikiran yang tersebar itu.",
  ui_story_5028_50281001_50_dialog_content = "Ini adalah sesuatu yang sebaiknya diserahkan kepada seseorang yang lebih profesional.",
  ui_story_5028_50281001_51_dialog_content = "Yah, setidaknya kita bisa menyepakati sesuatu: Guru kita benar-benar tidak bisa diandalkan.",
  ui_story_5028_50281001_52_dialog_content = "Tapi sebagai seorang extrozoologist, saya akan melakukan segalanya dengan kekuatan saya untuk melindungi binatang-binatang menakjubkan dunia menggantikannya!",
  ui_story_5028_50281001_53_dialog_content = "Hmph. Apa pun.",
  ui_story_5028_50281001_54_dialog_content = "Vic ada di sana. Jika Anda ingin menyelamatkannya, silakan.",
  ui_story_5028_50281001_55_dialog_content = "Cobalah untuk tidak menghalangi jalanku.",
  ui_story_5028_50281001_56_dialog_content = "Grr... Dia meremehkanku lagi!",
  ui_story_5028_50281001_57_dialog_content = "Sial... Aku bersumpah, suatu hari nanti, aku akan menjatuhkan kaus kakinya dengan keahlianku!",
  ui_story_5028_50281001_58_dialog_content = "Lihat!!!",
  ui_story_5028_50281001_59_dialog_content = "Kamu juga berpikir begitu, kan, Kyllo?",
  ui_story_5028_50281001_60_dialog_content = "Ayo pergi dan bawa Guruku keluar dari sini!",
  ui_story_5028_50281001_61_dialog_content = "<color=#e8d9bb>Jauh di dalam Benteng Gary</color>",
  ui_story_5028_50281001_62_dialog_content = "Tuan Vic!",
  ui_story_5028_50281001_63_dialog_content = "Anda membuat diri Anda benar-benar kacau kali ini, Guru...",
  ui_story_5028_50281001_64_dialog_content = "Dalam hal ini, saya akan dengan baik hati melepaskan ikatan Anda.",
  ui_story_5028_50281001_65_dialog_content = "Wah! Saya tahu Anda akan datang untuk menyelamatkan saya cepat atau lambat!",
  ui_story_5028_50281001_66_dialog_content = "Dan tidak terlambat satu menit pun! Tanganku mati rasa karena pengekangan ini...",
  ui_story_5028_50281001_67_dialog_content = "Dan siapa ini?",
  ui_story_5028_50281001_68_dialog_content = "Halo, Vik. Nama saya adalah PlayerName, dan saya-",
  ui_story_5028_50281001_69_option_content = "Akulah Caelestit yang ditangkap Fia.",
  ui_story_5028_50281001_70_dialog_content = "Ya!",
  ui_story_5028_50281001_71_dialog_content = "Ini adalah Caelestite, salah satu binatang ajaib paling langka yang pernah saya tangkap!",
  ui_story_5028_50281001_72_dialog_content = "Hanya ada satu yang tersisa di seluruh keberadaan!",
  ui_story_5028_50281001_73_option_content = "Saya teman Fia.",
  ui_story_5028_50281001_74_dialog_content = "Betul sekali! Dia salah satu dari teman binatang saya yang menakjubkan!",
  ui_story_5028_50281001_75_dialog_content = "Satu-satunya Caelestit di seluruh dunia!",
  ui_story_5028_50281001_76_dialog_content = "Oh? Dan Anda berhasil menangkapnya?",
  ui_story_5028_50281001_77_dialog_content = "Anda bertaruh!",
  ui_story_5028_50281001_78_dialog_content = "Dan tidak hanya itu—saya menyelesaikan semua tugas yang Anda berikan kepada saya.",
  ui_story_5028_50281001_79_dialog_content = "Paling mengesankan...",
  ui_story_5028_50281001_80_dialog_content = "Tentu saja saya tidak akan menjadi seorang ekstrozoologis jika saya tidak dapat menangani beberapa hal kecil seperti itu.",
  ui_story_5028_50281001_81_dialog_content = "Anda menemukan Caelestite berarti fase berikutnya dari rencana saya adalah mencari.",
  ui_story_5028_50281001_82_dialog_content = "Dan apakah itu?",
  ui_story_5028_50281001_83_dialog_content = "Langkah terakhir di jalan Anda untuk menyelesaikan magang Anda tidak lain adalah menghentikan rencana jahat Gary!",
  ui_story_5028_50281001_84_dialog_content = "Tunggu sebentar!",
  ui_story_5028_50281001_85_dialog_content = "Bukankah Anda mengatakan itu tentang apa yang baru saja saya lakukan?",
  ui_story_5028_50281001_86_dialog_content = "Secara alami, saya harus menjaga kerahasiaan. Misi terakhir Anda yang sebenarnya sekarang terungkap. Lagi pula, bukankah begitulah sebagian besar petualangan hebat?",
  ui_story_5028_50281001_87_dialog_content = "Tidak bisa diandalkan! Aku tahu aku tidak percaya kata-katamu!",
  ui_story_5028_50281001_88_dialog_content = "Apa yang kalian berdua bicarakan...",
  ui_story_5028_50281001_89_dialog_content = "Adakah yang bisa memberi tahu saya apa yang sedang terjadi?",
  ui_story_5028_50281001_90_dialog_content = "Omong-omong, apa perbedaan antara kau dan Gary ini? Dan kenapa dia ingin menculikmu?",
  ui_story_5028_50281001_91_dialog_content = "Ceritanya panjang...",
  ui_story_5028_50281001_92_dialog_content = "Ada saat saya menghitung Gary di antara teman-teman terdekat saya.",
  ui_story_5028_50281001_93_dialog_content = "Ketertarikan saya dengan makhluk luar biasa ini membawa saya ke beberapa tempat yang tidak biasa. Saya mendapati diri saya dijauhi oleh sebagian besar masyarakat yang sopan.",
  ui_story_5028_50281001_94_dialog_content = "Tapi Gary tidak bisa mendapatkan cukup dari saya begitu dia mengetahui keahlian ekstrozoologi saya. Dia berkeliaran siang dan malam untuk menyelami kedalaman pengetahuan saya.",
  ui_story_5028_50281001_95_dialog_content = "Saya pikir saya telah menemukan semangat yang sama, sesama ahli yang berusaha untuk memajukan batas-batas bidang kami.",
  ui_story_5028_50281001_96_dialog_content = "Artinya, sampai suatu hari, di sana saya sedang mabuk sendiri di sebuah kedai Umbraton ketika dia bertanya kepada saya—",
  ui_story_5028_50281001_97_dialog_content = "Karena Anda tahu banyak tentang makhluk luar biasa ini, Vic.",
  ui_story_5028_50281001_98_dialog_content = "Pasti kalian juga tahu kan hewan mana yang paling kuat?",
  ui_story_5028_50281001_99_dialog_content = "Yang paling kuat... binatang?",
  ui_story_5028_50281001_100_dialog_content = "Hah. Tentu saja, hik—",
  ui_story_5028_50281001_101_dialog_content = "Hewan paling kuat di dunia kita adalah... <color=#FFB400>kylo</color>!",
  ui_story_5028_50281001_102_dialog_content = "Heh. Dapatkan Kyllo untuk mempercayai Anda, dan saya berani mengatakan seluruh dunia akan... menjadi tiram Anda!",
  ui_story_5028_50281001_103_dialog_content = "Dengan Kyllos di sisimu... hik... kau bisa menghancurkan gerbang Kota Gannon, dan menendang pintu Lumopolis, mudah-mudahan!",
  ui_story_5028_50281001_104_dialog_content = "Pertanyaan Gary tidak hanya didorong oleh rasa ingin tahu, saya kira?",
  ui_story_5028_50281001_105_dialog_content = "Heh. Butuh waktu lama bagiku untuk mengetahui niatnya yang sebenarnya.",
  ui_story_5028_50281001_106_dialog_content = "Hanya ada satu alasan mengapa dia berteman denganku.",
  ui_story_5028_50281001_107_dialog_content = "Apa itu, tepatnya?",
  ui_story_5028_50281001_108_dialog_content = "Pembalasan dendam. Dia ingin membalas dendam, terutama terhadap semua binatang yang menakjubkan.",
  ui_story_5028_50281001_109_dialog_content = "Mengapa?",
  ui_story_5028_50281001_110_dialog_content = "Persetan jika saya tahu!",
  ui_story_5028_50281001_111_dialog_content = "Pada akhirnya, dia menghilang begitu saja dariku setelah itu.",
  ui_story_5028_50281001_112_dialog_content = "Kali berikutnya dia muncul adalah selama penculikan itu.",
  ui_story_5028_50281001_113_dialog_content = "Tuan Vic, apa gunanya menculikmu? Anda tidak benar-benar kaya. Bahkan, Anda tampak agak keras.",
  ui_story_5028_50281001_114_dialog_content = "Aku sedih mendengarmu mengatakan itu, Fia.",
  ui_story_5028_50281001_115_dialog_content = "Jawab saja dengan serius sebentar!",
  ui_story_5028_50281001_116_dialog_content = "Aduh!",
  ui_story_5028_50281001_117_dialog_content = "Dia ingin tahu di mana Kyllos bersarang.",
  ui_story_5028_50281001_118_dialog_content = "Apa?!",
  ui_story_5028_50281001_119_dialog_content = "Jadi saya kira dia benar-benar percaya menjinakkan Kyllos akan memberinya semua yang dia butuhkan dan tak tertandingi?",
  ui_story_5028_50281001_120_dialog_content = "Tapi bukankah itu tidak lebih dari fantasi lain yang berputar dari imajinasi Anda yang terlalu aktif?",
  ui_story_5028_50281001_121_dialog_content = "...",
  ui_story_5028_50281001_122_dialog_content = "Jika Anda benar tentang Kyllos, maka seluruh dunia bisa dalam bahaya...",
  ui_story_5028_50281001_123_dialog_content = "Jangan khawatir. Saya yakin itu akan berhasil dengan baik.",
  ui_story_5028_50281001_124_dialog_content = "Gary tidak akan pernah bisa mempengaruhi peristiwa dunia bahkan jika dia entah bagaimana berhasil mendapatkan setiap Kyllo.",
  ui_story_5028_50281001_125_dialog_content = "Kita bisa meninggalkan dia ke perangkatnya.",
  ui_story_5028_50281001_126_dialog_content = "...",
  ui_story_5028_50281001_127_dialog_content = "<size=50>Tidak!</size>",
  ui_story_5028_50281001_128_dialog_content = "Tidak ada ahli ekstrozoologi profesional dengan kehormatan apa pun, seperti calon saya sendiri, yang hanya bisa berdiri dan menyaksikannya terjadi!",
  ui_story_5028_50281001_129_dialog_content = "Lihat!",
  ui_story_5028_50281001_130_dialog_content = "Ahhh...",
  ui_story_5028_50281001_131_dialog_content = "Kita berbicara tentang sekelompok bandit yang memperbudak binatang-binatang yang menakjubkan ini dengan tawaran jahat mereka! Apakah Anda pikir mereka peduli sama sekali tentang mereka atau memperlakukan mereka dengan benar?",
  ui_story_5028_50281001_132_dialog_content = "Jika kita membiarkan Gary menangkap mereka, dia akan memasukkan mereka ke dalam penggiling daging sampai mereka melakukan apa yang dia inginkan!",
  ui_story_5028_50281001_133_dialog_content = "Memaksa makhluk-makhluk cantik ini untuk mengkhianati naluri mereka sangat tidak bermoral—dan tidak dapat ditoleransi!",
  ui_story_5028_50281001_134_dialog_content = "Oy! Itulah semangat!",
  ui_story_5028_50281001_135_dialog_content = "Mari kita terus menyalurkan sentimen itu sementara kita menemukan Gary dan menghentikan rencana gilanya!",
  ui_story_5028_50281001_136_dialog_content = "Saya akan memberi Anda manfaat dari keraguan sekali lagi — sekali saja, demi Kyllos!",
  ui_story_5028_50281001_137_dialog_content = "Rekan-rekan saya yang luar biasa dan saya akan bekerja sama untuk mengatasi ancaman jahat ini!",
  ui_story_5028_50281001_138_dialog_content = "Jadi saya bersumpah sebagai ahli ekstrozoologi yang sedang naik daun!",
  ui_story_5028_50281001_139_dialog_content = "Dan aku bisa mengandalkan kalian semua, Kyllo, Peko, Glooey, Bica dan PlayerName, saya tidak bisa?",
  ui_story_5028_50281001_140_dialog_content = "Lihat!",
  ui_story_5028_50281001_141_dialog_content = "Peko peko!",
  ui_story_5028_50281001_142_dialog_content = "gelap...",
  ui_story_5028_50281001_143_dialog_content = "Hai hai!",
  ui_story_5028_50281001_144_dialog_content = "Eh... oke?",
  ui_story_5028_50281001_145_dialog_content = "Oke! Ayo pergi!",
  ui_story_5028_50281001_146_dialog_content = "Kalian terlihat hampir siap untuk menghancurkan sebuah benteng. Saya harus berpikir kehadiran saya di sini menjadi agak berlebihan kemudian ...",
  ui_story_5028_50281001_147_dialog_content = "Guru Anda yang terhormat karenanya akan menunggu kabar tentang kepulangan Anda yang aman dari rumah—aduh, aduh, aduh!",
  ui_story_5028_50281001_148_dialog_content = "Mudah di sana! Lengan dan kaki Tuan tuamu yang malang tidak bisa menerima hukuman yang kejam dan tidak biasa seperti itu!",
  ui_story_5028_50281001_149_dialog_content = "Maafkan saya karena berpikir sebaliknya setelah seseorang mengatakan bahwa mereka adalah \"abadi berusia 18 tahun.\"",
  ui_story_5028_50281001_150_dialog_content = "Ah-ha-ha...",
  ui_story_5028_50281001_151_dialog_content = "Bukankah ini semua sebagian besar yang Anda lakukan, Guru?",
  ui_story_5028_50281001_152_dialog_content = "Jangan biarkan orang lain kekacauan yang Anda buat dan dapat membantu membersihkan!",
  ui_story_5028_50281001_153_dialog_content = "Aku hanya akan membantumu—",
  ui_story_5028_50281001_154_dialog_content = "Jika Anda mengatakan, misalnya:",
  ui_story_5028_50281001_155_dialog_content = "\"Tolong bantu saya, oh extrozoologist Fia yang perkasa, untuk menangani Eclipsites ini!\"",
  ui_story_5028_50281001_156_dialog_content = "Ha ha. Bukankah kita sedikit melompat? Kita perlu mengetahui rencana induk Gary terlebih dahulu.",
  ui_story_5028_50281001_157_dialog_content = "Nah, kalau begitu, bagaimana kalau saya membiarkan Anda berurusan dengan Eclipsites itu dalam perjalanan kembali?",
  ui_story_5028_50281001_158_dialog_content = "Hahaha... Ah?!",
  ui_story_5028_50281001_159_dialog_content = "Astaga! Mengaum!",
  ui_story_5028_50281001_160_dialog_content = "Aduh! Membantu!",
  ui_story_5028_50281001_161_dialog_content = "Aku tidak bisa menahan mereka sendiri!",
  ui_story_5028_50281002_1_dialog_content = "Aduh... Punggungku yang malang...",
  ui_story_5028_50281002_2_dialog_content = "Saya bukan penggemar latihan intensitas tinggi.",
  ui_story_5028_50281002_3_dialog_content = "Saya pikir Anda meremehkan diri sendiri. Lagipula, kamu tidak jauh lebih tua dariku, Vic, kan?",
  ui_story_5028_50281002_4_dialog_content = "Jangan menilai sebuah buku dari sampulnya, PlayerName.",
  ui_story_5028_50281002_5_dialog_content = "Saya mungkin berusia 18 tahun yang abadi tetapi pengalaman yang saya miliki akan cukup banyak menurut standar Anda.",
  ui_story_5028_50281002_6_dialog_content = "Ini dia lagi, pria bodoh. Begitu cerdas!",
  ui_story_5028_50281002_7_dialog_content = "Sayangnya, kredibilitas Anda menipis!",
  ui_story_5028_50281002_8_dialog_content = "Boo-hoo, sejujurnya aku patah hati, Fia.",
  ui_story_5028_50281002_9_dialog_content = "(Apakah Vic akan menangis?!)",
  ui_story_5028_50281002_10_dialog_content = "Tentunya tidak ada kedalaman kesepian yang lebih dalam daripada seorang Guru yang ditinggalkan dan dihina oleh murid-muridnya?",
  ui_story_5028_50281002_11_dialog_content = "Saya pikir saya mengerti mengapa Shira bahkan tidak memberi Anda waktu ketika Anda membutuhkan bantuan. Anda kerja keras.",
  ui_story_5028_50281002_12_dialog_content = "Hai! Shira saat ini sangat sibuk dengan masalahnya sendiri, terima kasih banyak. Itu sebabnya dia tidak masuk.",
  ui_story_5028_50281002_13_dialog_content = "Masalah? Masalah apa?",
  ui_story_5028_50281002_14_dialog_content = "Masalah macam apa yang dapat menginspirasinya untuk menyerahkan Gurunya kepada para bandit?",
  ui_story_5028_50281002_15_dialog_content = "Shira, bocah malang, tersihir oleh ketertarikan yang sama pada binatang buas yang kita semua miliki.",
  ui_story_5028_50281002_16_dialog_content = "Sayangnya, usahanya telah terperosok oleh sedikit nasib buruk. Apakah Anda melihat sesuatu yang tidak biasa tentang dia?",
  ui_story_5028_50281002_17_dialog_content = "Apakah Anda mengacu pada ...",
  ui_story_5028_50281002_18_dialog_content = "Kaki tentakelnya?",
  ui_story_5028_50281002_19_dialog_content = "Hmm... Bisa dibilang seperti itu.",
  ui_story_5028_50281002_20_dialog_content = "Binatang buas yang menakjubkan takut padanya?",
  ui_story_5028_50281002_21_dialog_content = "Memang. Perseptif Anda.",
  ui_story_5028_50281002_22_dialog_content = "Sebuah insiden malang menyatukan kaki Shira dengan kaki gurita di dekatnya.",
  ui_story_5028_50281002_23_dialog_content = "Betapa hewan-hewan mencintainya di masa lalu. Setelah transformasinya, mereka sekarang mendekat dengan ketakutan dari kejauhan, jika sama sekali.",
  ui_story_5028_50281002_24_dialog_content = "Gurita mewakili spesies yang aneh dan menakutkan bagi kebanyakan hewan.",
  ui_story_5028_50281002_25_dialog_content = "Itu adalah pukulan telak bagi Shira, itu sudah pasti. Namun tidak mengurangi kecintaannya pada bidang tersebut.",
  ui_story_5028_50281002_26_dialog_content = "Jika gairahnya berubah sama sekali, kita dapat mengatakan bahwa itu hanya berubah menjadi binatang buas yang menakjubkan.",
  ui_story_5028_50281002_27_dialog_content = "Bagaimana maksudmu?",
  ui_story_5028_50281002_28_dialog_content = "Jangan bilang kamu tidak melihat apa-apa?",
  ui_story_5028_50281002_29_dialog_content = "Dia sangat peduli pada binatang yang menakjubkan, aku akan memberinya itu...",
  ui_story_5028_50281002_30_dialog_content = "Tapi dia datang untuk melihat saya sebagai tidak lebih dari seorang \"penghobi\"!",
  ui_story_5028_50281002_31_dialog_content = "Seperti seorang pemain amatir yang dia anggap saya, dia bahkan tidak mempercayai keamanan metode saya.",
  ui_story_5028_50281002_32_dialog_content = "... Apakah itu menurut Anda sebagai pendapat yang masuk akal?",
  ui_story_5028_50281002_33_dialog_content = "...",
  ui_story_5028_50281002_34_dialog_content = "Oh, Shira, aku sangat menyesal tentang Guru kita...",
  ui_story_5028_50281002_35_dialog_content = "Saya melihat sikap yang sama juga terjadi pada Anda, Fia.",
  ui_story_5028_50281002_36_dialog_content = "Bagaimanapun, ini bukan kesalahpahaman pertama yang harus kuhadapi dalam hidupku, dan itu tidak akan menjadi yang terakhir.",
  ui_story_5028_50281002_37_dialog_content = "Singkatnya, Shira tidak menyukai metode \"tanpa persiapan\" saya dan memfokuskan semua upayanya untuk menjadi ahli ekstrozoologi profesional.",
  ui_story_5028_50281002_38_dialog_content = "Seorang \"ekstrozoolog profesional\"? Apakah ada hal seperti itu?",
  ui_story_5028_50281002_39_dialog_content = "Yah, dia telah mempelajari banyak bahan misterius dan merancang banyak metode untuk mengamati binatang buas yang menakjubkan.",
  ui_story_5028_50281002_40_dialog_content = "Misalnya, dengan memberikan tag pergelangan kaki ke binatang buas yang dia temui di alam liar sebelum melepaskannya kembali.",
  ui_story_5028_50281002_41_dialog_content = "Jadi, ketika dia hanya menangkap jenis binatang ajaib tertentu, dia bisa mendapatkan perkiraan kasar dari total populasi mereka dengan jumlah tanda pergelangan kaki.",
  ui_story_5028_50281002_42_dialog_content = "Jadi Shira yang menaruh semua tanda itu di kaki Drakolion?",
  ui_story_5028_50281002_43_dialog_content = "Ya. Yah, mungkin. Siapa lagi yang akan melakukannya selain dia?",
  ui_story_5028_50281002_44_dialog_content = "Kalau dipikir-pikir, dia datang dengan beberapa teknik bagus. Beberapa dari mereka, harus saya akui, cukup cerdik!",
  ui_story_5028_50281002_45_dialog_content = "Namun seiring berjalannya waktu, \"perbedaan pendapat\" kita semakin memburuk!",
  ui_story_5028_50281002_46_dialog_content = "Dia menyalahkan kecelakaannya sebagian karena kurangnya pengetahuannya, tetapi juga pada... kesalahanku.",
  ui_story_5028_50281002_47_dialog_content = "Dia berubah dari menganggapku sebagai praktisi yang tidak serius menjadi sesuatu yang berbahaya untuk ditolak!",
  ui_story_5028_50281002_48_dialog_content = "Hah? Jadi kau bertanggung jawab atas apa yang terjadi pada Shira?",
  ui_story_5028_50281002_49_dialog_content = "Tidak, sama sekali tidak! Itulah yang dimaksud dengan kecelakaan! Tidak ada yang bersalah!",
  ui_story_5028_50281002_50_dialog_content = "Shira ingin tahu dari mana dia berasal dan mencari pengetahuan tentang masa lalunya.",
  ui_story_5028_50281002_51_dialog_content = "Saya perhatikan dia punya gurita kecil, jadi saya menyarankan dia untuk memeriksa habitat dari mana teman kecilnya berasal.",
  ui_story_5028_50281002_52_dialog_content = "Bagaimana saya tahu bahwa dia akan memetakan sebuah kapal sampai ke laut dalam dan kemudian memiliki nasib buruk untuk menabrak badai petir ...",
  ui_story_5028_50281002_53_dialog_content = "Gurita kecil itu bergabung dengan Shira untuk menyelamatkan hidupnya melalui kekuatan regenerasinya yang luar biasa.",
  ui_story_5028_50281002_54_dialog_content = "Yang saya lakukan hanyalah mengungkapkan cara menemukan habitat gurita dan tidak ada yang salah.",
  ui_story_5028_50281002_55_dialog_content = "Hmph, kamu tidak akan mendapatkan simpatiku bahkan dengan wajah \"Aku akan menangis\" itu.",
  ui_story_5028_50281002_56_dialog_content = "Inilah yang terjadi ketika Anda memberikan nasihat buruk secara tidak bertanggung jawab.",
  ui_story_5028_50281002_57_dialog_content = "Jika Anda ingin memperbaiki keadaan, hal pertama yang harus kita lakukan adalah menemukan habitat Kyllos dan menghentikan rencana gila Gary!",
  ui_story_5028_50281002_58_dialog_content = "Sigh, Anda memiliki semua tanda magang, Fia, tetapi tidak ada rasa hormat.",
  ui_story_5028_50281002_59_dialog_content = "Sepertinya setelah penculikan yang panjang, aku masih harus menjalani perjalanan dengan perut kosong...",
  ui_story_5028_50281002_60_dialog_content = "Apakah kamu lapar?",
  ui_story_5028_50281002_61_dialog_content = "Flatbread ini akan membuat Anda kenyang!",
  ui_story_5028_50281002_62_dialog_content = "Ooh? Apakah saya mendeteksi bau tepung dan kilau keemasan yang renyah...? Tidak masalah jika saya mulai sekarang ...",
  ui_story_5028_50281002_63_dialog_content = "Nom-nom, rasa lapar saya telah mengubahnya menjadi roti pipih paling enak yang bisa dibayangkan!",
  ui_story_5028_50281002_64_dialog_content = "Entah bagaimana itu terlihat familier... Tunggu sebentar. Kenapa kamu membawa roti pipih, Fia?",
  ui_story_5028_50281002_65_dialog_content = "Karena saya pikir orang jahat yang menculik Tuan saya mungkin tidak cukup perhatian untuk menyediakan makanan.",
  ui_story_5028_50281002_66_dialog_content = "Jadi saya membawa bekal khusus.",
  ui_story_5028_50281002_67_dialog_content = "Nom-nom, murid yang hebat memang adalah orang yang mempertimbangkan kebutuhan Tuannya!",
  ui_story_5028_50281002_68_dialog_content = "Meskipun saya harus mengatakan saya membelinya beberapa hari yang lalu. Saya harap mereka tidak menjadi buruk.",
  ui_story_5028_50281002_69_dialog_content = "Nom—batuk, hei!",
  ui_story_5028_50281002_70_dialog_content = "Vik?!",
  ui_story_5028_50281002_71_dialog_content = "Batuk, aku baik-baik saja sekarang. Untuk saat ini.",
  ui_story_5028_50281002_72_dialog_content = "Apakah Anda ingin beberapa lagi? Saya membawa beberapa orang lain dengan rasa yang berbeda.",
  ui_story_5028_50281002_73_dialog_content = "T-Tidak apa-apa. aku sudah kenyang. Pada satu saja.",
  ui_story_5028_50281002_74_dialog_content = "Ayo pergi!",
  ui_story_5028_50281002_75_dialog_content = "Dan hentikan pria jahat itu dan rencananya!",
  ui_story_5028_50281002_76_dialog_content = "Jadi mereka adalah bandit yang menculik PlayerName?",
  ui_story_5028_50281002_77_dialog_content = "Mereka tampak agak aneh.",
  ui_story_5028_50281002_78_dialog_content = "Apa pedulimu? Mari kita masuk dan mengepel lantai bersama mereka. Apakah itu terdengar seperti rencana yang cukup bagi Anda?",
  ui_story_5028_50281002_79_dialog_content = "Betapa cerobohnya, Smokey.",
  ui_story_5028_50281002_80_dialog_content = "Bukan apa yang saya harapkan dari seorang anggota bangsawan.",
  ui_story_5028_50281002_81_dialog_content = "Ssst. Tidak berdebat.",
  ui_story_5028_50281002_82_dialog_content = "Ck...",
  ui_story_5028_50281002_83_dialog_content = "Mari kita ikuti saja mereka. Lalu kita akan masuk dan menyelamatkan PlayerName ketika ada kesempatan!",
  ui_story_5028_50281101_1_dialog_content = "<color=#e8d9bb>Habitat Kyllos</color>",
  ui_story_5028_50281101_2_dialog_content = "Saya harus mengakui bahwa Anda memiliki beberapa keterampilan, gadis muda saya.",
  ui_story_5028_50281101_3_dialog_content = "Tapi berapa lama Anda bisa bertahan?",
  ui_story_5028_50281101_4_dialog_content = "Gary",
  ui_story_5028_50281101_X4_dialog_content = "38 tahun",
  ui_story_5028_50281101_X5_dialog_content = "Seorang penjahat yang berkeliling menangkap binatang yang menakjubkan.",
  ui_story_5028_50281101_5_dialog_content = "Jika Anda akan membungkuk begitu rendah untuk menggunakan makhluk-makhluk ini melawan saya, saya dapat melihat Anda adalah seseorang yang harus saya hentikan ...",
  ui_story_5028_50281101_6_dialog_content = "Dan saya bisa melihat Anda adalah seseorang dengan kekuatan untuk dengan mudah mengalahkan Eclipsites.",
  ui_story_5028_50281101_7_dialog_content = "Namun Anda begitu terhambat oleh cinta imajinasi Anda untuk hewan sehingga Anda tidak mau melakukan apa yang perlu.",
  ui_story_5028_50281101_8_dialog_content = "Lebih baik menanggung serangan keterlaluan mereka, saya menerimanya? Orang bodoh yang malang.",
  ui_story_5028_50281101_9_dialog_content = "Diam.",
  ui_story_5028_50281101_10_dialog_content = "Setidaknya aku tahu siapa yang harus bertanggung jawab atas semua kejahatan ini.",
  ui_story_5028_50281101_11_dialog_content = "Dan siapa yang membuat binatang buas yang menakjubkan ini menjadi tawanan perang!",
  ui_story_5028_50281101_12_dialog_content = "Tawanan perang? Heh. Konyol!",
  ui_story_5028_50281101_13_dialog_content = "Beraninya kau menyebut makhluk yang begitu sederhana dan brutal sebagai \"tawanan\" dalam bentuk apa pun? Mereka tidak lebih tawanan daripada binatang beban lainnya.",
  ui_story_5028_50281101_14_dialog_content = "Faktanya, orang-orang biadab bodoh ini tidak pantas berbagi sumber daya dunia dan udaranya dengan kami!",
  ui_story_5028_50281101_15_dialog_content = "Kamu... tutup mulutmu!",
  ui_story_5028_50281101_16_dialog_content = "*Mendengkur*",
  ui_story_5028_50281101_17_dialog_content = "Hah!?",
  ui_story_5028_50281101_18_dialog_content = "Pergi. Bunuh dia.",
  ui_story_5028_50281101_19_dialog_content = "Singkirkan ide konyolnya yang bodoh ini.",
  ui_story_5028_50281101_20_dialog_content = "Astaga! Mengaum!",
  ui_story_5028_50281101_21_dialog_content = "Tolong jangan...",
  ui_story_5028_50281101_22_dialog_content = "Hentikan mereka!",
  ui_story_5028_50281101_23_dialog_content = "Lihat!",
  ui_story_5028_50281101_24_dialog_content = "Tembakan yang bagus, Fia!",
  ui_story_5028_50281101_25_dialog_content = "Terima kasih. Jangan bilang kau terkejut aku bisa bertarung?",
  ui_story_5028_50281101_26_dialog_content = "Shira, kamu baik-baik saja?",
  ui_story_5028_50281101_27_dialog_content = "Kenapa kamu...",
  ui_story_5028_50281101_28_dialog_content = "Anda aman sekarang. Kami di sini untuk menghentikan Gary!",
  ui_story_5028_50281101_29_dialog_content = "Vic menceritakan semuanya kepada kami.",
  ui_story_5028_50281101_30_dialog_content = "Kami akan membantumu menghentikan Gary!",
  ui_story_5028_50281101_31_dialog_content = "Keluar dari sini! Kita tidak bisa mengambil risiko.",
  ui_story_5028_50281101_32_dialog_content = "Orang ini adalah segelintir!",
  ui_story_5028_50281101_33_dialog_content = "Aku terkejut dia berhasil memanggil beberapa kavaleri.",
  ui_story_5028_50281101_34_dialog_content = "Dan kupikir kau akan kabur begitu saja setelah apa yang terjadi, Vic.",
  ui_story_5028_50281101_35_dialog_content = "Aku tidak pengecut seperti yang kau pikirkan, Gary.",
  ui_story_5028_50281101_36_dialog_content = "Jika Anda akan mulai berlaku, saya mungkin harus membantu diri saya sendiri juga.",
  ui_story_5028_50281101_37_dialog_content = "Saya sangat senang mengungkapkan kekuatan biadab yang mengerikan ini!",
  ui_story_5028_50281101_X37_dialog_content = "Dorong Eclipsites itu ke sini juga. Bersama sekarang!",
  ui_story_5028_50281101_38_dialog_content = "Gan...",
  ui_story_5028_50281101_39_dialog_content = "Pisahkan mereka.",
  ui_story_5028_50281101_40_dialog_content = "Iya Bos!",
  ui_story_5028_50281101_41_dialog_content = "Gahhhh!",
  ui_story_5028_50281101_42_dialog_content = "Serang, Kylo, PlayerName!",
  ui_story_5028_50281101_43_dialog_content = "Lihat!",
  ui_story_5028_50281101_44_dialog_content = "Hah? Dan saya?",
  ui_story_5028_50281101_45_dialog_content = "Berhenti melamun! Berikan perintah!",
  ui_story_5028_50281102_1_dialog_content = "Lemah. Sangat lemah...",
  ui_story_5028_50281102_2_dialog_content = "Bagaimana Anda bisa memiliki binatang buas yang begitu kuat di sisi Anda dan tidak tahu apa-apa tentang cara menggunakannya?",
  ui_story_5028_50281102_3_dialog_content = "Kenapa, kau kecil...!",
  ui_story_5028_50281102_4_dialog_content = "Pelajaran ini ada di rumah: untuk menekuk satu makhluk untuk melakukan kehendak Anda dalam pertempuran, lakukan dengan demikian ...",
  ui_story_5028_50281102_5_dialog_content = "Bangunlah, dasar kungkang yang menyedihkan, dan hancurkan mereka!",
  ui_story_5028_50281102_6_dialog_content = "Mengaum!!!",
  ui_story_5028_50281102_7_dialog_content = "Anda... melatih Drakolion ini?",
  ui_story_5028_50281102_8_dialog_content = "Mengaum!!!",
  ui_story_5028_50281102_9_dialog_content = "Lihat!",
  ui_story_5028_50281102_10_dialog_content = "Hentikan kegilaan ini! Tidak ada binatang buas yang ingin melawan siapa pun!",
  ui_story_5028_50281102_11_dialog_content = "Mereka tidak mau?",
  ui_story_5028_50281102_12_dialog_content = "Ha ha! Saya senang saya tidak perlu khawatir tentang apa yang diinginkan binatang buas ini!",
  ui_story_5028_50281102_13_dialog_content = "Saya hanya membutuhkan mereka untuk cukup takut dan menghormati saya untuk mengorbankan hidup mereka!",
  ui_story_5028_50281102_14_dialog_content = "Anda sudah benar-benar gila! Dan saya, sebagai ahli ekstrozoologi, akan meminta pertanggungjawaban Anda!",
  ui_story_5028_50281102_15_dialog_content = "Kerja bagus, muridku yang brilian! Kamu bisa melakukannya!",
  ui_story_5028_50281102_16_dialog_content = "Dorongan Anda sia-sia karena tidak berguna.",
  ui_story_5028_50281102_17_dialog_content = "Ya Tuhan. Muridku menyerangku lagi...",
  ui_story_5028_50281102_18_dialog_content = "Kata-kata yang kuat dari hal kecil seperti itu!",
  ui_story_5028_50281102_19_dialog_content = "Sayang sekali Anda tidak memiliki kekuatan untuk mendukungnya.",
  ui_story_5028_50281102_20_dialog_content = "Astaga!",
  ui_story_5028_50281102_21_dialog_content = "Yaargh!",
  ui_story_5028_50281102_22_dialog_content = "Fi!!!",
  ui_story_5028_50281102_23_dialog_content = "Hah!?",
  ui_story_5028_50281102_24_dialog_content = "Aduh Buyung. Kita sedang hancur...",
  ui_story_5028_50281102_25_dialog_content = "Kami menyerah! Tolong biarkan kami pergi.",
  ui_story_5028_50281102_26_dialog_content = "Apa yang salah denganmu? Apakah Anda tidak akan menawarkan sedikit perlawanan?",
  ui_story_5028_50281102_27_dialog_content = "Resistensi apa? Kami tidak bisa melakukan apa-apa.",
  ui_story_5028_50281102_28_dialog_content = "Dia membawamu dan Fia keluar, bukan?",
  ui_story_5028_50281102_29_dialog_content = "PlayerName adalah Caelestit, bukan Aurorian. Dia tidak bisa melawan.",
  ui_story_5028_50281102_30_dialog_content = "Dan saya sudah punya cukup banyak masalah dengan kaki dan tangan tua saya yang malang.",
  ui_story_5028_50281102_31_dialog_content = "Jadi satu-satunya pilihan kita adalah menyerah.",
  ui_story_5028_50281102_32_dialog_content = "Anda harus setidaknya mencoba menawarkan beberapa perlawanan...",
  ui_story_5028_50281102_33_dialog_content = "Resistensi apa? Saya katakan kita memilih kelangsungan hidup praktis.",
  ui_story_5028_50281102_34_dialog_content = "Apakah Anda pikir saya akan membiarkan Anda berjalan keluar dari sini jika Anda menyerah?",
  ui_story_5028_50281102_35_dialog_content = "Tidak, kamu tetap bersamaku sampai kamu bisa menyaksikan momen kebesaranku!",
  ui_story_5028_50281102_36_dialog_content = "Amankan mereka dengan erat dan antar mereka ke sel tahanan.",
  ui_story_5028_50281102_37_dialog_content = "Iya Bos!",
  ui_story_5028_50281102_38_dialog_content = "Heh. Anda membuat hidup sangat sulit bagi kami terakhir kali. Sekarang kita bisa mengungkapkan \"terima kasih\" kita.",
  ui_story_5028_50281102_39_dialog_content = "Lihat! halo!",
  ui_story_5028_50281102_40_dialog_content = "Kyllo!",
  ui_story_5028_50281102_41_dialog_content = "Ugh!",
  ui_story_5028_50281102_42_dialog_content = "Membekukan!",
  ui_story_5028_50281102_43_dialog_content = "Tidak begitu ketat! Saya rentan terhadap kejang lengan. Aduh!",
  ui_story_5028_50281102_44_dialog_content = "Ugh...",
  ui_story_5028_50281102_45_dialog_content = "Ini dia. Kami benar-benar dan benar-benar kacau ...",
  ui_story_5028_50281102_46_dialog_content = "Buka mata Anda lebar-lebar, dan amati apa yang akan saya tunjukkan kepada Anda.",
  ui_story_5028_50281102_47_dialog_content = "Saya akan menunjukkan kepada dunia betapa menakutkan dan kuatnya orang-orang biadab ini sampai gagasan itu tertanam kuat di benak setiap orang.",
  ui_story_5028_50281102_48_dialog_content = "Oh. Jadi itu rencana utamamu selama ini?",
  ui_story_5028_50281102_49_dialog_content = "Ada apa denganmu dan binatang ajaib? Mengapa Anda sangat membenci mereka?",
  ui_story_5028_50281102_50_dialog_content = "Saya ragu seorang \"penyayang binatang\" seperti Anda akan mengerti.",
  ui_story_5028_50281102_51_dialog_content = "Yang perlu Anda ketahui adalah saya menganggap mereka bertanggung jawab karena merampas apa yang paling penting bagi saya.",
  ui_story_5028_50281102_52_dialog_content = "\"Yang paling penting\"... Hah?",
  ui_story_5028_50281102_53_dialog_content = "Anda menjengkelkan, bukan?",
  ui_story_5028_50281102_54_dialog_content = "Saya sedang dalam perjalanan untuk menjebak makhluk-makhluk ini ketika Anda memutuskan untuk melempar kunci pas dalam pekerjaan.",
  ui_story_5028_50281102_55_dialog_content = "Itu benar. Saya mampu untuk bersabar.",
  ui_story_5028_50281102_56_dialog_content = "Asalkan si kecil ini tidak kabur...",
  ui_story_5028_50281102_57_dialog_content = "Lo, lo!",
  ui_story_5028_50281102_58_dialog_content = "Apa itu?",
  ui_story_5028_50281102_59_dialog_content = "Itu membuat suara yang sama seperti Kyllo meskipun terlihat agak aneh.",
  ui_story_5028_50281102_60_dialog_content = "Apakah itu juga Kyllo?",
  ui_story_5028_50281102_61_dialog_content = "Semua keahlian saya mengatakan ya, mereka adalah spesies yang sama.",
  ui_story_5028_50281102_62_dialog_content = "Ada jenis lain dari Kyllo? Bagaimana akhirnya terlihat seperti itu?",
  ui_story_5028_50281102_63_dialog_content = "Ada banyak kemungkinan.",
  ui_story_5028_50281102_64_dialog_content = "Evolusi yang tiba-tiba, faktor lingkungan, dan variasi sub-ras semuanya dapat menyebabkan perbedaan individu tersebut.",
  ui_story_5028_50281102_65_dialog_content = "Ini terlihat sangat berbeda dari Kyllo saya. Apakah Anda yakin mereka spesies yang sama?",
  ui_story_5028_50281102_66_dialog_content = "Beberapa kemungkinan bisa menjelaskan itu—eh, sebenarnya tidak ada yang terlintas dalam pikiran.",
  ui_story_5028_50281102_67_dialog_content = "Kami membutuhkan Anda untuk menjadi yang paling dapat diandalkan sekarang!",
  ui_story_5028_50281102_68_dialog_content = "Heh, hargai momen berharga yang menyenangkan ini. Mereka akan menjadi yang terakhir untukmu.",
  ui_story_5028_50281102_69_dialog_content = "Mengapa kau melakukan ini?",
  ui_story_5028_50281102_70_dialog_content = "Meskipun orang-orang biadab ini tidak dapat memahami bahasa manusia, mereka dapat menanggapi tangisan jenis mereka sendiri.",
  ui_story_5028_50281102_71_dialog_content = "Lo, lo!",
  ui_story_5028_50281102_72_dialog_content = "Dengan itu, saya bisa menarik semua Kyllos di sekitar bagian ini ke jaring saya. Maka itu akan menjadi proses pelatihan yang sederhana.",
  ui_story_5028_50281102_73_dialog_content = "Hahaha... Hahaha!!",
  ui_story_5028_50281102_74_dialog_content = "Dan semua Aurorian of Astra akan segera tahu betapa menakutkannya teror yang bisa mereka lakukan!",
  ui_story_5028_50281102_75_dialog_content = "Dan bersatu denganku dalam kesedihan yang sama.",
  ui_story_5028_50281102_76_dialog_content = "Tetap awasi mereka. Jangan biarkan mereka lolos.",
  ui_story_5028_50281102_77_dialog_content = "Iya Bos!",
  ui_story_5028_50281102_78_dialog_content = "<color=#e8d9bb>Pangkalan Gary</color>",
  ui_story_5028_50281102_79_dialog_content = "Silahkan!",
  ui_story_5028_50281102_80_dialog_content = "Tidak begitu kasar!",
  ui_story_5028_50281102_81_dialog_content = "Aku akan berjalan di sekitar Anda ketika saya keluar dari sini!",
  ui_story_5028_50281102_82_dialog_content = "Ya, itulah semangatnya, Fia.",
  ui_story_5028_50281102_83_dialog_content = "Aku tidak percaya kau masih sembrono pada saat seperti ini.",
  ui_story_5028_50281102_84_dialog_content = "Anda tidak memiliki rasa kepatutan. Ya ampun, kita dalam bahaya besar!",
  ui_story_5028_50281102_85_dialog_content = "Diam! Satu lagi mengintip dari Anda dan saya akan membuat Anda semua tergantung!",
  ui_story_5028_50281102_86_dialog_content = "...",
  ui_story_5028_50281102_87_dialog_content = "...",
  ui_story_5028_50281102_88_dialog_content = "Aku tidak mendengarkanmu! Jika Anda ingin saya berhenti bicara, maka saya akan—oof!",
  ui_story_5028_50281102_89_dialog_content = "Dinginkan selama beberapa menit sambil memikirkan rencana, oke?",
  ui_story_5028_50281102_90_dialog_content = "(Apa yang harus saya lakukan? Saya tidak bisa memikirkan apa pun sendiri...)",
  ui_story_5028_50281102_91_dialog_content = "(Oh, benar! Karena saya tidak bisa berbicara, mengapa saya tidak menggunakan kemampuan psikis saya untuk berkomunikasi dengan semua orang?)",
  ui_story_5028_50281102_92_dialog_content = "(Dengan cara ini para bandit itu seharusnya tidak bisa melihat kita sedang berdiskusi.)",
  ui_story_5028_50281102_93_option_content = "Angkatan Meningkatkan!",
  ui_story_5028_50281102_94_dialog_content = "Fi! Bisakah kamu mendengarku?",
  ui_story_5028_50281102_95_dialog_content = "Wow! PlayerName, bisakah Anda setidaknya memberi saya pemberitahuan sebelum menggunakan kekuatan Anda?",
  ui_story_5028_50281102_96_dialog_content = "Saya minta maaf. Ini darurat!",
  ui_story_5028_50281102_97_dialog_content = "Vic?",
  ui_story_5028_50281102_98_dialog_content = "Oh ya, kemampuan psikis Caelestite, saya mengerti? Ah, masa lalu...",
  ui_story_5028_50281102_99_dialog_content = "Dan Shira!",
  ui_story_5028_50281102_100_dialog_content = "Aku mendengarmu.",
  ui_story_5028_50281102_101_dialog_content = "Fia, mari kita bahas bagaimana kita bisa mengejarnya!",
  ui_story_5028_50281102_102_dialog_content = "Sebuah lari untuk itu? Dan bagaimana cara melakukannya?",
  ui_story_5028_50281102_103_dialog_content = "Mereka mendapatkan Kyllo-ku, dan sisanya bukan tandingan para bandit ini.",
  ui_story_5028_50281102_104_dialog_content = "Sudahkah Anda bertanya pada Shira? Dia sangat kuat, meskipun sedikit aneh. Mungkin dia punya beberapa ide.",
  ui_story_5028_50281102_105_dialog_content = "Shira, bisakah kamu memikirkan sesuatu? Apakah ada cara untuk menggunakan kekuatan binatang yang menakjubkan ini untuk melarikan diri?",
  ui_story_5028_50281102_106_dialog_content = "Daripada memikirkan cara untuk mengubah makhluk malang ini melawan bandit jahat ini...",
  ui_story_5028_50281102_107_dialog_content = "Saya pikir saya mungkin lebih beruntung mendapatkan diri saya keluar dari tali terkutuk ini.",
  ui_story_5028_50281102_108_dialog_content = "Seharusnya tidak terlalu sulit untuk merobeknya begitu saya pulih.",
  ui_story_5028_50281102_109_dialog_content = "Tapi jika mereka tidak membantu kita sama sekali... Vic, ada ide?",
  ui_story_5028_50281102_110_dialog_content = "Kami tidak terburu-buru, PlayerName.",
  ui_story_5028_50281102_111_dialog_content = "Kami mungkin tidak bisa bergerak, tapi ini mungkin saat yang tepat untuk menggunakan kemampuan Caelestitmu untuk memeriksa sekeliling kami.",
  ui_story_5028_50281102_112_dialog_content = "Nasib kami ada di tangan Anda, PlayerName.",
  ui_story_5028_50281102_113_dialog_content = "Seperti itu? Pada saya?",
  ui_story_5028_50281102_114_dialog_content = "Saya akan memberikan yang terbaik.",
  ui_story_5028_50281102_115_option_content = "Angkatan Meningkatkan!",
  ui_story_5028_50281102_116_dialog_content = "...",
  ui_story_5028_50281102_117_dialog_content = "(Ada bandit yang berpatroli di dekat sini...)",
  ui_story_5028_50281102_118_dialog_content = "(Beberapa binatang ajaib yang dikurung).",
  ui_story_5028_50281102_119_dialog_content = "(Banyak binatang menakjubkan yang terlihat seperti Kyllos?)",
  ui_story_5028_50281102_120_dialog_content = "Vic, itu tidak bagus. Para bandit telah menangkap sejumlah besar Kyllos!",
  ui_story_5028_50281102_121_dialog_content = "Ya ampun. Jadi dia benar-benar berhasil?",
  ui_story_5028_50281102_122_dialog_content = "Kita seharusnya tidak perlu terlalu khawatir kecuali dia berhasil membangkitkan kemampuan Kyllos.",
  ui_story_5028_50281102_123_dialog_content = "Benar. Aku akan melihat-lihat lagi. Saya pikir saya bisa merasakan beberapa aktivitas yang jauh.",
  ui_story_5028_50281102_124_dialog_content = "itu Revy, bersembunyi di beberapa sampah.",
  ui_story_5028_50281102_125_dialog_content = "Tunggu, Revy?!",
  ui_story_5028_50281102_126_dialog_content = "PlayerName! Anda akhirnya memperhatikan saya!",
  ui_story_5028_50281102_127_dialog_content = "Kami baru saja memulai dan Anda menghilang dari saya, PlayerName.",
  ui_story_5028_50281102_128_dialog_content = "Itu benar, kami baru mulai bermain ketika Fia membawaku pergi untuk membantunya.",
  ui_story_5028_50281102_129_dialog_content = "Aku sangat menyesal.",
  ui_story_5028_50281102_130_dialog_content = "Kami telah mencari Anda selama berabad-abad!",
  ui_story_5028_50281102_131_dialog_content = "Kita? Anda memiliki orang lain dengan Anda? Biarkan aku melihat lagi!",
  ui_story_5028_50281102_132_dialog_content = "Dia Genevieve...",
  ui_story_5028_50281102_133_dialog_content = "PlayerName, apakah Anda punya banyak teman baru di sana?",
  ui_story_5028_50281102_134_dialog_content = "Anda sangat populer, PlayerName.",
  ui_story_5028_50281102_135_dialog_content = "Aku menoleh sejenak dan kemudian, wow! Lihat berapa banyak pengikut yang Anda miliki.",
  ui_story_5028_50281102_136_dialog_content = "Dan apakah itu? Smokey? Dan dia berdamai dengan Genevieve?",
  ui_story_5028_50281102_137_dialog_content = "Oh. Apakah mereka berteman dengan Anda?",
  ui_story_5028_50281102_138_dialog_content = "Saya menantikan kesenangan yang berapi-api.",
  ui_story_5028_50281102_139_dialog_content = "Oh tidak, tolong jangan mengejekku!",
  ui_story_5028_50281102_140_dialog_content = "Besar. Saya pikir kita semua bersama-sama pasti bisa membalikkan keadaan ini!",
  ui_story_5028_50281102_141_dialog_content = "Saya sedang dalam masalah, dan saya butuh bantuan Anda!",
  ui_story_5028_50281102_142_dialog_content = "Tentu saja. PlayerName adalah teman saya, dan saya akan selalu siap membantu!",
  ui_story_5028_50281102_143_dialog_content = "Kami semua datang ke sini hanya untuk menemukanmu, PlayerName.",
  ui_story_5028_50281102_144_dialog_content = "Terima kasih!",
  ui_story_5028_50281102_145_dialog_content = "Fia, Shira, Vic: kita punya jalan keluar!",
  ui_story_5028_50281102_146_dialog_content = "Saya menemukan beberapa orang untuk membantu kami!",
  ui_story_5028_50281102_147_dialog_content = "Hah. Itu butuh waktu lama!",
  ui_story_5028_50281102_148_dialog_content = "Saat Anda berlama-lama dengan telepati Anda, saya sudah menemukan yang sangat <color=#FFB400>rencana brilian</color>.",
  ui_story_5028_50281102_149_dialog_content = "Hah? A-Rencana apa yang kamu buat?",
  ui_story_5028_50281102_150_dialog_content = "Jangan pernah meremehkan ahli ekstrozoologi!",
  ui_story_5028_50281102_151_dialog_content = "Ini adalah apa yang kita mulai dengan, dan kemudian kita akan...",
  ui_story_5028_50281201_1_dialog_content = "<color=#e8d9bb>Di luar markas Gary</color>",
  ui_story_5028_50281201_2_dialog_content = "Bagaimana menurutmu? Apakah Anda pikir rencana bos benar-benar dapat bekerja?",
  ui_story_5028_50281201_3_dialog_content = "Sst... Tenang.",
  ui_story_5028_50281201_4_dialog_content = "Jangan menyuarakan keraguan Anda atau dia akan menggantung Anda di pohon sepanjang malam yang membekukan.",
  ui_story_5028_50281201_5_dialog_content = "Dan apa yang dikatakan Vic itu?",
  ui_story_5028_50281201_6_dialog_content = "Sepertinya bos benar-benar percaya padanya!",
  ui_story_5028_50281201_7_dialog_content = "<color=#e8d9bb>Toot-toot</color>",
  ui_story_5028_50281201_8_dialog_content = "Dengarkan. Bos ada pesanan lagi.",
  ui_story_5028_50281201_9_dialog_content = "Apa? Apa yang baru saja dikatakan?",
  ui_story_5028_50281201_10_dialog_content = "<color=#e8d9bb>Toot-toot</color>",
  ui_story_5028_50281201_11_dialog_content = "Itu... penyusup!",
  ui_story_5028_50281201_12_dialog_content = "Dari barat laut!",
  ui_story_5028_50281201_13_dialog_content = "Ayo pergi!",
  ui_story_5028_50281201_14_dialog_content = "Fiuh... Dimana mereka?",
  ui_story_5028_50281201_15_dialog_content = "Persetan? Tidak ada apa-apa di sini...",
  ui_story_5028_50281201_16_dialog_content = "<color=#e8d9bb>Tot-tot, tot—</color>",
  ui_story_5028_50281201_17_dialog_content = "Apa? Itu sinyal untuk sarapan?",
  ui_story_5028_50281201_18_dialog_content = "Apakah ada yang salah dengan sistem sinyal? Siapa yang melakukan itu?",
  ui_story_5028_50281201_19_dialog_content = "Besar! Langkah pertama dari rencana induk saya adalah sukses besar!",
  ui_story_5028_50281201_20_dialog_content = "Hal baik Revy mengambil buku sinyal bandit...",
  ui_story_5028_50281201_21_dialog_content = "Dan Peko Rabbit telah berhasil memakannya!",
  ui_story_5028_50281201_22_dialog_content = "Peko peko!",
  ui_story_5028_50281201_23_dialog_content = "Semuanya terserah padamu sekarang, Caelestite!",
  ui_story_5028_50281201_24_dialog_content = "Saya tidak terlalu nyaman dengan ini, tetapi setelah mengalami begitu banyak nyaris celaka...",
  ui_story_5028_50281201_25_dialog_content = "Saya pikir kemampuan melarikan diri saya telah meningkat pesat!",
  ui_story_5028_50281201_26_dialog_content = "Hei, kamu bandit bodoh! Temui aku!",
  ui_story_5028_50281201_27_dialog_content = "Apa itu? Seorang tawanan melarikan diri!",
  ui_story_5028_50281201_28_dialog_content = "Tahan di sana!",
  ui_story_5028_50281201_29_dialog_content = "Uh?",
  ui_story_5028_50281201_30_dialog_content = "Ini cara lari—dekat dengan habitat asli Kyllos.",
  ui_story_5028_50281201_31_dialog_content = "Soroz berhenti di sekitar sini ketika dia mencari Gary, dan...",
  ui_story_5028_50281201_32_dialog_content = "Orang yang mengejar Soroz itu masih di sini!",
  ui_story_5028_50281201_33_dialog_content = "*Gemuruh*",
  ui_story_5028_50281201_34_dialog_content = "Lihat ke sana!",
  ui_story_5028_50281201_35_dialog_content = "Apa apaan? Drakolion lain?",
  ui_story_5028_50281201_36_dialog_content = "Mengaum!!!",
  ui_story_5028_50281201_37_dialog_content = "Urgh—!",
  ui_story_5028_50281201_38_dialog_content = "Cepat, laporkan ke bos!",
  ui_story_5028_50281201_39_dialog_content = "Benar, oke!",
  ui_story_5028_50281201_40_dialog_content = "Aneh. Drakolion baru saja terbang. Dan kenapa masih gelap?",
  ui_story_5028_50281201_41_dialog_content = "Aduh!",
  ui_story_5028_50281201_42_dialog_content = "Hai hai! Hai!",
  ui_story_5028_50281201_43_dialog_content = "Besar! Lain kali Anda tidak perlu makan batu sebesar itu...",
  ui_story_5028_50281201_44_dialog_content = "Siapa itu yang memanggil? Apa yang terjadi?",
  ui_story_5028_50281201_45_dialog_content = "Ah!",
  ui_story_5028_50281201_46_dialog_content = "Hallo!",
  ui_story_5028_50281201_47_dialog_content = "Apakah ini semacam lelucon? Apa? Tanah tiba-tiba licin?",
  ui_story_5028_50281201_48_dialog_content = "Kacau!",
  ui_story_5028_50281201_49_dialog_content = "Apa apaan?",
  ui_story_5028_50281201_50_dialog_content = "Bagaimana saya ... sangat lelah ...",
  ui_story_5028_50281201_51_dialog_content = "Fiuh...",
  ui_story_5028_50281201_52_dialog_content = "Rencananya berjalan dengan baik.",
  ui_story_5028_50281201_53_dialog_content = "Mereka mengikat para bandit.",
  ui_story_5028_50281201_54_dialog_content = "Tidak buruk. Saya hampir terkesan.",
  ui_story_5028_50281201_55_dialog_content = "Yah, kau tahu, bagaimanapun juga, Fia adalah muridku, jadi yang terbaik adalah yang diharapkan.",
  ui_story_5028_50281201_56_dialog_content = "Bagaimana saya bisa tidak berhasil ketika saya seorang ahli ekstrozoologi profesional?",
  ui_story_5028_50281201_57_dialog_content = "Bahkan tidak ada satu pun bandit yang datang.",
  ui_story_5028_50281201_58_dialog_content = "Sebentar, PlayerName. Aku akan membuka kandang dan melepaskanmu.",
  ui_story_5028_50281201_59_dialog_content = "Fiuh. Itu benar-benar baik dari Anda.",
  ui_story_5028_50281201_60_dialog_content = "Lihat!",
  ui_story_5028_50281201_61_dialog_content = "Kyllo saya! Luar biasa, Anda tidak terluka!",
  ui_story_5028_50281201_62_dialog_content = "Tahap pertama dari rencana kami adalah sukses yang menakjubkan.",
  ui_story_5028_50281201_63_dialog_content = "Sekarang saatnya untuk menemukan dan menghentikan Gary.",
  ui_story_5028_50281201_64_dialog_content = "Fi.",
  ui_story_5028_50281201_65_dialog_content = "Kenapa kau menatapku seperti itu?",
  ui_story_5028_50281201_66_dialog_content = "Berhenti memandang rendah saya!",
  ui_story_5028_50281201_67_dialog_content = "Aku tidak bermaksud begitu!",
  ui_story_5028_50281201_68_dialog_content = "Pada akhirnya, Anda masih anak-anak.",
  ui_story_5028_50281201_69_dialog_content = "Aku bilang, aku tidak!",
  ui_story_5028_50281201_70_dialog_content = "Anda harus memanggil saya seorang extrozoologist!",
  ui_story_5028_50281201_71_dialog_content = "Baik. Sedikit judul yang panjang, jika Anda bertanya kepada saya, dan sulit untuk diingat.",
  ui_story_5028_50281201_72_dialog_content = "Kenapa kamu...!",
  ui_story_5028_50281201_73_dialog_content = "Bagaimanapun, tindakan Anda telah membuktikan bahwa Anda lebih dari setara dengan gelar semacam itu.",
  ui_story_5028_50281201_74_dialog_content = "Anda sudah ... dewasa.",
  ui_story_5028_50281201_75_dialog_content = "Hah?",
  ui_story_5028_50281201_76_dialog_content = "Anda ... memuji saya?",
  ui_story_5028_50281201_77_dialog_content = "Saya mungkin tidak selalu mengetahui detailnya, tetapi saya memiliki bakat yang nyata!",
  ui_story_5028_50281201_78_dialog_content = "Dan saya bisa mengetahui apa saja tentang teman-teman saya!",
  ui_story_5028_50281201_79_dialog_content = "Hah! Sekarang Anda tahu saya seorang ahli ekstrozoologi yang sangat kuat!",
  ui_story_5028_50281201_80_dialog_content = "Jangan mendahului dirimu sendiri. Anda telah melakukannya dengan baik, tetapi saya tidak akan menganggap kita sama.",
  ui_story_5028_50281201_81_dialog_content = "Untuk itu, pertama-tama Anda harus ...",
  ui_story_5028_50281201_82_dialog_content = "Aku bertanya-tanya tentang apa semua kebisingan itu. Aku seharusnya tahu bahwa kamu, maaf, orang bodoh yang bertanggung jawab.",
  ui_story_5028_50281201_83_dialog_content = "Lihat!",
  ui_story_5028_50281201_84_dialog_content = "Orang jahat itu kembali!",
  ui_story_5028_50281201_85_dialog_content = "Apakah dia yang menculikmu, PlayerName?",
  ui_story_5028_50281201_86_dialog_content = "Betapa menyedihkannya dia untuk memesan Eclipsites.",
  ui_story_5028_50281201_87_dialog_content = "Hah? Saya tidak percaya Anda dan saya melihat sesuatu secara langsung, Genevieve.",
  ui_story_5028_50281201_88_dialog_content = "\"Mata-ke-mata\" sendiri!",
  ui_story_5028_50281201_89_dialog_content = "Apa yang mengerikan. Kita harus benar-benar membakar pangkalan ini menjadi abu.",
  ui_story_5028_50281201_90_dialog_content = "Astaga. Tidak mungkin. Benar-benar tidak.",
  ui_story_5028_50281201_91_dialog_content = "Tempat itu dipenuhi dengan Kyllos yang telah ditangkap Gary! Ini akan menjadi bencana bagi Kyllos!",
  ui_story_5028_50281201_92_dialog_content = "Apa ini? Lebih bodoh? Tidak diragukan lagi milikmu, tauge?",
  ui_story_5028_50281201_93_dialog_content = "Jangan panggil aku tauge!",
  ui_story_5028_50281201_94_dialog_content = "Mengapa kalian semua sangat ingin menyelamatkan orang-orang biadab ini?",
  ui_story_5028_50281201_95_dialog_content = "Mereka tidak kejam, mereka adalah teman dan sahabat kita!",
  ui_story_5028_50281201_96_dialog_content = "Sahabat? Ha ha! Tidak, mereka bukan teman. Mereka kejam.",
  ui_story_5028_50281201_97_dialog_content = "Anda pikir mereka adalah teman. Keyakinan Anda sepihak.",
  ui_story_5028_50281201_98_dialog_content = "Ketika keripik turun, binatang hanyalah binatang.",
  ui_story_5028_50281201_99_dialog_content = "Tunggu saja sampai Anda tidak memiliki nilai lebih untuk mereka. Mereka akan menyerang Anda dan mencabik-cabik Anda.",
  ui_story_5028_50281201_100_dialog_content = "Kamu gila! Anda orang gila yang jahat!",
  ui_story_5028_50281201_101_dialog_content = "Hei, nak.",
  ui_story_5028_50281201_102_dialog_content = "Nama saya Fia!",
  ui_story_5028_50281201_103_dialog_content = "Apa pun. Orang itu hanya orang gila. Siapa yang tahu apa yang memotivasi dia?",
  ui_story_5028_50281201_104_dialog_content = "Anda tidak dapat meyakinkan seseorang seperti itu tentang kesalahan cara mereka. Satu-satunya bujukan yang mereka mengerti adalah...",
  ui_story_5028_50281201_105_dialog_content = "Lanjutkan.",
  ui_story_5028_50281201_106_dialog_content = "Dulu...?",
  ui_story_5028_50281201_107_dialog_content = "Memaksa.",
  ui_story_5028_50281201_108_dialog_content = "Wow. Jawaban ini sangat Shira.",
  ui_story_5028_50281201_109_dialog_content = "Anda ingin bertarung saat itu?",
  ui_story_5028_50281201_110_dialog_content = "Hah! Luar biasa.",
  ui_story_5028_50281201_111_dialog_content = "Aku senang bisa mengalahkanmu, bukan sekali, tapi dua kali. Dan selamanya akan begitu.",
  ui_story_5028_50281201_112_dialog_content = "Graaah—!!",
  ui_story_5028_50281202_1_dialog_content = "Kyllo, tangkap dia!",
  ui_story_5028_50281202_2_dialog_content = "Lihat!",
  ui_story_5028_50281202_3_dialog_content = "Terlalu lambat dan canggung untuk seleraku.",
  ui_story_5028_50281202_4_dialog_content = "Gaaah!",
  ui_story_5028_50281202_5_dialog_content = "Revy, lindungi Fia!",
  ui_story_5028_50281202_6_dialog_content = "Aku tidak akan membiarkanmu lolos begitu saja!",
  ui_story_5028_50281202_7_dialog_content = "Pukulan cemeti!",
  ui_story_5028_50281202_8_dialog_content = "Bagaimana tentang itu? Teman saya menunjukkan satu atau dua hal?",
  ui_story_5028_50281202_9_dialog_content = "Berbuat salah...",
  ui_story_5028_50281202_10_dialog_content = "Anda memiliki trik yang cukup untuk menyelamatkan kulit Anda di medan perang.",
  ui_story_5028_50281202_11_dialog_content = "Saya harus mengatakan, para Aurorian ini telah memberi saya sedikit masalah, bukan?",
  ui_story_5028_50281202_12_dialog_content = "Bagaimana kalau kita mencoba ini?",
  ui_story_5028_50281202_13_dialog_content = "Cambuknya—itu <color=#FFB400>bersinar</color>!",
  ui_story_5028_50281202_14_dialog_content = "Hati-hati, semuanya!",
  ui_story_5028_50281202_15_dialog_content = "Lo... Lo...!",
  ui_story_5028_50281202_16_dialog_content = "Kyllo? Kyllo!",
  ui_story_5028_50281202_17_dialog_content = "peko...",
  ui_story_5028_50281202_18_dialog_content = "Anda psiko! Apa yang telah kau lakukan?!",
  ui_story_5028_50281202_19_dialog_content = "Semua dalam waktu yang baik, Nak.",
  ui_story_5028_50281202_20_dialog_content = "Sebentar lagi, Anda akan melihat teman-teman hewan menggemaskan Anda mengoyak perut Anda dari tubuh Anda!",
  ui_story_5028_50281202_21_dialog_content = "Mereka tidak akan pernah melakukan itu!",
  ui_story_5028_50281202_22_dialog_content = "Serang cambuknya!",
  ui_story_5028_50281202_23_dialog_content = "Saya tahu!",
  ui_story_5028_50281202_24_dialog_content = "Hai!",
  ui_story_5028_50281202_25_dialog_content = "Saya tidak percaya berapa banyak Eclipsites yang dia miliki di bawah ibu jarinya ...",
  ui_story_5028_50281202_26_dialog_content = "Hal yang hebat tentang Eclipsites adalah Anda dapat memiliki sebanyak yang Anda inginkan.",
  ui_story_5028_50281202_27_dialog_content = "Bahkan jika mereka semua mati, ada persediaan baru yang tak ada habisnya untuk mengisi tempat mereka.",
  ui_story_5028_50281202_28_dialog_content = "Semuanya, sekarang!",
  ui_story_5028_50281202_29_dialog_content = "<color=#e8d9bb>Lihat!</color>",
  ui_story_5028_50281202_30_dialog_content = "Apakah itu Kyllo-mu yang menangis?",
  ui_story_5028_50281202_31_dialog_content = "<color=#e8d9bb>Lo... Lo!</color>",
  ui_story_5028_50281202_32_dialog_content = "T-Tidak, tidak!",
  ui_story_5028_50281202_33_dialog_content = "Tangisan mereka datang dari sekitar kita!",
  ui_story_5028_50281202_34_dialog_content = "Ini tidak bagus...",
  ui_story_5028_50281202_35_dialog_content = "Dia tidak mengincar Kyllo milik Fia, tapi semua Kyllo yang ditawan di markasnya!",
  ui_story_5028_50281202_36_dialog_content = "Aduh Buyung. Ini tidak bagus.",
  ui_story_5028_50281202_37_dialog_content = "Kita tidak bisa hanya tinggal di sini. Seseorang harus menyelamatkan mereka!",
  ui_story_5028_50281202_38_dialog_content = "Shira!",
  ui_story_5028_50281202_39_dialog_content = "Hah?",
  ui_story_5028_50281202_40_dialog_content = "Anda menyebut diri Anda seorang ahli dalam binatang yang menakjubkan, bukan?",
  ui_story_5028_50281202_41_dialog_content = "Tapi kamu terluka. Jangan khawatir tentang pertempuran. Bawa saja mereka keluar dari sini!",
  ui_story_5028_50281202_42_dialog_content = "Anda berada di ambang kematian, namun yang dapat Anda pikirkan hanyalah teman-teman Kyllo Anda yang berharga?",
  ui_story_5028_50281202_43_dialog_content = "Sungguh mengherankan jika ada di antara Anda yang selamat sampai dewasa.",
  ui_story_5028_50281202_44_dialog_content = "Astaga! Mengaum!",
  ui_story_5028_50281202_45_dialog_content = "Waktu pertempuran, saudara-saudara!",
  ui_story_5028_50281202_46_dialog_content = "Ugh!",
  ui_story_5028_50281202_47_dialog_content = "Mari kita lihat berapa banyak yang bisa saya dapatkan kali ini, satu, dua, tiga ...",
  ui_story_5028_50281202_48_dialog_content = "Aku punya banyak.",
  ui_story_5028_50281202_49_dialog_content = "Terlalu lambat! Mereka akan segera membakar tempat itu.",
  ui_story_5028_50281202_50_dialog_content = "Apakah begitu? Kalau begitu mari kita lihat siapa di antara kita yang bisa mendapatkan paling banyak dalam waktu singkat!",
  ui_story_5028_50281202_51_dialog_content = "Lo, lo!",
  ui_story_5028_50281202_52_dialog_content = "Apakah Vic tidak pernah memberitahumu? Binatang buas yang menakjubkan takut padaku.",
  ui_story_5028_50281202_53_dialog_content = "Maka izinkan saya meyakinkan Anda, sebagai sesama ahli, itu akan segera menjadi sejarah kuno!",
  ui_story_5028_50281202_54_dialog_content = "Apa?",
  ui_story_5028_50281202_55_dialog_content = "Ayo, Drakolion!",
  ui_story_5028_50281202_56_dialog_content = "Mengaum-",
  ui_story_5028_50281202_57_dialog_content = "(Fia... memanggil Drakolion.)",
  ui_story_5028_50281202_58_dialog_content = "Grr...",
  ui_story_5028_50281202_59_dialog_content = "Maaf untuk memaksakan pada Anda, tapi bisa tolong...",
  ui_story_5028_50281202_60_dialog_content = "Bantu Shira menemukan binatang buas menakjubkan lainnya di hutan dan bawa mereka semua pergi dari sini!",
  ui_story_5028_50281202_61_dialog_content = "Shira!",
  ui_story_5028_50281202_62_dialog_content = "...",
  ui_story_5028_50281202_63_dialog_content = "(Shira perlahan mendekati Drakolion...)",
  ui_story_5028_50281202_64_dialog_content = "...!",
  ui_story_5028_50281202_65_dialog_content = "(Hebat. Itu menerima kehadirannya!)",
  ui_story_5028_50281202_66_dialog_content = "Itu nyata...",
  ui_story_5028_50281202_67_dialog_content = "Terima kasih, \"Ekstrozoologi Fia\"!",
  ui_story_5028_50281202_68_dialog_content = "Maka lakukanlah! Sekarang!",
  ui_story_5028_50281202_69_dialog_content = "Ha ha ha ha!",
  ui_story_5028_50281202_70_dialog_content = "Kenapa dia tertawa?",
  ui_story_5028_50281202_71_dialog_content = "Sulit untuk percaya betapa sekelompok nincompoops Anda.",
  ui_story_5028_50281202_72_dialog_content = "Memimpin beberapa binatang buas dan tauge di sini mencoba menghentikanku?",
  ui_story_5028_50281202_73_dialog_content = "Saya ingin meninggalkan yang terbaik sampai yang terakhir, tetapi saya hanya harus membuat pengecualian ...",
  ui_story_5028_50281202_74_dialog_content = "Mari saya tunjukkan mengapa saya tak terbendung.",
  ui_story_5028_50281202_75_dialog_content = "Tunjukan dirimu.",
  ui_story_5028_50281202_76_dialog_content = "lihat...",
  ui_story_5028_50281202_77_dialog_content = "Apakah itu suara Kyllo...?",
  ui_story_5028_50281202_78_dialog_content = "Kylo itu?",
  ui_story_5028_50281202_79_dialog_content = "Itu tidak cukup untuk membuatku takut!",
  ui_story_5028_50281202_80_dialog_content = "Lihat!",
  ui_story_5028_50281202_81_dialog_content = "Astaga—?!",
  ui_story_5028_50281202_82_dialog_content = "K-Kenapa semuanya terlihat seperti Eclipsites?",
  ui_story_5028_50281202_83_dialog_content = "Dan mengapa semuanya terdengar seperti Kyllos?",
  ui_story_5028_50281202_84_dialog_content = "Lo, lo! Lihat!",
  ui_story_5028_50281202_85_dialog_content = "Makhluk ini benar-benar adalah Kyllo yang sama tadi.",
  ui_story_5028_50281202_86_dialog_content = "Kekuatan terbesar Kyllos adalah <color=#FFB400>metamorfosis</color>.",
  ui_story_5028_50281202_87_dialog_content = "Dengan sedikit dorongan, Kyllo mana pun dapat berubah menjadi bentuk makhluk apa pun dan menggunakan kemampuan mereka.",
  ui_story_5028_50281202_88_dialog_content = "Bagaimana Anda meninggalkan sesuatu yang penting ini !?",
  ui_story_5028_50281202_89_dialog_content = "Eh, tidak terpikir olehku untuk menyebutkannya sampai sekarang. Juga saya tidak tahu Kyllos bisa menggunakan kemampuan ini ketika ketakutan.",
  ui_story_5028_50281202_90_dialog_content = "Pada akhirnya, Kyllos hanya akan menggunakannya untuk melindungi teman tepercaya.",
  ui_story_5028_50281202_91_dialog_content = "Ini sebenarnya lebih sulit dipercaya daripada yang saya harapkan ...",
  ui_story_5028_50281202_92_dialog_content = "Ini pasti bukan waktu yang tepat untuk tersenyum?",
  ui_story_5028_50281202_93_dialog_content = "Ini menakutkan! Bagaimana kita akan menghadapi ini?",
  ui_story_5028_50281202_94_dialog_content = "Ada baiknya Anda meminta saya untuk menjawabnya.",
  ui_story_5028_50281202_95_dialog_content = "Kyllos memiliki rasa kepercayaan dan loyalitas yang kuat. Menangkan kepercayaan mereka, dan dunia adalah tiram Anda.",
  ui_story_5028_50281202_96_dialog_content = "Dan tentu saja, satu-satunya yang bisa mengalahkan Kyllo adalah Kyllo lainnya.",
  ui_story_5028_50281301_1_dialog_content = "Lihat!",
  ui_story_5028_50281301_2_dialog_content = "Lo, lo!",
  ui_story_5028_50281301_3_dialog_content = "Sialan! Apa yang bisa kita lakukan melawan kekuatan Gary!",
  ui_story_5028_50281301_4_dialog_content = "Berjuang sebentar lagi, kenapa tidak? Bakar teror hari ini jauh di lubuk hatimu!",
  ui_story_5028_50281301_5_dialog_content = "... Dan kemudian saya akan dengan senang hati mengirim orang-orang kejam saya ke setiap sudut dan celah di seluruh Astra.",
  ui_story_5028_50281301_6_dialog_content = "Hahaha... Hahaha!",
  ui_story_5028_50281301_7_dialog_content = "Sampai jumpa.",
  ui_story_5028_50281301_8_dialog_content = "Sekarang, PlayerName!",
  ui_story_5028_50281301_9_dialog_content = "Gunakan kekuatan Anda untuk menunjukkan kepada Kyllos betapa Anda percaya dan percaya pada Fia!",
  ui_story_5028_50281301_10_dialog_content = "Hah? kekuatan saya?",
  ui_story_5028_50281301_11_dialog_content = "Anda tahu, hal mental yang Anda lakukan. Ayo, pikirkan!",
  ui_story_5028_50281301_12_dialog_content = "(Kekuatanku...)",
  ui_story_5028_50281301_13_dialog_content = "(Satu-satunya kekuatan saya adalah kemampuan psikis, dan itu hanya membantu orang berbicara satu sama lain.)",
  ui_story_5028_50281301_14_dialog_content = "(Bicara satu sama lain tapi... Fia tidak punya cara untuk berkomunikasi dengan Kyllo?!)",
  ui_story_5028_50281301_15_dialog_content = "Sederhananya, cobalah untuk merasakan pikiran dan perasaan Kyllo dan mentransfernya ke Fia.",
  ui_story_5028_50281301_16_dialog_content = "Fia akan menangani sisanya!",
  ui_story_5028_50281301_17_dialog_content = "Hah? Bisakah saya merasakan pikiran Kyllo?",
  ui_story_5028_50281301_18_dialog_content = "Tentu saja Anda bisa. Jangan pernah lupa bahwa Anda seorang Caelestit!",
  ui_story_5028_50281301_19_dialog_content = "Oke, saya akan mencobanya!",
  ui_story_5028_50281301_20_option_content = "Angkatan Meningkatkan!",
  ui_story_5028_50281301_21_dialog_content = "Aku perlu merasakan pikiran Kyllo...",
  ui_story_5028_50281301_22_dialog_content = "Lo, lo! Lihat!",
  ui_story_5028_50281301_23_dialog_content = "Ini sangat takut. Ada beberapa kekuatan yang belum digunakan dan... sepertinya diblokir untuk menggunakannya.",
  ui_story_5028_50281301_24_dialog_content = "Lihat! Lihat!",
  ui_story_5028_50281301_25_dialog_content = "Saya merasakan emosi yang menurut saya berarti Anda ingin melindungi sesuatu?",
  ui_story_5028_50281301_26_dialog_content = "Melindungi sesuatu? Melindungi?",
  ui_story_5028_50281301_27_dialog_content = "Fi! Kyllo ingin melindungimu!",
  ui_story_5028_50281301_28_dialog_content = "Apa?!",
  ui_story_5028_50281301_29_dialog_content = "Lo, lo! Lihat!",
  ui_story_5028_50281301_30_dialog_content = "Apakah itu mengatakan ingin melindungiku?",
  ui_story_5028_50281301_31_dialog_content = "Lo, lo! Lo, lo!",
  ui_story_5028_50281301_32_dialog_content = "Saya pikir itu setuju dengan apa yang Anda pikirkan, dan itu benar-benar cemas!",
  ui_story_5028_50281301_33_dialog_content = "Dia benar-benar cemas... dan dia setuju...",
  ui_story_5028_50281301_34_dialog_content = "Jadi itu artinya tangisan itu?",
  ui_story_5028_50281301_35_dialog_content = "Saya menemukan jawabannya! Saya akhirnya menemukan jawabannya!",
  ui_story_5028_50281301_36_dialog_content = "Menemukannya? Tahu apa?",
  ui_story_5028_50281301_37_dialog_content = "Berkatmu, aku akhirnya mengerti apa arti tangisan Kyllo.",
  ui_story_5028_50281301_38_dialog_content = "Dengan kata lain, saya telah memecahkan kode bahasa Kyllos!",
  ui_story_5028_50281301_39_dialog_content = "Anda melakukannya?",
  ui_story_5028_50281301_40_dialog_content = "Lo, lo, lo! Lo, lo!",
  ui_story_5028_50281301_41_dialog_content = "A-Apa yang dikatakan...?",
  ui_story_5028_50281301_42_dialog_content = "Itu mengatakan, \"Saya ingin melindungi Fia.\"",
  ui_story_5028_50281301_43_dialog_content = "Lihat!",
  ui_story_5028_50281301_44_dialog_content = "Hah? Kyllo, apakah Anda mengatakan berbicara dengan saya telah memberi Anda kekuatan baru?",
  ui_story_5028_50281301_45_dialog_content = "Kemudian gunakan!",
  ui_story_5028_50281301_46_dialog_content = "Wow, Kyllo bersinar!",
  ui_story_5028_50281301_47_dialog_content = "Kyllo berubah bentuk...",
  ui_story_5028_50281301_48_dialog_content = "Fia dan Kyllo, gunakan kekuatan barumu untuk mengalahkan Gary!",
  ui_story_5028_50281301_49_dialog_content = "Terima kasih atas komentarnya. Kami mengerti!",
  ui_story_5028_50281301_50_dialog_content = "Anda pikir Anda bisa mengalahkan saya? Anda pasti sedang bermimpi.",
  ui_story_5028_50281301_51_dialog_content = "Pergilah, makhluk-makhlukku. Hancurkan mereka!",
  ui_story_5028_50281301_52_dialog_content = "*Gemuruh*",
  ui_story_5028_50281301_53_dialog_content = "Lihat!",
  ui_story_5028_50281302_1_dialog_content = "Pergi, Kyllo, dan ajari orang jahat ini agar kita tidak diganggu!",
  ui_story_5028_50281302_2_dialog_content = "Lihat!",
  ui_story_5028_50281302_3_dialog_content = "H-Bagaimana?",
  ui_story_5028_50281302_4_dialog_content = "Lihat! Lo, lo, lo!",
  ui_story_5028_50281302_5_dialog_content = "Kyllo Gary menangis kesakitan.",
  ui_story_5028_50281302_6_dialog_content = "Kyllo...",
  ui_story_5028_50281302_7_dialog_content = "Kyllo! Pergi untuk cambuk Gary!",
  ui_story_5028_50281302_8_dialog_content = "Lihat!!!",
  ui_story_5028_50281302_9_dialog_content = "Ugh!",
  ui_story_5028_50281302_10_dialog_content = "Sekarang waktunya!",
  ui_story_5028_50281302_11_dialog_content = "Melihat!",
  ui_story_5028_50281302_12_dialog_content = "Membakar!",
  ui_story_5028_50281302_13_dialog_content = "Pukulan cemeti!",
  ui_story_5028_50281302_14_dialog_content = "Eclipsites semuanya dikalahkan!",
  ui_story_5028_50281302_15_dialog_content = "Aku punya musuh terakhir. Jadi benar-benar itu adalah kemenangan saya.",
  ui_story_5028_50281302_16_dialog_content = "Anda berhasil menjejalkan sedikit tembakan di sana, sayangku Genevieve.",
  ui_story_5028_50281302_17_dialog_content = "Tapi sungguh, orang terakhir itu milikku.",
  ui_story_5028_50281302_18_dialog_content = "Anda hanya memukulnya dengan cambuk Anda di akhir, saya pikir.",
  ui_story_5028_50281302_19_dialog_content = "Kami membawa mereka semua keluar?",
  ui_story_5028_50281302_20_dialog_content = "Apakah kita melakukannya...?",
  ui_story_5028_50281302_21_dialog_content = "Lihat!",
  ui_story_5028_50281302_22_dialog_content = "Ya!",
  ui_story_5028_50281302_23_dialog_content = "Menjijikan...",
  ui_story_5028_50281302_24_dialog_content = "Semua Kyllos telah dibebaskan dari kendali Gary!",
  ui_story_5028_50281302_25_dialog_content = "PlayerName, gunakan kekuatanmu untuk menyampaikan pikiran Fia kepada Kyllo lain seperti yang kamu lakukan sebelumnya!",
  ui_story_5028_50281302_26_dialog_content = "Oke!",
  ui_story_5028_50281302_27_option_content = "Angkatan Meningkatkan!",
  ui_story_5028_50281302_28_dialog_content = "Anda sesama Kyllo?",
  ui_story_5028_50281302_29_dialog_content = "Anda tidak perlu takut dengan pria jahat itu lagi!",
  ui_story_5028_50281302_30_dialog_content = "Kami membebaskanmu dari kendalinya. Dia tidak akan pernah bisa memaksa Anda untuk melakukan sesuatu yang tidak ingin Anda lakukan lagi!",
  ui_story_5028_50281302_31_dialog_content = "Anda tidak perlu berjuang lagi. Datang dan bergabunglah dengan kami.",
  ui_story_5028_50281302_32_dialog_content = "Saya seorang extrozoologist, dan saya akan melindungi Anda.",
  ui_story_5028_50281302_33_dialog_content = "Lo... Lo?",
  ui_story_5028_50281302_34_dialog_content = "Lihat!",
  ui_story_5028_50281302_35_dialog_content = "Jangan khawatir. Aku tidak seperti orang jahat di sana. Aku akan menjagamu dengan baik.",
  ui_story_5028_50281302_36_dialog_content = "...",
  ui_story_5028_50281302_37_dialog_content = "Aduh Buyung. Kekejaman Gary adalah semua yang pernah diketahui Kyllo. Saya khawatir itu mendorongnya ke titik puncak psikologis!",
  ui_story_5028_50281302_38_dialog_content = "Kita harus segera pergi dari sini. Butuh waktu untuk mengajarinya cara hidup yang lain.",
  ui_story_5028_50281302_39_dialog_content = "Saya tidak akan membiarkan impian saya tentang keadilan, balas dendam, gagal karena sekelompok orang bodoh seperti Anda!",
  ui_story_5028_50281302_40_dialog_content = "Menyerah padaku, kau binatang!",
  ui_story_5028_50281302_41_dialog_content = "Waktu istirahat sudah habis!",
  ui_story_5028_50281302_42_dialog_content = "Lo... Lo...!",
  ui_story_5028_50281302_43_dialog_content = "Kyllo baru saja terus-menerus menangis kesakitan, bukan?",
  ui_story_5028_50281302_44_dialog_content = "Hentikan, Gar!",
  ui_story_5028_50281302_45_dialog_content = "Apakah Anda akan menyiksanya?",
  ui_story_5028_50281302_46_dialog_content = "Menyiksanya?",
  ui_story_5028_50281302_47_dialog_content = "Ide yang bagus!",
  ui_story_5028_50281302_48_dialog_content = "Bagaimana lagi itu akan membuatku takut?",
  ui_story_5028_50281302_49_dialog_content = "Dan jika itu tidak membuat saya takut, bagaimana saya bisa menggunakan kekuatan terbesarnya?",
  ui_story_5028_50281302_50_dialog_content = "Sekarang gunakan semua kekuatanmu untuk menghancurkan mereka!",
  ui_story_5028_50281302_51_dialog_content = "Atau Anda akan tahu rasa sakit yang sebenarnya di tangan saya!",
  ui_story_5028_50281302_52_dialog_content = "Lo, lo! Lihat!",
  ui_story_5028_50281302_53_dialog_content = "Lihat!",
  ui_story_5028_50281302_54_dialog_content = "Oh tidak? Apa yang kita lakukan? Itu berteriak minta tolong!",
  ui_story_5028_50281302_55_dialog_content = "Haruskah kita mengalahkannya lagi?",
  ui_story_5028_50281302_56_dialog_content = "Lihat!",
  ui_story_5028_50281302_57_dialog_content = "Hentikan, Fia!",
  ui_story_5028_50281302_58_dialog_content = "Kyllo sangat lemah sekarang. Itu tidak akan bertahan dari serangan lain.",
  ui_story_5028_50281302_59_dialog_content = "Nah, lalu menurut Anda apa yang harus kita lakukan, Guru?",
  ui_story_5028_50281302_60_dialog_content = "Dengan Kyllo sejauh itu, saya pikir itu benar-benar tergantung pada nasib dan keberuntungan.",
  ui_story_5028_50281302_61_dialog_content = "Saya menolak untuk mempercayainya. Saya telah belajar untuk tidak mempercayai Anda!",
  ui_story_5028_50281302_62_dialog_content = "Ha ha! Berdoalah untuk keberuntungan saat itu. Itu harapan terakhirmu.",
  ui_story_5028_50281302_63_dialog_content = "Sekarang saatnya untuk—",
  ui_story_5028_50281302_64_dialog_content = "Sejujurnya aku tidak tahan berkelahi. Ini adalah bagian terburuk dari ini.",
  ui_story_5028_50281302_65_dialog_content = "Darimana itu datang?!",
  ui_story_5028_50281302_66_dialog_content = "Tapi ada yang lebih baik daripada membiarkan orang sepertimu bebas!",
  ui_story_5028_50281302_67_dialog_content = "Mengaum!!!",
  ui_story_5028_50281302_68_dialog_content = "Ah! Bagaimana kau...",
  ui_story_5028_50281302_69_option_content = "Itu beruntung... Itu berubah menjadi Shira!",
  ui_story_5028_50281302_70_option_content = "Shira membanting ke tanah dan mengirim Gary terbang dengan tendangan!",
  ui_story_5028_50281302_71_dialog_content = "Tidak ada hubungannya dengan keberuntungan sama sekali.",
  ui_story_5028_50281302_72_dialog_content = "Hanya transformasi kualitatif dari semua usaha saya sampai sekarang.",
  ui_story_5028_50281302_73_dialog_content = "Shira!",
  ui_story_5028_50281302_74_dialog_content = "Beruntung aku memiliki pandangan ke depan untuk memberitahu Drakolion untuk membantu Shira menyelamatkan yang lain.",
  ui_story_5028_50281302_75_dialog_content = "Itulah kunci untuk menghentikan rencana Gary!",
  ui_story_5028_50281302_76_dialog_content = "Dan saya siap untuk mengatakan betapa dewasanya Anda telah tumbuh ...",
  ui_story_5028_50281302_77_dialog_content = "lihat...",
  ui_story_5028_50281302_78_dialog_content = "Uh?",
  ui_story_5028_50281302_79_dialog_content = "Lo, lo?!",
  ui_story_5028_50281302_80_dialog_content = "Saya tidak bisa membayangkan siksaan yang dialami makhluk malang ini di bawah kepemimpinan Gary.",
  ui_story_5028_50281302_81_dialog_content = "Mengapa kita tidak memberikannya istirahat?",
  ui_story_5028_50281302_82_dialog_content = "Apa yang akan kita lakukan dengan Tuan Public Enemy Nomor Satu?",
  ui_story_5028_50281302_83_dialog_content = "*Batuk*... Ugh!",
  ui_story_5028_50281302_84_dialog_content = "(Shira mengangkat Gary dengan salah satu tentakelnya dan membawanya ke atas.)",
  ui_story_5028_50281302_85_dialog_content = "(Dia tampak penuh dengan amarah yang membunuh.)",
  ui_story_5028_50281302_86_dialog_content = "(Dia menakutkan!)",
  ui_story_5028_50281302_87_dialog_content = "Lo, lo, lo...",
  ui_story_5028_50281302_88_dialog_content = "Eh... Sepertinya... Aku sudah... dikalahkan akhirnya...",
  ui_story_5028_50281302_89_dialog_content = "Anda sebaiknya membunuh saya.",
  ui_story_5028_50281302_90_dialog_content = "Mungkin sudah takdirku untuk mati di tangan orang-orang biadab ini.",
  ui_story_5028_50281302_91_dialog_content = "Dia terlalu berbahaya untuk hidup.",
  ui_story_5028_50281302_92_dialog_content = "Saya pikir, untuk kebaikan yang lebih besar, kita harus...",
  ui_story_5028_50281302_93_dialog_content = "Kubilang kita dengar dulu dari arsitek utama kita tentang kesuksesan hari ini—mari kita dengar pendapatmu, Fia. Menurutmu apa yang harus kita lakukan padanya?",
  ui_story_5028_50281302_94_dialog_content = "...",
  ui_story_5028_50281302_95_dialog_content = "Fi?",
  ui_story_5028_50281302_96_dialog_content = "Jelas, kita harus membiarkan orang jahat ini membusuk di penjara karena kejahatannya!",
  ui_story_5028_50281302_97_dialog_content = "Hah?",
  ui_story_5028_50281302_98_dialog_content = "Hah? Membusuk di penjara?",
  ui_story_5028_50281302_99_dialog_content = "Jangan berpikir aku akan berhenti merencanakan balas dendam setelah aku keluar.",
  ui_story_5028_50281302_100_dialog_content = "Dan kemudian saya, ahli ekstrozoologi Fia, harus menghentikan Anda lagi!",
  ui_story_5028_50281302_101_dialog_content = "Anda akan melihat betapa kuatnya binatang ajaib saya telah tumbuh di bawah perlindungan saya pada waktu itu—",
  ui_story_5028_50281302_102_dialog_content = "Itu akan menjadi hukuman terbesarmu!",
  ui_story_5028_50281302_103_dialog_content = "Bagus sekali. Sebuah pidato yang sangat mengesankan.",
  ui_story_5028_50281302_104_dialog_content = "Ya ampun! Anda terlihat seperti Shira. Tapi Anda seorang pria gurita?",
  ui_story_5028_50281302_105_dialog_content = "Ya ampun. Sungguh menyakitkan mendengarmu mengatakan itu.",
  ui_story_5028_50281302_106_dialog_content = "Kleken, apakah Anda berada di sini berarti bahwa Shadowlord ...?",
  ui_story_5028_50281302_107_dialog_content = "Waktunya tidak mungkin lebih sempurna, PlayerName. Anda memiliki di tangan Anda bandit yang dicari oleh Shadowlord.",
  ui_story_5028_50281302_108_dialog_content = "Mengingat betapa merepotkannya dia, akan lebih mengejutkan jika Shadowlord tidak tertarik.",
  ui_story_5028_50281302_109_dialog_content = "Benar sekali, nyonya.",
  ui_story_5028_50281302_110_dialog_content = "Gary, sepuluh tahun yang lalu istri dan anak Anda tersandung ke wilayah binatang yang menakjubkan, di mana mereka dengan sedih dibunuh oleh sekelompok binatang yang menakjubkan.",
  ui_story_5028_50281302_111_dialog_content = "Dan sejak hari itu Anda menyibukkan diri dengan membunuh dan menangkap segala jenis binatang yang menakjubkan.",
  ui_story_5028_50281302_112_dialog_content = "Jika Anda hanya membatasi diri Anda untuk itu, Shadowlord tidak akan terlibat.",
  ui_story_5028_50281302_113_dialog_content = "Tapi perilakumu baru-baru ini telah melewati batas yang bahkan mengancam Umbraton sendiri.",
  ui_story_5028_50281302_114_dialog_content = "Mengancam Umbraton? Pasti tidak...",
  ui_story_5028_50281302_115_dialog_content = "Memang, sayangku.",
  ui_story_5028_50281302_116_dialog_content = "Banyak binatang ajaib memilih untuk membuat tempat tinggal mereka di dekat Umbraton, dan merupakan komponen penting dari pertahanannya.",
  ui_story_5028_50281302_117_dialog_content = "Binatang-binatang itu mengusir segala ancaman berbahaya dari ekosistem mereka, termasuk Eclipsites.",
  ui_story_5028_50281302_118_dialog_content = "Kehadiran Eclipsite di dekat Umbraton telah mendorong para monster untuk membangun tembok tak berwujud yang memisahkan Aurorian dari ancaman Eclipsite.",
  ui_story_5028_50281302_119_dialog_content = "Tentu saja, hilangnya monster itu akan membuat Umbraton terkena serangan Eclipsite langsung.",
  ui_story_5028_50281302_120_dialog_content = "Jadi itu saja...",
  ui_story_5028_50281302_121_dialog_content = "Hah? Shadowlord？",
  ui_story_5028_50281302_122_dialog_content = "Jika Shadowlord begitu hebat dan kuat, mengapa dia tidak campur tangan bertahun-tahun yang lalu untuk melindungi istri dan anak saya?",
  ui_story_5028_50281302_123_dialog_content = "Pada akhirnya, bukankah kita semua hidup di bawah apa yang disebutnya \"hukum\"?",
  ui_story_5028_50281302_124_dialog_content = "Shadowlord menegakkan hukumnya di Umbraton, tetapi ini tidak berarti apa-apa tentang hutan.",
  ui_story_5028_50281302_125_dialog_content = "Pada akhirnya, penghormatan terhadap perintahnya membutuhkan manifestasinya.",
  ui_story_5028_50281302_126_dialog_content = "Bah! Hanya jika sesederhana itu.",
  ui_story_5028_50281302_127_dialog_content = "Gary.",
  ui_story_5028_50281302_128_dialog_content = "Apa? Anda memiliki beberapa kata bijak lagi?",
  ui_story_5028_50281302_129_dialog_content = "Atau apakah Anda ingin menembak saya sendiri untuk persahabatan kita yang berumur pendek?",
  ui_story_5028_50281302_130_dialog_content = "Apa pun. Saya tidak peduli. Saya tidak berubah pikiran tentang apa pun.",
  ui_story_5028_50281302_131_dialog_content = "Tidak ada yang bisa menghentikan saya. Tidak ada!",
  ui_story_5028_50281302_132_dialog_content = "... Tidak panggilan Anda untuk membuat.",
  ui_story_5028_50281302_133_dialog_content = "Melatih binatang buas yang menakjubkan untuk saling membunuh pada akhirnya dapat menyebabkan kepunahan semua kehidupan eksotis di planet ini...",
  ui_story_5028_50281302_134_dialog_content = "Bahkan jika Shadowlord tidak melakukan apa pun untuk menghentikanmu, orang lain, termasuk wanita ini, akan melakukannya menggantikannya.",
  ui_story_5028_50281302_135_dialog_content = "Gary.",
  ui_story_5028_50281302_136_dialog_content = "Apakah Anda tahu mengapa saya hanya memiliki satu sayap?",
  ui_story_5028_50281302_137_dialog_content = "Aku tidak tahu. Jadi?",
  ui_story_5028_50281302_138_dialog_content = "Hah?",
  ui_story_5028_50281302_139_option_content = "Mengapa?",
  ui_story_5028_50281302_140_dialog_content = "Saya perhatikan itu sejak pertama kali kita bertemu, tetapi Anda selalu mengabaikan topik itu.",
  ui_story_5028_50281302_141_dialog_content = "Saya sangat terpesona dengan binatang yang menakjubkan bahkan sebagai seorang anak. Saya senang bisa lebih dekat dan pribadi dengan mereka.",
  ui_story_5028_50281302_142_dialog_content = "Tapi saya tidak begitu mengerti bagaimana pikiran mereka bekerja saat itu. Jadi suatu kali saya akhirnya mengganggu binatang ajaib yang salah.",
  ui_story_5028_50281302_143_dialog_content = "Ia menyerang, merobek separuh sayapku dengan rahangnya, meninggalkanku dengan ini.",
  ui_story_5028_50281302_144_dialog_content = "Lihat apa yang bisa mereka lakukan? Dan tidakkah kamu marah diperlakukan seperti itu?",
  ui_story_5028_50281302_145_dialog_content = "Saya bingung dan marah sampai seorang teman menunjukkan sesuatu yang berbeda.",
  ui_story_5028_50281302_146_dialog_content = "Kami para Aurorian sama membingungkan dan tidak dapat dipahami oleh binatang-binatang menakjubkan seperti halnya mereka bagi kami.",
  ui_story_5028_50281302_147_dialog_content = "Naluri mereka menyuruh mereka untuk takut dan meragukan kita. Makhluk itu menyerang hanya untuk membela diri saat aku terlalu dekat.",
  ui_story_5028_50281302_148_dialog_content = "Dan bukankah itu juga yang terkadang kita lakukan terhadap mereka?",
  ui_story_5028_50281302_149_dialog_content = "Dari sudut pandang mereka, Aurorian cenderung keluar untuk berburu atau menangkap mereka, atau menyerang tanah mereka.",
  ui_story_5028_50281302_150_dialog_content = "Dan jika temanku tidak menggunakan kekuatan telepatinya untuk membantuku berkomunikasi dengan makhluk itu...",
  ui_story_5028_50281302_151_dialog_content = "Saya mungkin tidak akan pernah memiliki kesempatan untuk benar-benar mengetahui bagaimana perasaan mereka terhadap kami.",
  ui_story_5028_50281302_152_dialog_content = "Itulah kunci yang memungkinkan saya untuk memahami dan akhirnya memaafkan mereka.",
  ui_story_5028_50281302_153_dialog_content = "Kita tidak sama.",
  ui_story_5028_50281302_154_dialog_content = "Anda memutuskan untuk memaafkan mereka. Itu tidak mengatakan apa-apa tentang apa yang mereka pikirkan.",
  ui_story_5028_50281302_155_dialog_content = "Keluargaku dibunuh!",
  ui_story_5028_50281302_156_dialog_content = "Dan, seperti yang saya pahami, Anda mulai berburu mereka di hutan sendiri sesudahnya, benar?",
  ui_story_5028_50281302_157_dialog_content = "Benar. Aku membunuh banyak dari mereka. Tidak ada yang selamat.",
  ui_story_5028_50281302_158_dialog_content = "Jadi Anda membunuh pelakunya, benar-benar dan sepenuhnya membalas dendam. Jadi mengapa melanjutkan? Mengapa membuat eksotik lain mengalami nasib yang sama?",
  ui_story_5028_50281302_159_dialog_content = "Apalagi membuat mereka menjadi sasaran kampanye ketakutan yang ditujukan pada orang-orang Aurora.",
  ui_story_5028_50281302_160_dialog_content = "Jelas untuk menunjukkan kepada semua orang bahwa orang-orang biadab ini sama sekali tidak seperti Aurorian dan pantas untuk mati!",
  ui_story_5028_50281302_161_dialog_content = "Jika binatang ajaib itu benar-benar mengerikan seperti yang Anda pikirkan—",
  ui_story_5028_50281302_162_dialog_content = "Dan dengan sengaja menargetkan keluargamu, menghancurkan kebahagiaanmu dan setiap kesempatan untuk hidup normal...",
  ui_story_5028_50281302_163_dialog_content = "Lalu apa bedanya Anda—mengingat kampanye Anda untuk membantai mereka semua tanpa pandang bulu?",
  ui_story_5028_50281302_164_dialog_content = "...!",
  ui_story_5028_50281302_165_dialog_content = "Anda masih memiliki banyak tahun untuk hidup, teman lama saya. Saya harap Anda menggunakan sisanya untuk benar-benar memikirkan apa yang Anda lakukan.",
  ui_story_5028_50281302_166_dialog_content = "Saya tidak punya apa-apa lagi untuk ditambahkan, Tuan Gurita Misterius.",
  ui_story_5028_50281302_167_dialog_content = "Oh? Anda sudah selesai?",
  ui_story_5028_50281302_168_dialog_content = "Kalau begitu tolong dengarkan permintaanku.",
  ui_story_5028_50281302_169_dialog_content = "Baik. Saya akan sangat menghargai jika semua yang hadir bisa menyerahkan dia dan bawahannya ke Shadowlord.",
  ui_story_5028_50281302_170_dialog_content = "Shadowlord telah berjanji untuk memberikan hukuman kepada penjahat ini untuk melindungi keselamatan Umbraton.",
  ui_story_5028_50281302_171_dialog_content = "Sehubungan dengan hukuman penjara yang disebutkan Nyonya, saya akan melakukan yang terbaik untuk menyampaikan keinginannya kepada Shadowlord.",
  ui_story_5028_50281302_172_dialog_content = "Saya tidak keberatan. Bagaimana dengan kalian yang lain?",
  ui_story_5028_50281302_173_dialog_content = "Shadowlord mungkin tidak memiliki hasrat yang sama dengan kami untuk penelitian eksotis, tetapi dia ahli dalam hal menghukum penjahat.",
  ui_story_5028_50281302_174_dialog_content = "Akan sulit mendirikan penjara hanya untuknya.",
  ui_story_5028_50281302_175_dialog_content = "Saya yakin Shadowlord memiliki banyak tempat untuk mengancam masyarakat.",
  ui_story_5028_50281302_176_dialog_content = "Saya setuju.",
  ui_story_5028_50281302_177_dialog_content = "Selama dia menghabiskan waktu yang sangat lama di penjara, aku baik-baik saja!",
  ui_story_5028_50281302_178_option_content = "Anda memiliki keinginan Anda, Kleken.",
  ui_story_5028_50281302_179_option_content = "Tetap saja, terima kasih banyak.",
  ui_story_5028_50281302_180_dialog_content = "Kalau begitu, semuanya, bisakah aku meminta bantuanmu untuk membawa bandit ini kembali ke Umbraton bersamaku?",
  ui_story_5028_50281302_181_dialog_content = "Kamu ingin membantu? Oke, tentu.",
  ui_story_5028_50281302_182_dialog_content = "Oh tidak. Tugas membosankan lainnya.",
  ui_story_5028_50281302_183_dialog_content = "Saya tidak melihat bagaimana kami benar-benar dapat membantu? Kita harus memberikan makhluk lain di sini kepada seorang profesional atau sesuatu untuk membantu mereka.",
  ui_story_5028_50281302_184_dialog_content = "Ya!",
  ui_story_5028_50281302_185_dialog_content = "Aku akan kembali ke misiku kalau begitu. Selamat tinggal, semuanya.",
  ui_story_5028_50281302_186_dialog_content = "Saya hanya berharap kita tidak perlu melihat wajah sedihnya lagi.",
  ui_story_5028_50281302_187_dialog_content = "Yah, kurasa itu bukan yang terakhir kita melihat Gary.",
  ui_story_5028_50281401_1_dialog_content = "Akhir dari semua ketidaknyamanan sudah cukup untuk disyukuri.",
  ui_story_5028_50281401_2_dialog_content = "Saya terkesan betapa kuatnya Kyllos.",
  ui_story_5028_50281401_3_dialog_content = "Dan di sini saya pikir referensi Anda untuk tak terkalahkan hanyalah tipuan untuk menjebak Gary.",
  ui_story_5028_50281401_4_dialog_content = "Saya tidak akan pernah menipu mantan atau murid saya saat ini, baik itu Gary, Shira, atau Fia, murid saya yang terhormat.",
  ui_story_5028_50281401_5_dialog_content = "Dia tidak sengaja menipu.",
  ui_story_5028_50281401_6_dialog_content = "Begini, Shira sendiri yang mengatakannya.",
  ui_story_5028_50281401_7_dialog_content = "Masalah kredibilitasnya lebih tentang tidak dapat diandalkan daripada apa pun.",
  ui_story_5028_50281401_8_dialog_content = "Shira, itu membuatku sakit sampai menangis mendengarmu mengatakan itu...",
  ui_story_5028_50281401_9_dialog_content = "Tapi aku tidak mengerti bagaimana Kyllo-ku bisa memiliki semua kekuatan ini dan tidak menggunakannya sebelumnya—bahkan dalam bahaya?",
  ui_story_5028_50281401_10_dialog_content = "Tidak, tunggu—hal yang paling aneh adalah...",
  ui_story_5028_50281401_11_dialog_content = "Bagaimana kita menjelaskan kurangnya keberhasilan Master Vic yang menakjubkan mengingat semua binatang ajaib yang kuat ada di ujung jarinya?",
  ui_story_5028_50281401_12_dialog_content = "Benar. Itu benar-benar aneh!",
  ui_story_5028_50281401_13_dialog_content = "...",
  ui_story_5028_50281401_14_dialog_content = "Astaga... Biarkan aku.",
  ui_story_5028_50281401_15_dialog_content = "Kyllo adalah spesies yang sangat spesial dengan kemampuan yang sangat unik.",
  ui_story_5028_50281401_16_dialog_content = "Namun kemampuan ini hanya digunakan dalam percakapan dengan makhluk lain yang berbagi ikatan kepercayaan.",
  ui_story_5028_50281401_17_dialog_content = "Sayangnya, karena jumlah Kyllos telah berkurang, demikian juga kemampuan mereka untuk berkomunikasi satu sama lain.",
  ui_story_5028_50281401_18_dialog_content = "Dan mengingat berbagai karakteristik Kyllo yang luar biasa dan perbedaan dalam bahasa tubuh, hampir tidak mungkin bagi orang lain untuk mendapatkan pemahaman yang akurat.",
  ui_story_5028_50281401_19_dialog_content = "Itulah mengapa sangat sedikit Aurorian yang dapat berkomunikasi dengan Kyllos.",
  ui_story_5028_50281401_20_dialog_content = "Terkadang bahkan Kyllos sendiri berjuang untuk memahami arti tangisan satu sama lain.",
  ui_story_5028_50281401_21_dialog_content = "Semua ini telah sangat meningkatkan angka kematian bayi di antara Kyllos di alam liar.",
  ui_story_5028_50281401_22_dialog_content = "Faktanya, semua Kyllos yang Anda amati di habitat itu dibesarkan secara pribadi hingga dewasa oleh Vic.",
  ui_story_5028_50281401_23_dialog_content = "Apakah Guru itu brilian?",
  ui_story_5028_50281401_24_dialog_content = "Jadi jika Kyllos tidak dapat berkomunikasi dengan kita, bagaimana Guru mengetahui semua ini?",
  ui_story_5028_50281401_25_dialog_content = "Ada satu metode yang memungkinkan seseorang untuk memahami apa yang sebenarnya dan benar-benar dipikirkan Kyllo, dan itu adalah...",
  ui_story_5028_50281401_26_option_content = "Saya?",
  ui_story_5028_50281401_27_dialog_content = "Secara khusus, kemampuan psikis Caelestites.",
  ui_story_5028_50281401_28_option_content = "Caelestit...?",
  ui_story_5028_50281401_29_dialog_content = "Ya.",
  ui_story_5028_50281401_30_dialog_content = "Kemampuan psikis Caelestites mampu secara langsung menjembatani hambatan bahasa dan memahami pikiran Kyllos.",
  ui_story_5028_50281401_31_dialog_content = "Pemahaman ini membentuk kunci untuk memecahkan kode hubungan antara tangisan dan pikiran Kyllo dan kemudian bahasa itu sendiri.",
  ui_story_5028_50281401_32_dialog_content = "Saat itulah saya akhirnya menemukan bakat khusus Anda, Fia, ketika Anda bisa memahaminya begitu cepat.",
  ui_story_5028_50281401_33_dialog_content = "Dan itulah mengapa tugas pertama yang diberikan Tuanku adalah menangkap seorang Caelestit, kan?",
  ui_story_5028_50281401_34_dialog_content = "Benar. \"Komunikasi\" adalah faktor yang sangat penting yang diperlukan untuk membuka potensi Kyllo yang sebenarnya.",
  ui_story_5028_50281401_35_dialog_content = "Jadi kenapa aku bisa mengerti apa yang dikatakan Kyllo juga?",
  ui_story_5028_50281401_36_dialog_content = "Karena semua perjalanan Anda bersama, saya curiga Kyllo menganggap Anda sebagai teman.",
  ui_story_5028_50281401_37_dialog_content = "Tapi bagaimana Kyllo milik Gary menggunakan kekuatan yang sama?",
  ui_story_5028_50281401_38_dialog_content = "Saya tidak yakin.",
  ui_story_5028_50281401_39_dialog_content = "Saya menduga itu mungkin efek dari cambuk.",
  ui_story_5028_50281401_40_dialog_content = "Cambuk mengerikan itu mampu menaklukkan pikiran binatang buas yang menakjubkan dengan jejak yang mengerikan.",
  ui_story_5028_50281401_41_dialog_content = "Ketakutan adalah sama dan kebalikan dari cinta. Teror ekstrim Kyllo membuka metamorfosis yang mengerikan.",
  ui_story_5028_50281401_42_dialog_content = "Hmm. Itu bukan apa yang saya sebut \"komunikasi\"!",
  ui_story_5028_50281401_43_dialog_content = "Itu pasti sebabnya dia tidak bisa mengalahkanku, seorang ahli ekstrozoologi, dan mencapai hubungan nyata apa pun dengan Kyllo-nya!",
  ui_story_5028_50281401_44_dialog_content = "Apa menurutmu Vic menyadari semua ini selama ini?",
  ui_story_5028_50281401_45_dialog_content = "Belum tentu.",
  ui_story_5028_50281401_46_dialog_content = "Dia pernah punya teman Caelestit.",
  ui_story_5028_50281401_47_dialog_content = "Teman ini membantunya berhasil berkomunikasi dengan Kyllo, dan lebih memahami tentang makhluk luar biasa ini.",
  ui_story_5028_50281401_48_dialog_content = "Sampai tujuh belas tahun yang lalu.",
  ui_story_5028_50281401_49_dialog_content = "Tunggu, Vic selalu menggambarkan dirinya sebagai \"abad 18 tahun\"?",
  ui_story_5028_50281401_50_dialog_content = "Tepatnya berapa umurnya saat itu?",
  ui_story_5028_50281401_51_dialog_content = "Batuk, baiklah kalau begitu. Mari kita tidak menyelidiki masa lalu sepanjang hari, oke?",
  ui_story_5028_50281401_52_dialog_content = "Saya pikir kami memiliki beberapa hal yang adil untuk dilakukan di sini.",
  ui_story_5028_50281401_53_dialog_content = "Lihat! Lihat!",
  ui_story_5028_50281401_54_dialog_content = "Apa itu? Anda ingin saya melihatnya?",
  ui_story_5028_50281401_55_dialog_content = "Lo... Lo...",
  ui_story_5028_50281401_56_dialog_content = "Its... Situasinya telah memburuk dengan cepat.",
  ui_story_5028_50281401_57_dialog_content = "Aduh Buyung. Itu pasti akibat dari hidup di bawah rezim teror dan penderitaan yang begitu lama.",
  ui_story_5028_50281401_58_dialog_content = "Itu terluka parah dalam pertempuran barusan. Aku takut hidupnya akan hilang.",
  ui_story_5028_50281401_59_dialog_content = "Apakah ada orang di sini yang mampu menyembuhkannya dengan Luminatics?",
  ui_story_5028_50281401_60_dialog_content = "...",
  ui_story_5028_50281401_61_dialog_content = "Cepat! Sebaiknya kita mencari seseorang yang bisa membantu kita di Umbraton! Harus ada waktu!",
  ui_story_5028_50281401_62_dialog_content = "Drakolion, bantu kami!",
  ui_story_5028_50281401_63_dialog_content = "Tidak ada waktu, tidak ada waktu!",
  ui_story_5028_50281401_64_dialog_content = "Lihat!",
  ui_story_5028_50281401_65_dialog_content = "Hah? K-Kyllo?!",
  ui_story_5028_50281401_66_dialog_content = "Lihat! Lihat! Lihat!",
  ui_story_5028_50281401_67_dialog_content = "Mereka semua adalah Kyllos yang baru saja kulepaskan...",
  ui_story_5028_50281401_68_dialog_content = "Mereka datang kembali?",
  ui_story_5028_50281401_69_dialog_content = "Lihat! Lo, lo!",
  ui_story_5028_50281401_70_dialog_content = "Maksudmu, jika aku bisa berkomunikasi dengan mereka, mereka akan membantu kita?",
  ui_story_5028_50281401_71_dialog_content = "Oke, saya akan mencoba!",
  ui_story_5028_50281401_72_dialog_content = "Dengarkan aku, oh Kyllos, bantu kami menyelamatkannya!",
  ui_story_5028_50281401_73_dialog_content = "Bantu kami...",
  ui_story_5028_50281401_74_dialog_content = "Membantunya...",
  ui_story_5028_50281401_75_dialog_content = "Lihat!",
  ui_story_5028_50281401_76_dialog_content = "Lo, lo, lo!",
  ui_story_5028_50281401_77_dialog_content = "Ini adalah pendaran yang sama seperti yang mengelilingi Kyllo Fia dalam pertempuran!",
  ui_story_5028_50281401_78_dialog_content = "Anda sebaiknya duduk dan menonton.",
  ui_story_5028_50281401_79_dialog_content = "Anda mungkin berada dalam pengalaman sekali seumur hidup.",
  ui_story_5028_50281401_80_dialog_content = "Caelestite membantu Fia berkomunikasi dengan Kyllos untuk membuka kekuatan luar biasa mereka...",
  ui_story_5028_50281401_81_dialog_content = "Lo, lo, lo—",
  ui_story_5028_50281401_82_dialog_content = "Cahaya dari Kyllos menyelimuti Kyllo yang terluka...",
  ui_story_5028_50281401_83_dialog_content = "Lukanya—menyembuhkan!",
  ui_story_5028_50281401_83X_dialog_content = "Itulah betapa kuatnya Kyllo!",
  ui_story_5028_50281401_84_dialog_content = "Mampu meniru kemampuan binatang menakjubkan lainnya dan Aurorian...",
  ui_story_5028_50281401_85_dialog_content = "\"Luar Biasa\" tidak terlalu berlebihan.",
  ui_story_5028_50281401_86_dialog_content = "Sepertinya saya tidak jauh dari sasaran ketika saya mengatakan \"dunia akan menjadi tiram Anda.\"",
  ui_story_5028_50281401_87_dialog_content = "Saya mengerti...",
  ui_story_5028_50281401_88_option_content = "Luar biasa.",
  ui_story_5028_50281401_89_dialog_content = "Anda sendiri tidak terlalu buruk, PlayerName.",
  ui_story_5028_50281401_90_dialog_content = "Hah?",
  ui_story_5028_50281401_91_option_content = "aku sedikit cemburu...",
  ui_story_5028_50281401_92_dialog_content = "Saya akan melakukan pekerjaan yang jauh lebih baik untuk melindungi teman-teman saya jika saya memiliki kekuatan semacam itu ...",
  ui_story_5028_50281401_93_dialog_content = "Anda memiliki banyak kekuatan sebagaimana adanya—kekuatan komunikasi yang sempurna antara individu yang berbeda.",
  ui_story_5028_50281401_94_dialog_content = "Ini mungkin tidak banyak dalam pertempuran, tetapi jangan meremehkan kekuatan membantu orang memahami satu sama lain.",
  ui_story_5028_50281401_95_dialog_content = "Kekuatan untuk menghilangkan kesalahpahaman, mengurai kebencian lama, dan mencegah pecahnya pertengkaran sejak awal.",
  ui_story_5028_50281401_96_dialog_content = "Saya mengerti...",
  ui_story_5028_50281401_97_dialog_content = "Mengerti!",
  ui_story_5028_50281401_98_dialog_content = "Lihat, Kyllo tampaknya telah memulihkan kekuatannya.",
  ui_story_5028_50281401_99_dialog_content = "Lo... Lo?",
  ui_story_5028_50281401_100_dialog_content = "Anda sembuh!",
  ui_story_5028_50281401_101_dialog_content = "Semua orang yang bekerja bersama telah menyembuhkan Anda!",
  ui_story_5028_50281401_102_dialog_content = "Lo, lo! Lihat!",
  ui_story_5028_50281401_103_dialog_content = "Oh, dan juga terima kasih kepada ahli ekstrozoologi residen Anda!",
  ui_story_5028_50281401_104_dialog_content = "Lo, lo, lo!",
  ui_story_5028_50281401_105_dialog_content = "Wow! Haha, itu menggelitik!",
  ui_story_5028_50281401_106_dialog_content = "Bagaimanapun, saya pikir sudah lewat waktu kami pergi dan membawa makhluk-makhluk ini ke habitat yang jauh lebih cocok.",
  ui_story_5028_50281401_107_dialog_content = "Hah? Kyllo akan kembali?",
  ui_story_5028_50281401_108_dialog_content = "Lihat!",
  ui_story_5028_50281401_109_dialog_content = "Kau... Kau akan meninggalkanku, Kyllo?",
  ui_story_5028_50281401_110_dialog_content = "Anda tidak berpikir Anda bisa tinggal?",
  ui_story_5028_50281401_111_dialog_content = "lihat...",
  ui_story_5028_50281401_112_dialog_content = "Lo-woo!",
  ui_story_5028_50281401_113_dialog_content = "K-Menurutmu tidak? T-Tapi...",
  ui_story_5028_50281401_114_dialog_content = "Masih anak-anak, pada akhirnya.",
  ui_story_5028_50281401_115_dialog_content = "Seorang peneliti murni tidak hanya harus memahami tetapi juga menghormati kebiasaan naluriah dan keinginan makhluk yang mereka amati.",
  ui_story_5028_50281401_116_dialog_content = "Anda tidak bisa memaksakan kehendak Anda pada binatang yang menakjubkan.",
  ui_story_5028_50281401_117_dialog_content = "Aku bukan anak kecil!",
  ui_story_5028_50281401_118_dialog_content = "Lihat!",
  ui_story_5028_50281401_119_dialog_content = "Di Sini...",
  ui_story_5028_50281401_120_dialog_content = "Kekuatan Burung Hantu Lutumi. Anda berhasil... wow.",
  ui_story_5028_50281401_121_dialog_content = "Lihat! Lihat!",
  ui_story_5028_50281401_122_dialog_content = "Astaga. Anda pergi begitu cepat?",
  ui_story_5028_50281401_123_dialog_content = "Fia tidak akan senang ketika dia bangun setelah mengucapkan selamat tinggal kepada begitu banyak teman.",
  ui_story_5028_50281401_124_dialog_content = "Pastikan untuk menghiburnya. Hal-hal ini bisa sulit dan menjengkelkan.",
  ui_story_5028_50281401_125_dialog_content = "Saya tidak terlalu berpengalaman dengan anak-anak. Bolehkah saya mendesak murid saya yang terhormat untuk menangani yang satu ini?",
  ui_story_5028_50281401_126_dialog_content = "eh...",
  ui_story_5028_50281401_127_dialog_content = "Pastikan untuk saling menjaga dengan baik!",
  ui_story_5028_50281401_128_dialog_content = "Dan jauhi orang-orang yang terlihat seperti berita buruk.",
  ui_story_5028_50281401_129_dialog_content = "Lihat!",
  ui_story_5028_50281401_130_dialog_content = "Nah, itulah akhir ceritanya.",
  ui_story_5028_50281401_131_dialog_content = "Kyllo dan saudara-saudara mereka tinggal di hutan yang sama bahkan sampai hari ini.",
  ui_story_5028_50281401_132_dialog_content = "Gadis bernama Fia itu memang tumbuh menjadi ahli ekstrozoologi ternama.",
  ui_story_5028_50281401_133_dialog_content = "Akhir yang bagus untuk semua orang.",
  ui_story_5028_50281401_134_dialog_content = "Lalu apa yang terjadi?",
  ui_story_5028_50281401_135_dialog_content = "Bagaimanapun, Vice, biarkan aku istirahat dulu, ya?",
  ui_story_5028_50281401_136_dialog_content = "Saya telah membaca \"The Adventures of the Extrozoologist\" selama 3 jam penuh.",
  ui_story_5028_50281401_137_dialog_content = "Tenggorokanku semakin serak.",
  ui_story_5028_50281401_138_dialog_content = "Oh maaf. Anda sebaiknya istirahat itu.",
  ui_story_5028_50281401_139_dialog_content = "Tapi aku benar-benar masuk ke dalamnya! Kita tidak bisa berakhir di sini saja.",
  ui_story_5028_50281401_140_dialog_content = "Aku sangat ingin tahu apa yang terjadi selanjutnya.",
  ui_story_5028_50281401_141_dialog_content = "Atau Anda bisa bertanya kepada wanita yang menulis buku itu, dia harus—",
  ui_story_5028_50281401_142_dialog_content = "PlayerName!!!",
  ui_story_5028_50281401_143_dialog_content = "Lihat, itu dia!",
  ui_story_5028_50281401_144_dialog_content = "Saya ingin pergi mencari binatang yang menakjubkan besok di laut!",
  ui_story_5028_50281401_145_dialog_content = "Dan sebagai diri Anda yang eksotis, Caelestite, saya tidak akan menerima jawaban tidak!",
  ui_story_5028_50281401_146_dialog_content = "Baiklah baiklah. Sudah kubilang beberapa kali, bahwa aku bukan binatang yang menakjubkan...",
  ui_story_5028_50281401_147_dialog_content = "Anda menyangkalnya? Sayang sekali. Agak terlambat untuk itu sekarang.",
  ui_story_5028_50281401_148_dialog_content = "Dan, sebagai \"Guru ahli ekstrozoologi\" Anda, saya tidak bisa membiarkan Anda kabur begitu saja!",
  ui_story_5028_50281401_149_dialog_content = "Anda benar-benar ingin menumpang Soroz, bukan!",
  ui_story_5028_50281401_150_dialog_content = "Dan Drakolion itu sepertinya ikut juga!",
  ui_story_5028_50281401_151_dialog_content = "Anda harus memikirkan cara mengembalikannya ke tempat yang seharusnya!",
  ui_story_5028_50281401_152_dialog_content = "Percayalah, Soroz tidak akan memenuhi permintaan kemitraan apa pun!",
  ui_story_5028_50281401_153_dialog_content = "Bukankah aku bilang begitu? Drakolion akan kembali setelah musim kawin.",
  ui_story_5028_50281401_154_dialog_content = "Penghormatan terhadap binatang yang menakjubkan, kebiasaan dan harapan mereka, merupakan hal mendasar bagi ahli ekstrozoologi mana pun yang sepadan dengan garam mereka.",
  ui_story_5028_50281401_155_dialog_content = "Saya tidak akan memaksanya kembali, itu pasti!",
  ui_story_5028_50281401_156_dialog_content = "Bagus sekali—kali ini.",
  ui_story_5028_50281401_157_dialog_content = "Surga tahu berapa lama Anda akan menangis jika Kyllo tidak kembali!",
  ui_story_5028_50281401_158_dialog_content = "Permisi?",
  ui_story_5028_50281401_159_dialog_content = "Saya tidak ingat itu!",
  ui_story_5028_50281401_160_dialog_content = "Ayo! Akui!",
  ui_story_5028_50281401_161_dialog_content = "Hai!",
  ui_story_5028_50281401_162_dialog_content = "Kyllo, gigit dia!",
  ui_story_5028_50281401_163_dialog_content = "Lo—Oowoo!",
  ui_story_5028_50281401_164_dialog_content = "Grr!",
  ui_story_5028_50281401_165_dialog_content = "Kakiku!",
  ui_story_5028_50281401_166_dialog_content = "Ptui!",
  ui_story_5028_50281401_167_dialog_content = "Anda tidak bisa terlalu langsung dengan anak-anak, PlayerName.",
  ui_story_5028_50281401_168_dialog_content = "Vice, datang dan bantu aku!",
  ui_story_5028_50281401_169_dialog_content = "Bantu aku melepaskan Kyllo dari kakiku!",
  ui_story_5028_50281401_170_dialog_content = "Baiklah baiklah. Melepaskan PlayerName, Oke?",
  ui_story_5028_50281401_171_dialog_content = "Lihat!",
  ui_story_5028_50281401_172_dialog_content = "Hah! Ahli ekstrozoologi memiliki semua kekuatan, bukan?",
  ui_story_5028_50281401_173_dialog_content = "Kakiku... Ada bekas gigitan Kyllo!",
  ui_story_5028_50281401_174_dialog_content = "Tunggu. Kylo pergi. Saya ingat itu dengan jelas. Kenapa masih berkeliaran di sekitar Fia?",
  ui_story_5028_50281401_175_dialog_content = "Seorang ahli di bidang saya memiliki karisma luar biasa yang hanya sedikit yang Anda ketahui. Kyllo saya akhirnya kembali.",
  ui_story_5028_50281401_176_dialog_content = "Lo, lo, lo—lo!",
  ui_story_5028_50281401_177_dialog_content = "Oh? Apakah Kyllo mencoba memberi tahu kami sesuatu?",
  ui_story_5028_50281401_178_dialog_content = "Oh? Aku tidak begitu mengerti, Kyllo. Apa yang Anda katakan? Bisakah Anda mengulangi diri Anda sendiri?",
  ui_story_5028_50281401_179_dialog_content = "Lo, lo, lo...",
  ui_story_5028_50281401_180_dialog_content = "\"Karena aku mengkhawatirkan kesehatan Fia?\"",
  ui_story_5028_50281401_181_dialog_content = "\"Aku memikirkan hari-hari dimana Fia akan menangis tanpa kehadiranku...\"",
  ui_story_5028_50281401_182_dialog_content = "\"Saya sangat khawatir dengan kesehatannya sehingga saya harus kembali ...\"",
  ui_story_5028_50281401_183_dialog_content = "Apakah begitu?!",
  ui_story_5028_50281401_184_dialog_content = "Lihat! Lihat! Lihat!",
  ui_story_5028_50281401_185_dialog_content = "Ahhh! Kyllo!",
  ui_story_5028_50281401_186_dialog_content = "Hentikan!",
  ui_story_5028_50281401_187_dialog_content = "... Dan dengan itu kita harus menutup tirai kisah ini.",
  ui_story_5028_50281401_188_dialog_content = "... Mengingat tidak ada akhir dari banyak petualangan seorang ahli ekstrozoologi sejati."
}
return config
